/* 平成21年委員会データ（自動生成・分割ファイル） */
window.SHINAGAWA_DB.years.h21.committeeSessions.push(...[{"id":"h21-20090826-15","meetingId":"h21-cm08","date":"2009年8月26日","dateIso":"2009-08-26","committee":"環境対策特別委員会","time":"午後１時０３分～午後２時３８分","status":"正式会議録","sourceType":"formal","overview":"環境対策特別委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を29件抜き出しています。","hasFullText":true,"topics":[{"id":"topic-01","title":"水辺とみどりの整備","agenda":"水辺とみどりの整備","exchanges":[{"speaker":"林委員","kind":"質問","question":"個別にいろいろ説明をいただきましてありがとうあります。個別にまた後で質問したいと思うんだけれども、この水とみどりというものをかなり積極的に区として、新しいものも、あるいは古いものの整備も含めてやっていくということなんだけれども、予算的にはどういうふうに考えていらっしゃるのか。","respondent":"藤田水とみどりの課長","answer":"新たな考え方を入れる中での先ほども少し申し上げた緑の行動計画をつくるといった面での新たなといいますか、これまでの進めてきた施策を再構築していくような形での予算の調整ですとか、あるいは、公園づくりの中では。","voiceIndex":5,"id":"exchange-001"},{"speaker":"林委員","kind":"質問","question":"やっぱり長いスパンでみどりであったり水というものに取り組んでいくという課なんだから、そういう裏づけがされる、あるいは上限を決められてしまうと動きにくいということも言われるかもわからないけれども、財源についてのいわゆる課としての考え方を持つべきだろうなというふうに思うんですけれども、いかがですか。","respondent":"藤田水とみどりの課長","answer":"これまでも区の施策としては、例えば国庫補助や都からの補助、そういったようなものが活用できるようなものについては積極的に取りながら事業を進めていきたいということでやってきておりますので、きょうの委員からのお話も含めて。","voiceIndex":7,"id":"exchange-002"},{"speaker":"林委員","kind":"意見","question":"上がってきたときに、それはじゃあ早速具体的に検討に入りましょうというフットワークがあったほうが、みどりとか水というのはなかなか増やそうと思っても増やせない部分があると思うので、そういう段取りというか、一般的な言葉で申しわけないけれども、段取りだけは進めていっておいてほしいので、お願いしておきます。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":9,"id":"exchange-003"},{"speaker":"石田委員","kind":"質問・要望","question":"全体的に区民やＮＰＯ、各種団体や企業等と協働してやっていこうというような、そういうことが感じられるんですけれども、今現在、どのくらいの団体とか企業等と連携をとられて今まで行ってこられたのか。今後どういうような人たちを、町会とか学校関係とか、そういうものも記載されているんですが、どのような人たちを増やしていくのかというものの、展望と今の現状を教えていただきたい。","respondent":"藤田水とみどりの課長","answer":"今回のＮＰＯや区民、企業も含めまして、いろいろな面で協働しながら進めていきたいということで、先ほど申したものづくり、それからひとづくり、しくみづくり、情報発信も含めて、そういった中でさまざまな面で活用していきたいというふうに考えておりますけれども。","voiceIndex":10,"id":"exchange-004"},{"speaker":"南委員","kind":"質問","question":"やっぱり一定程度自治体としての基本的な部分の責任というのは外してはならない部分はあると思うので、その辺をどういうふうに考えて仕分けというんですか、そういうところをやっていこうとしているのか、その辺を伺いたいのが１つと、それからあと、みどり率ということで、さっき２３％とおっしゃったと思うんですけれども、３５ページのところのみどり率については、これは東京都の計画なんですけれども。","respondent":"藤田水とみどりの課長","answer":"基本的な責任を持っていろいろ対応するのはあくまでも区でありまして、そこの中で地域の方々がやりたい、例えばお花を植えたい、それから掃除をしたいというような活動に対してやっていただくということで。","voiceIndex":12,"id":"exchange-005"},{"speaker":"南委員","kind":"質問・要望","question":"自治体としての協働の部分の仕分けの部分ですけれども、当然そういう答弁だし、それ以外のものはあり得ないというふうに思うんですけれども、じゃあ、具体的に例えば場をつくる、場を守る、場を考える、そういうところで言うと、これは担い手の役割として活動実態の把握とか、要望・意見を抽出するとかというふうに、これは担い手の側だから、多分区民とか企業とかＮＰＯだとか。","respondent":"藤田水とみどりの課長","answer":"つくる場としては、実際に公園用地がある。そんなような形で、１つの今これは例えですが、連携を図りながら進めていきたいというふうに考えてあります。","voiceIndex":14,"id":"exchange-006"},{"speaker":"南委員","kind":"提案","question":"あんまりよくわからないのでごめんなさい。オレンジのジャケットを着て。この元なぎさ通りの緑道を新・みどりのネットワークづくりの中でやるという、そういう場を提供するに当たって、どういうふうに区民に協働というのを提案して、区民に公募も含めてしていこうとしているのか、ちょっとそういうことを知りたいなと思っています。","respondent":"藤田水とみどりの課長","answer":"大きなまちづくりの面では、いろいろなものづくりの観点がありますので、連携しながらやっていけるような先ほどの公園のワークショップ的な手法を用いながら進めることもありますし、そうではない場面では、地域の方々からアンケートをとったり、意見を聞いたりしながらつくると。","voiceIndex":16,"id":"exchange-007"},{"speaker":"南委員","kind":"質問","question":"いろいろな意見があるわけですから、そこをどう調整していくのかというところがやっぱり大事な部分なんだろうと思うので、しかし、十分時間をかけつつも、だらだらではなくて、しっかり十分に時間をかけながら自分たちのまちづくりをどういうふうにするかという、そこの角度を離さないでやっていくべきなんだろうなというふうに思うので、ちょっとまだあんまり事例がこういう点ではないから。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":18,"id":"exchange-008"},{"speaker":"伊藤委員","kind":"確認","question":"３４ページから、新・水とみどりのネットワークのこと、それから６７ページのところについて少しお伺いします。だから、そういう品川区ではない公の団体との調整をどうとっていくかということが１つと、それから、滝王子通りは拡幅計画がある。だから、そういう調整をどういうふうにとっていって、この構想を具体化しようとしているのかということをお伺いしたい。","respondent":"藤田水とみどりの課長","answer":"今、３４ページをお開きいただいていると思いますが、隣の３３ページのほうもあわせて見ていただきたいのですが、今回、水とみどりを全体的にとらえたときに、図にありますとおり、観光とか交流、環境、景観・アメニティ。","voiceIndex":21,"id":"exchange-009"},{"speaker":"伊藤委員","kind":"確認","question":"そうすると、じゃあ、山手通りとか、それから商店街、この中で３３ページに説明するのであれば、どういうところに当てはまっていくのでしょうかということのお答えと、それから、例えば山手通りの場合には、品川区が手の届くところと手の届かないところがあるはずですよね、国道だから。だから、そういう中で３３ページにどういうものを当てはめていくかということの確認をもう１つお願いします。","respondent":"藤田水とみどりの課長","answer":"すみません、全部お答えしなくて申しわけなかったんですが、山手通りのほうですけれども、現在、都市計画道路を整備するという意味での優先整備路線になっておりまして、中央環状品川線の工事の関連もあって、単純に今、拡幅工事がどんどん進んでいるというわけではありませんが。","voiceIndex":23,"id":"exchange-010"},{"speaker":"伊藤委員","kind":"意見","question":"つまり、もうちょっと幅広く考えたほうがいいということですね。水とみどりという言葉でとらえてしまうと、単純に木を増やすとか、そうとられてしまいがちなんだけれども、あくまで品川区として考えているのは、こういう場を４つの項目の中で当てはめていこうということを行うことを通して計画として水とみどりの施策として進めていくという考え方でよろしいんですね。","respondent":"岩田防災まちづくり事業部長","answer":"そういう面では、例えば商店街に街路樹を植えるわけにはまいりませんが、電線類の地中化が終わった後に、いわゆる商店街灯や、あるいは地中化のためのトランスを載せる街路灯の上にそういったお花をぶら下げてみたり、そういったいわゆるみどりに関するものをつけ加えながら。","voiceIndex":25,"id":"exchange-011"},{"speaker":"伊藤委員","kind":"質問","question":"もう１点だけですけれども、６７ページの計画の中に、さらに「旧東海道松の街道」という表現がありますね。６７ページ。松の街道。何年か前に建設委員会でたしかあったと思うんですけれども、ほとんど計画が動いていない。特に鈴ヶ森とか、東と南の地区ですか。","respondent":"藤田水とみどりの課長","answer":"そういった中で、委員ご指摘のとおり、旧東海道の松の街道というようなことで、特に北側のほうについては地域の皆さんとの連携事業の中で街道松ということで松が徐々に増えてきておりますが、なかなか南のほうは、今。","voiceIndex":27,"id":"exchange-012"},{"speaker":"伊藤委員","kind":"質問","question":"これで最後にしますけれども、構想は構想ですからいいんですけれども、それをやっぱり具体化していって計画を進めていく、現場がよくなっていかないことには構想が構想で終わってしまうわけですから、やはりお願いしたいのは、それがＰＤＣＡで出ていますので、必ずそれが進まないということをチェックして、品川区独自の対策をとって、着実に計画が進んでいただきますようにお願いいたします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":29,"id":"exchange-013"},{"speaker":"飯沼委員","kind":"質問・要望","question":"だから、もうちょっと、例えばみどりの道というのがどういうものなのか、あと、いこいのゾーンとか、新・いこいのゾーンとかが増えていますよね。この辺がイメージ的にどういうものなのか、もうちょっと教えていただきたいと思います。","respondent":"藤田水とみどりの課長","answer":"今回、新・いこいのゾーンというような書き方をしておりますが、この辺につきましては、例えば公園があまりないような地域もありますので、そういった中でも何とか公園用地を確保できないかとか。","voiceIndex":30,"id":"exchange-014"},{"speaker":"飯沼委員","kind":"質問・要望","question":"先ほど、みどり率のところなんですけれども、３５ページの緑被率からみどり率を取り上げるようになった経過というか、この辺の大もとの考え方は、どこが、国とか東京都が考えたと思うんですけれども、その大もとの考え方の違いというのがどう流れてこうなったのか、ちょっと聞きたいのと、緑被率というのは、今までと従来と変わりなく追求はされているということだと思うんですけれども。","respondent":"藤田水とみどりの課長","answer":"先ほどもありました防災機能を持った広場だとか、そういったようなものもこういった拠点の中の１つに位置づけられますので、そういった観点では進めていきたいというふうに考えてあります。それから、みどり率の考え方ですが、大もとは東京都のほうが示したものです。","voiceIndex":32,"id":"exchange-015"},{"speaker":"飯沼委員","kind":"質問","question":"今のところで、みどりだけではなくて水辺もというところでは、憩いや安らぎをもたらすというそういった環境的なものといろいろ含めて、その辺を入れてきたということは、それは重要であると思うんですけれども、私はやっぱり大もとのこのみどり率というものが取り上げられていく中で。","respondent":"久保田都市環境事業部長、藤田水とみどりの課長","answer":"最初のご質問の中で、みどりは大事だということ、それからみどりを増やすためには樹木をもっと増やしていく必要があるというようなお話ですけれども、みどりの大事さというのは全くそのとおりだと思うんですけれども。実態調査の今の現状ですが、その航空写真のほうは６月に撮影を終わりまして、現在、例えば大木、大きな樹木を実際に歩いて調査をする。","voiceIndex":34,"id":"exchange-016"},{"speaker":"飯沼委員","kind":"質問・要望","question":"私は目標がないと思っています、樹木に関しては。だから、そういった面では保存樹をなるべく援助をより多くして、大きな木を切らないようにしていく方向とかもしっかり示してほしいんですけれども、ぜひこの目標を持つというところをご答弁をいただきたいと思います。","respondent":"藤田水とみどりの課長","answer":"みどりを増やすという部分では、目標の中には当然みどりの部分と水の部分があるんですが、水辺の部分は、これからその面積がどんどん増えていくというものではありませんので、逆にみどりを増やしていかないと、その数値に近づかないということになりますので。","voiceIndex":37,"id":"exchange-017"},{"speaker":"飯沼委員","kind":"質問・要望","question":"ぜひみどりを増やしていただきたいと思いますので、よろしくお願いいたします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":39,"id":"exchange-018"},{"speaker":"大沢委員","kind":"質問・要望","question":"課題のほうで、各水辺、連携、共通した項目があって、「行政に偏った整備」ということの文言がありますけれども、この意味を教えていただきたいということで、そもそもやはりまちづくり、水辺、連携、緑地というのは、行政が主体になって行っていかなければできない事業なので、「行政に偏った整備」というのは、僕は適当な表現ではないと思うんですけれども。","respondent":"藤田水とみどりの課長","answer":"そういった面で、行政だけでものを考えて進めていてはできないということで、今後はこの行政ばかりで進めるのではなくて、もう少し幅広い観点で整備を進めていくべきという、方向性も含めて行政に偏った整備に現状がなっているということで課題として挙げているものです。","voiceIndex":40,"id":"exchange-019"},{"speaker":"大沢委員","kind":"質問","question":"こういう事業を行うに当たって。そうなると、やっぱり協働をうたっていながら、課題ですから書いてあるのは課題でいいんですけれども、偏った整備というのは、ちょっとなんか、それも３つ共通して書いてあるという、これは全部まちづくりのやつですから３つ共通して書いてあるのはしごく当然だと思うんですけれども、何か表現にちょっと違和感を感じるんですけれども。","respondent":"松代都市計画課長","answer":"ちょっと都市計画みたいなところで我々も勉強して進めていますので、ちょっとご説明します。水辺といいますと、品川区は非常に水辺に面する部分があって、貴重な財産だというふうに思っています。","voiceIndex":42,"id":"exchange-020"},{"speaker":"林委員","kind":"質問","question":"具体的な話をちょっとすると、このペーパーの「公共のみどりを増やす」、３番目に出てきて説明をいただいて、東急との鉄道に関する話は出てきたんだけれども、ＪＲとの話が出てこない。植木を沿線に植えていくことでそれをカバーできますよという話もあって、ＪＲと協議をしているのかどうかが１つ聞かせてほしいこと。","respondent":"藤田水とみどりの課長","answer":"当然そういった中で区民との活動を一緒にやっていこうという観点になると、やはり一緒に活動しやすいのは草花なのかなというふうに思っておりますので、そういった面では。","voiceIndex":44,"id":"exchange-021"},{"speaker":"林委員","kind":"質問・要望","question":"そうすると、みんなが住んでいる、生活をしている近隣で、さっきもちょっと話に出た、こういう言葉を使っていいのかね、路地裏作戦みたいな、みどりを防災にもなるだろうし、目を楽しませて憩いの部分もあるだろうし、そういったことで区民の参加ということで、こういう絵をポンと見せられてもだめなので、そういうきめ細かい計画づくりというのも、僕は区のほうはやるべきだと思うんですよね。","respondent":"藤田水とみどりの課長","answer":"今回の新・水とみどりのネットワーク構想では、委員お話がありましたとおり、小さなみどり、そういったものもやっぱり大切にしていかなければいけないよねというようなことで書いてありますので、当然大きなみどりだけでなく、小さな地域の方々が路地の裏でお花を育てたり。","voiceIndex":46,"id":"exchange-022"},{"speaker":"林委員","kind":"質問・要望","question":"最後にします。そういうきれいにしていくということも忘れないで。池田山の公園なんかも、せっかくきれいなコイを放っているのに、色が見えないぐらい濁ってしまって、今どうなっているか最近は池までのぞいていないので、コイの色ぐらいはわかるような、せめてそういうような清潔化というのか、特に水の場合は気をつけて取り組んでおいていただきたいとお願いしておきます。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":48,"id":"exchange-023"},{"speaker":"金野委員","kind":"質問・要望","question":"今の林委員の関連することで私も１つ小さなみどりというところで教えていただきたいというか、確認なんですけれども、いわゆる小さなみどりのネットワークというところを考えると、やはり今ある個々のお宅、あるいはお庭を持っていらっしゃる方等のこういったみどりの活用というのはどのようにお考えなのか。やはりこの草花が非常に維持管理に結構根気がいりますね。","respondent":"藤田水とみどりの課長","answer":"草花の維持管理なんですが、なかなか個人のお宅で個人がずっと管理されているところに区のほうとして支援するというのはなかなか難しいと考えております。","voiceIndex":49,"id":"exchange-024"},{"speaker":"金野委員","kind":"質問・要望","question":"そういうお宅を持っていらっしゃる方、どれぐらい数字的にはよくわかりませんけれども、結構そういうお宅を持っていらっしゃる方は高齢化しておりまして、それを維持管理するのは非常に大変という声も伺います。ですので、そういったところに何かみんなで協力できる、また路地裏の方々と整備をしていける、そんなものができたらという要望で終わります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":51,"id":"exchange-025"},{"speaker":"浅野委員","kind":"質問","question":"１点だけなんですけれども、施策の機能別展開というのが４６ページにありますけれども、ここの中で５２ページに防災・防犯ということで出ておりますけれども、防災につきましては大体イメージは密集市街地の解消ですとか、そういうところと連動してみどりも増やしていくという感覚はわかるんですけれども、防犯については、あまり記載がないような気がしまして、どういう役立ち方をしていくのかなと。","respondent":"藤田水とみどりの課長","answer":"木もあまり大きくなる、あるいは街路樹等で大きくなってくると、街路照明等も遮断して明かりがなかなかうまく効率よく明るく照らすことができない。","voiceIndex":52,"id":"exchange-026"},{"speaker":"浅野委員","kind":"質問・要望","question":"確かにところによってはすごい道路までせり出しているような木ですとか、そういうような場面、柳が出ているところとか、確かにそういうところは非常にうっそうとしているような感じがして、私も相談を受けたこともあって、泥棒が入ったと、立て続けに入ったということもありますので、やはりみどりを増やしたいという部分と、確かにそれと反対に犯罪が増えるようなことになっては。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":54,"id":"exchange-027"},{"speaker":"林委員","kind":"意見","question":"だけど、みどりをこれから増やしていくと、どうしても夏場、あれはまちの人にやってもらわないと、区でやるというわけにもなかなかいかないのだろうと思うんだけれども、片方の環境整備、水とみどりはきれいになったけれども、虫はどうも歓迎しないよというような話になるんだけれども、そのことはこの委員会ではないのかなという気もするんだけれども。","respondent":"齋藤道路公園課長","answer":"それで、区民の皆さんから、そのかわりにということになりますと、やはり農薬法が改正されて、いたずらに散布することが禁止になっておりますので、通報をいただいて、区としても対応する、これが今のところの対応です。","voiceIndex":58,"id":"exchange-028"},{"speaker":"飯沼委員","kind":"意見","question":"すみません。委員長にお願いなんですけれども、本委員会、地球温暖化防止と、水辺とみどりの整備と２項目あるんですが、年間を通してどのように進めていくのかというあたりを、次回でも結構なんですけれども、ちょっとお示しをいただけたらなと考えています。","respondent":"山路委員長","answer":"はい、わかりました。では、その要望は正副で検討します。ほかにございませんか。","voiceIndex":62,"id":"exchange-029"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?Template=document&Id=6172#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=15&TermStart=2009-01-01&TermEnd=2009-12-31"}],"sourceMeta":{"pages":0,"characters":29768,"voices":64}},{"id":"h21-20090918-4","meetingId":"h21-c-settlement","date":"2009年9月18日","dateIso":"2009-09-18","committee":"決算特別委員会","time":"午後３時３３分～午後３時４０分","status":"正式会議録","sourceType":"formal","overview":"決算特別委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を0件抜き出しています。","hasFullText":true,"topics":[],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?Template=document&Id=1306#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=4&TermStart=2009-01-01&TermEnd=2009-12-31"}],"sourceMeta":{"pages":0,"characters":2027,"voices":18}},{"id":"h21-20090924-6","meetingId":"h21-cm09","date":"2009年9月24日","dateIso":"2009-09-24","committee":"区民委員会","time":"午前１０時０２分～午前１１時５４分","status":"正式会議録","sourceType":"formal","overview":"区民委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を13件抜き出しています。","hasFullText":true,"topics":[{"id":"topic-01","title":"委員会での質疑","agenda":"委員会での質疑","exchanges":[{"speaker":"渡部委員","kind":"質問・要望","question":"２つ伺っていきます。それと、区内共通商品券なんですけれども、１回販売されまして、８月３１日まででしょうか。実際２億２,０００万円のうちどれぐらい使われたのか。８月末の段階でどれぐらい使われたのかを教えていただきたいのと、その下の経費の部分の、細かい費目の景品というのは何なのかなというので、教えてください。","respondent":"福島ものづくり・経営支援課長、諸岡商業・観光課長","answer":"時期ですけれども、これは決められましたらすぐ契約したところに伺いまして、今年度いっぱいの事業ですので、３月までにまとめる予定です。データベースにつきましても外注で行う予定です。８月末が使用期限なんですが、商店のほうでまだ換金していない分がありまして、９月いっぱいが換金期間ですので、最終的には９月末日で正確な集計が出るです。","voiceIndex":7,"id":"exchange-001"},{"speaker":"渡部委員","kind":"質問","question":"秋のプレミアム商品券の景品というのはあるんですか。景品というのは２つありますよね。エコポイントのほうと。それと、あと１点。使える、使えないはお店の問題とかいうのがあると思うんですけれども、歓迎されていてもその辺がどうも徹底されていなかったのかなというような気がしまして、これは課長のほうで決められることではないのかなと思うんですけれども、その辺何かご意見あるでしょうか。","respondent":"諸岡商業・観光課長","answer":"失礼しました。プレミアム商品券のほうの景品ですね。３,０００円×３００本という、今回につきましては景品をつけて、販売促進を図りたいです。それから、おつりの件ですけれども、商店街ばらつきがあったです。","voiceIndex":10,"id":"exchange-002"},{"speaker":"稲川委員","kind":"質問・要望","question":"二、三点確認をさていただきたいのですが、この４９ページ、共通商品券普及促進事業ということで４,５９５万７,０００円についてなんですが、１０分の１０国の補助というか、ということなんですが、そこの補助金がどこから、国のどこの所管というんですかね、どこの省庁から出ているかということと、その省庁のどういった支出、どこから支出されているかというかな、所管というか。その辺、確認です。","respondent":"諸岡商業・観光課長","answer":"その金額ですけれども、商品券につきましてプレミアム分を助成するですけれども、発行総額等につきましては経済状況でありますとか、商店街の状況を把握して、売れ残り等のないように販売できるような形での状況を見計らいながら、商店街振興組合連合会とも協議しながら。","voiceIndex":12,"id":"exchange-003"},{"speaker":"稲川委員","kind":"質問","question":"経済産業省なのか、どこなのかというのをちょっと念のために教えてください。どのような割り当てかという。要するに４,５９５万７,０００円というのは、先ほどもおっしゃったように商店街振興組合連合会と話をして、使い切れるような額ということをおっしゃっていたんですけれども、それは区がむだのないように使う額がちょうどそれぐらいの額だという認識でよろしいのかどうなのか。１０分の１０であれば。","respondent":"諸岡商業・観光課長","answer":"総額ですけれども、経済状況に応じて区のほうの企画部等も、財政部門とも協議検討しながら、あるいは商店街振興組合連合会が基本的には発行いたしますので、商店街振興組合連合会の意見等もよく聞きながら定めておりまして。","voiceIndex":14,"id":"exchange-004"},{"speaker":"三上委員","kind":"質問・要望","question":"今になってから。ですから、そういった点での、今回更新したから、あとはまた１０年間いいですよなんていうことでは決してないと思うんですけれども、そこらあたりの、今後のデータベースの更新の仕方というのはどういうふうに考えていこうとされるのか。更新もしないんだったら、やめちゃったほうがいいというようなことで、ここらあたりのお考えをちょっとお聞かせいただきたいと思います。","respondent":"諸岡商業・観光課長、福島ものづくり・経営支援課長","answer":"区といたしましても相談機能の充実ということで、相談員を平成２０年度に１人増員するとか、この間、増大するさまざまな相談に対応できるように機能強化といいますか、体制を整えてきたところです。実際のところ月１万３,０００件ぐらいのアクセスがありますし、他県からの受注につながったですとか、そういう声も聞いていますので。","voiceIndex":16,"id":"exchange-005"},{"speaker":"三上委員","kind":"質問・要望","question":"共通商品券については、こういう時期ですからスピードをもって対応をしていっていただきたいなと。信用という意味にあっては、いついつ発行しますよと言っていながら、それに間に合わないなんていうことだけは、やはり区民にとっては何やってんだという話になるでしょうから、そういった点ではきちんと準備をした上で、日程的におくれのないようにしっかりと整えていっていただきたいと、こう思います。","respondent":"諸岡商業・観光課長","answer":"ただ、１階には啓発展示室いう部屋もありますので、そういった消費者センターの中の部屋をいろいろ工夫して活用しながら、相談業務の充実を図っていきたいと考えています。","voiceIndex":19,"id":"exchange-006"},{"speaker":"渡辺委員","kind":"確認","question":"この１点だけ。商品券のお話で、先ほど来の指摘と若干かぶりますが、まず、発行額についてだけ確認等含めて伺います。そういった中で、ここでいう管理運営費、事務費が、サービスはすごく先行していていいことなんですが、運営する側の負担という点で実態に即しているのかな、大変じゃないのかなという心配もあわせて伺えればと思います。","respondent":"諸岡商業・観光課長","answer":"今回、３億円規模ですが、春に初めて２億円規模というのを行いまして、それは先ほどご案内しましたように４月２０日に発売いたしまして、ゴールデンウィークを挟みまして５月１２日に完売をしたです。","voiceIndex":21,"id":"exchange-007"},{"speaker":"渡辺委員","kind":"意見","question":"今のご説明どおりだと思いますが、完売というものがとても、他区も含めて、もちろん残ったという報道もありましたけれども、基本的には本当に対象者が広いという点から、あるいは低所得者の方の希望もすごくある政策かと思っているので、その辺、今回だけじゃないとは思っていますので、これまでの区の事業の継続性もあって、今後という点の中では十分に考慮していただければなと思っています。その意見だけ。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":23,"id":"exchange-008"},{"speaker":"南副委員長","kind":"質問・要望","question":"先ほどの質問者もそういう思いもあってお聞きになったんだろうと思うんですけれども、私も、この１１年、こんなにたっていたんだと改めて実感したんですけれども、やはりもう少しきめ細かに、とりわけずっとこの間、何とか景気というのがあって大企業は栄えている、中小企業はなかなか厳しいという状況があっただけに、そういう足元をきちんとつくっていくという、そこがまず大事だと思いますので。","respondent":"諸岡商業・観光課長、福島ものづくり・経営支援課長","answer":"先週、東京都ならびに特別区の課長会がございました。東京都のほうからも、今のところまだ特に消費者庁からの具体的なそういった説明はないですから、今後出てくるものかなと考えています。こちらにつきましても、確かに実際企業のほうで行ってはいるんですけれども、その辺の見直し等につきましてはやはり１０年という期間が長くならないように、定期的に行っていきたいというふうには考えてあります。","voiceIndex":24,"id":"exchange-009"},{"speaker":"南副委員長","kind":"提案","question":"その関係で、調査項目というのはもう、コンセプトだけを区側が委託会社にプロポーザルを含めて提案して、そしてこういう内容でと出してくるんだと思うんですけれども、その後さらにこういうところも、こういうところもさらに細かく聞きたいんだみたいな、行政側の意思がどの程度委託業者との関係で整理されていくのか、そこを一つ伺いたいと思います。２点だけ、製造業のほうは伺いたいと思います。","respondent":"諸岡商業・観光課長、福島ものづくり・経営支援課長","answer":"児童への消費者教育等のかかわりですけれども、子ども親子消費生活教室というのを年に２回ほど開いています。学校は先ほど申し上げましたように副読本を配布いたしまして、学校教育の中で取り組んでいただいているです。業者が決まってからは、こちらとの打ち合わせで細かい詰めをしていきます。その際は区として小売店も調査できないかとか、そういうことは指示をしていく予定です。","voiceIndex":27,"id":"exchange-010"},{"speaker":"渡辺委員","kind":"意見","question":"一般会計補正予算についてですが、賛成とします。当然、収支の中で緊急総合経済対策という点から、区民目線から、国の視点から必要性が十分にあるということから、賛成ということでお願いします。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":31,"id":"exchange-011"},{"speaker":"南副委員長","kind":"質問・要望","question":"その辺の確認を一つしたいのと、ですから、今年度始まったばかりの事業なので、当然皆さん初めてなんですけれども、これを契機に地域の中でこういう活動をしていくと、継続性が求められるということだと思うんですけれども、ちょっとその辺を確認したいのと、その辺について、体操も、あと介護のヘルパーの養成も、みんなそれぞれ継続性があるところだと思うんですけれども。","respondent":"秋山協働・国際担当課長","answer":"今回の制度ですけれども、基本的には単年度の事業ということで、今回の募集事業は今年が制度の１年目ですので、９月から来年の２月いっぱいまでの事業ということで募集をしていますので、継続につきましては。","voiceIndex":41,"id":"exchange-012"},{"speaker":"南副委員長","kind":"質問","question":"所管質問を、この間一般質問したんですけれども、本人が質問した内容でも所管質問してもいいということになったと聞いているので、ちょっとしたいんですけれども。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":50,"id":"exchange-013"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?Template=document&Id=2560#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=6&TermStart=2009-01-01&TermEnd=2009-12-31"}],"sourceMeta":{"pages":0,"characters":32530,"voices":59}},{"id":"h21-20090924-7","meetingId":"h21-cm09","date":"2009年9月24日","dateIso":"2009-09-24","committee":"厚生委員会","time":"午前１０時０２分～午後２時１８分","status":"正式会議録","sourceType":"formal","overview":"厚生委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を54件抜き出しています。","hasFullText":true,"topics":[{"id":"topic-01","title":"第７７号議案、平成２１年度品川区一般会計補正予算（歳出 厚生委員会所管分）","agenda":"第７７号議案、平成２１年度品川区一般会計補正予算（歳出 厚生委員会所管分）","exchanges":[{"speaker":"安藤委員","kind":"質問・要望","question":"緊急雇用という言葉がかなり出ていたんですが、いろいろな事業が混ざっているので、ちょっと整理ができない部分がありまして、教えていただきたいんです。それぞれの臨時職員とか、あるいは訪問員ですとか、そういった雇用された方の待遇の面は、例えば何時間労働で、時給が幾らで、各種社会保険や福利厚生、あるいは契約期間、契約形態、そういったものも、それぞれ教えていただきたいんです。","respondent":"冨岡高齢者福祉課長","answer":"これが４１ページです。４２ページにつきましては、福祉人材確保定着事業追加分です。それから、次の高齢福祉費の中のひとり暮らし高齢者等訪問調査事業です。それから、ページが飛びまして、保健衛生費の予防接種データ入力業務臨時職員雇用費等です。","voiceIndex":5,"id":"exchange-001"},{"speaker":"安藤委員","kind":"質問・要望","question":"わかりました。待遇の点では、全部だと膨大になるので、４７ページの予防接種データ入力業務というのは、最後のほうの待遇の具体的内容というのですか、時給、労働時間等、契約期間などを、もう少し教えていただきたいと思います。これは、予算を組んだわけですから、ぜひとも、４,５００件全員に活用していただきたいと思うんですが、そのための区としての工夫みたいなことがあれば、教えてください。","respondent":"平澤生活福祉課長、冨岡高齢者福祉課長、吉田品川区保健所保健予防課長","answer":"時期は、こちらは６月３０日の厚生労働省の告示を受けまして、７月１日開始ということでございまして、いつまでということなんですけれども、毎年。福祉人材確保定着事業分ですけれども、二つの事業のうち、下のほうの説明がちょっと漏れていたので、恐縮ですが、これにつきましては。実働２０日間で、３人を雇用する予定でございまして、日当といたしましては、区の臨時職員の雇用といったところです。","voiceIndex":7,"id":"exchange-002"},{"speaker":"安藤委員","kind":"質問・要望","question":"それを確認させていただきたい。それから、もう１点、福祉人材の定着のところですけれども、これももう少し説明をいただきたいんです。個々のヘルパーのスキルを上げていくというのはすごく大事だと思いますが、それがやっぱり賃金の上昇につながるかどうかというところが、一つのかぎになるのではないかと思うんですが、そこら辺については、区としては、どのようにお考えなのか、この２点をお伺いします。","respondent":"冨岡高齢者福祉課長","answer":"あわせて、これは法人がどういうふうに手当するかはともかくとしまして、東京都が介護職に限りまして、追加で１万５,０００円の手当ということで対応していると聞いておりまして、介護職人材に対しては２段階で出ているんだということで、以前に比べれば。","voiceIndex":11,"id":"exchange-003"},{"speaker":"山内委員","kind":"質問・要望","question":"１点だけ。火災警報器の件で、お尋ねというか、ご指摘をさせていただきたいんです。これから予算で３,６００世帯分啓発活動をしていく中で、そういうことがないように、ひとつお願いをさせていただきたいと思うんです。啓発活動はうまくいっていると思うんですけれども、ちゃんと内容が説明できる方の配置の部分について、今後、ちょっとお考えをいただきたいと思うんですが、いかがでしょうか。","respondent":"冨岡高齢者福祉課長","answer":"今後ですけれども、民生委員については、もうご説明をしているんですが、どういうところにご質問があるのかというところを、もう一度、ご指摘もいただきながら、説明をどういうふうにしていったらいいかということも含めて、今後、ちょっと検討させていただきたいと思います。","voiceIndex":13,"id":"exchange-004"},{"speaker":"山路委員","kind":"質問","question":"国と東京都の基金を活用しての緊急雇用対策、非常に大事な時期ではないかと思うので、今回の補正に組まれたと思うんですけれども、いろいろ細かく分かれていますけれども、大体、何人ぐらい雇用していただくのか、お聞きしたいと思います。","respondent":"冨岡高齢者福祉課長","answer":"厚生委員会所管だと、約２０名ぐらいだと思うんですけれども、ほかのところもありますので、すみません、私どもでは、ちょっとそこまで把握しておりません。","voiceIndex":15,"id":"exchange-005"},{"speaker":"山路委員","kind":"質問・要望","question":"厚生委員会関連で２０名というのは、非常に貴重なことで、いろいろ説明を聞いていますと、専門といいますか、経験豊かな人材が登用されていくのかと思うんですけれども、区としては、どういう形で募集されていくというか、その辺について聞かせていただきたいと思います。","respondent":"冨岡高齢者福祉課長","answer":"高齢者関係の部分ですと、例えば社会福祉協議会に委託するとか、法人事業者に委託していく経費ですので、区が直接というよりも、委託をして、その対応で区がどういうふうに仕上がっているかというのを見ていくということになると思います。","voiceIndex":17,"id":"exchange-006"},{"speaker":"山路委員","kind":"意見","question":"今回で、将来の人材にもつなげていくという計画はあると思うんですけれども、委託関係で人材を育成していくということですが、区としては、補正で、緊急にこういう人材を短期間雇用する期間は何年ぐらい見ていらっしゃるのか、お聞かせください。","respondent":"冨岡高齢者福祉課長","answer":"予算計上は今年度ですけれども、国、東京都の要綱上は、もう１年とうたわれているところです。","voiceIndex":19,"id":"exchange-007"},{"speaker":"石田委員","kind":"質問・要望","question":"年金のときに、そのことによって大分いろいろなデータが喪失してしまったというようなことも実際に起こった中で、たしか２人か３人でやられると思うんですが、４カ月でどのぐらいのデータ入力をされるのか、ちょっと確認をさせていただきたいと思いますので、よろしくお願いします。","respondent":"吉田品川区保健所保健予防課長","answer":"その予防接種票自体は、長期間保存になっておりますので、おそらく紛失する可能性は極めて低いだろうと考えています。","voiceIndex":21,"id":"exchange-008"},{"speaker":"鈴木委員","kind":"確認","question":"何点か確認します。先ほどから出ている住宅用火災警報器の関係で、まず１点、確認なんですけれども、先ほどもお話がありましたように、借家の場合だと、大家の承諾書をもらわなきゃいけないということになりますよね。私、前から疑問に思っているんですけれども、その理由ですね、そこの確認を、もう１回させてください。そこからちょっと教えてください。","respondent":"冨岡高齢者福祉課長","answer":"借家における取り付けの際の承諾書ですが、借家であっても、本来は大家につけていただくところですが、おっしゃるように、ご本人だとか、お住まいになっている方の生命の維持ということがほんとうに基本になってくる、その辺をどういうふうに調整していくかというところで。","voiceIndex":23,"id":"exchange-009"},{"speaker":"鈴木委員","kind":"意見","question":"そこの中で考えると、どうかなと、私は非常に疑問に思っているところなんです。当然、大家が知らないというのはまずいというお答えは、十分に承知をしているんですけれども、そこら辺、逆の立場もちょっと考えてほしい。そこにまた不動産屋が入っていくと、不動産屋がもらいにくくて、それが進まないというケースも現実に聞いているので、そこら辺、ちょっとお答えいただければと思います。","respondent":"冨岡高齢者福祉課長","answer":"私のほうでは、今、委員のおっしゃったことは、正直申し上げて、ほとんど耳に入っていなかったことですが、確かに遠隔地の場合もあるということで、例えば郵送でやっていただくとか、いろいろなやり方があるかと思いますが、それについては、逆に。","voiceIndex":25,"id":"exchange-010"},{"speaker":"鈴木委員","kind":"質問・要望","question":"民生委員が間に入って、そこまでやってくださるのか、もう一つ、不動産屋が仲介業として入っているから、不動産屋さんにやってもらうという問題もあるんですけれども、やはりその前段で引っかかってしまうという人もあるということも、ちょっと考えていただきたい。これはお答えをいただいたので、もう結構です。そこら辺、当然対応していただけると思うんですけれども、お考えを教えてもらいたい。","respondent":"冨岡高齢者福祉課長、黒田健康福祉事業部副参事","answer":"送迎の時間が非常にかかってしまうということでありますが、やはり高齢者は、こういうサービスセンター事業は、慣れたスタッフと一緒に展開していくということでありまして、やはり、対応スタッフとの関係等の問題もありますので。昭和５５年の中小企業センター設立当初からの部分でございまして、学校ができて教室として利用するところは平成７年にかえてありますので、その部分はまだ大丈夫なんですが、それ以前の部分がもう修理が効かないということで。","voiceIndex":27,"id":"exchange-011"},{"speaker":"鈴木委員","kind":"質問","question":"だけれども、そんな中で、一番最終的には、利用者の体調管理に注意してほしいという意味からお聞きしました。両方とも、お答えは結構です。それからもう１点だけ。調査事業等は、このときに４００万円かけて、さらにまた２００万円追加という形でいいんですか。それから、もう１点。ですから、そこら辺を十分に理解してもらうように、地域の方に早くから周知しておいてもらいたいと思います。","respondent":"冨岡高齢者福祉課長","answer":"高齢者相談員としての訪問がない方でありますので、おっしゃるとおり、周知方には十分に留意をして取り組んでまいりたいと思っているところであります。これにつきましては、民生委員のお力も借りながら取り組んでいこうと考えています。","voiceIndex":30,"id":"exchange-012"},{"speaker":"鈴木委員","kind":"質問・要望","question":"単身高齢者がどのぐらいいるか、私は数はわからないですけれども、すごく混在した地域で、また範囲が広いので、その辺も十分にご理解をしていただきたいという点が１点。それから、６月補正のときに、１０分の１０の国の補助が３年間というお話だったんですけれども、今回の事業の調査は１年間でやるのか、それとも、前回のときに３年間という話の中で、今回の調査は単年度という感じでいいんですか。","respondent":"冨岡高齢者福祉課長","answer":"したがいまして、できれば今年度中に調査ができればいいなと考えております。ぎちぎちなスケジュールでございませんけれども、そのような予定です。","voiceIndex":32,"id":"exchange-013"},{"speaker":"鈴木委員","kind":"質問・要望","question":"せっかくやる調査ですから、いい結果を出してもらって、なるべく数多くの方からいろいろな情報、調査結果を得て、いい調査に結びつけてもらいたいということを要望して終わります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":34,"id":"exchange-014"},{"speaker":"金野委員","kind":"質問・要望","question":"大体はわかるんですけれども、この費用に当たっての応援は、どういったことを地域の財源とするのかを、１点確認をさせていただきたい。２点目は、訪問介護委員の資質向上支援事業というふうに計上されておりますけれども、これは、今までのヘルパーの資質をいかに向上させていくか、どのように向上させていくかという具体的な研修の中身を教えてください。","respondent":"冨岡高齢者福祉課長、吉田品川区保健所保健予防課長","answer":"日常生活の支援ということで、買い物や食事などの宅配の手配とか、そういったことも視野に入れ、あるいは見守り活動、安否確認とか、異変の対応とか、そういうこともありますけれども、そういうような事業をいろいろ予定をしています。三つ目ですが、現在は紙台帳でやっておりますので、台帳のあるところでしか予防接種歴は把握ができないわけですが、電子化することで、３保健センターでもあまりお待たせすることなく、予防接種の履歴がわかるといったことです。","voiceIndex":35,"id":"exchange-015"},{"speaker":"金野委員","kind":"質問・要望","question":"よくわかりました。ひとり暮らし高齢者の日常生活、あるいは見守りということで、３年間というとこですが、これは継続をしていくものだろうと思うんです。例えば、賃貸住宅でも大家との連携とかは取られるんでしょうか。そういったところまで踏み込むのでしょうか。単純にひとり暮らしの高齢者と１対１なのか、それとも、踏み込んで、大家と、という場面もあるのでしょうか。それを１点、教えてください。","respondent":"冨岡高齢者福祉課長","answer":"生活応援事業の中で、特に見守りということで、大家との連携というところは、やっぱり一つの検討課題だろうと理解をしております。例えば、別の場面であっても、孤立死防止ということでも、大家との連携というのは、一つの検討課題としてあると思っています。","voiceIndex":38,"id":"exchange-016"},{"speaker":"飯沼副委員長","kind":"質問・要望","question":"何点か、お伺いいたします。それから、アパート探しがなかなか大変なので、その辺の支援は考えられるのかどうか、その辺をお伺いしたいと思います。遠いので、送迎がつくというということなんですけれども、そこは指定管理者ですか、そういった面で、大崎地域の方が北品川まで通うというところで遠くなるわけですが、送迎を行うに当たっての支援が考えられているのかどうかお聞きかせください。","respondent":"平澤生活福祉課長、冨岡高齢者福祉課長","answer":"離職者向けの国の施策についての詳しい説明を、ということなんですけれども、こちらにつきましてはハローワークでやっている制度でございまして、また今年から始まったということで。手続的には、決まった段階で、どういう形で進めていくかということで相談をしまして、今後、事業を進めてまいりたいと考えています。","voiceIndex":40,"id":"exchange-017"},{"speaker":"飯沼副委員長","kind":"質問・要望","question":"これは希望です。それなりの規模ということですけれども、大きなところで研修プログラムが、それがまたほかの小さい事業所に還元されるという面も含まれているのかどうかわかりませんが、積極的に資質向上のため、こういうところにも研修に行っていただくというところでは、規模をあまり制限しないで広げていただけたらなと思いますが、この辺、いかがでしょうか。","respondent":"冨岡高齢者福祉課長","answer":"福祉人材のところで、５法人に規模を制限しないでほしいですけれども、やはり新しく雇用したときに、この方たちは仕事はご存じないわけでございまして、その人たちをバックアップしながら、オンザジョブで、仕事上でトレーニングしていくとなりますと。","voiceIndex":43,"id":"exchange-018"},{"speaker":"安藤委員","kind":"質問","question":"住宅手当のところで、説明を聞き逃していたら申しわけないんですが、これはすごく大事な事業ではないかと思うんですけれども、継続して行ってほしいと思うんですが、期間はどれぐらいと決まっているのかということと、手当の額ですけれども、生活保護の額の上限ということでよろしかったのでしょうか。","respondent":"平澤生活福祉課長","answer":"期間の話です。こちらは国のセーフティネット対策事業を受けて行われる１０分の１０事業となっておりますので、今回の補正は年度末前なんですけれども、３年間を予定していると聞いております。次に金額です。","voiceIndex":45,"id":"exchange-019"}]},{"id":"topic-02","title":"第７８号議案、平成２１年度品川区後期高齢者医療特別会計補正予算（歳出）","agenda":"第７８号議案、平成２１年度品川区後期高齢者医療特別会計補正予算（歳出）","exchanges":[{"speaker":"安藤委員","kind":"質問","question":"所管のほうから希望を出したということになるのか、あわせて経緯もお伺いしたいと思います。実は収納率もかなり高いような、普通徴収で９６.５％ではなかったかなと思うんですけれども、この徴収事務の対象となる高齢者はどういう方々なのか、区としては、どのような方とつかんでいらっしゃるのか、生活実態や、あるいは未納の事情などは、どのようにお考えになっているのかお伺いします。","respondent":"本城国保医療年金課長","answer":"そのほかに、所得割の課税世帯に対しても、所得割を、所得状況に応じて、５０％、あるいは７５％、あるいは全額の軽減等の対応がされているところです。","voiceIndex":54,"id":"exchange-020"},{"speaker":"安藤委員","kind":"質問","question":"この非常勤の方は、専門知識が十分にある方なのか、そこら辺もお伺いします。どういう方が配置されるのか。質問ですけれども、どういう方が配置されるのかということと、実際に、その事務員はどのようなことを行うのか、もう少し具体的にお伺いしたい。それからもう一度、区として、９７.１％の外にいる方をどのようにとらえているのか、もう一度、お伺いします。","respondent":"本城国保医療年金課長","answer":"未納となっている方は、個々には実態がわからない、個々に把握しているわけではないとお話しいたしましたけれども、今回、新しくできた保険料の制度ですので、納めるのを単に忘れているというのも、かなりの数でいると見込まれますので、そういった方については。","voiceIndex":56,"id":"exchange-021"},{"speaker":"安藤委員","kind":"質問・要望","question":"多くの方が忘れているのではないかと考えているということなんですが、そこら辺も、実態はわからないわけですから、ぜひ、区としてつかむ努力をしていただきたいと思います。今回、あえて後期高齢者医療の徴収事務の仕事を行う非常勤を雇うと、補正予算を組もうと思った区の考え方と、経過を、あわせて説明していただきたいんです。そこら辺の区の考え方をお伺いしたいと思います。","respondent":"本城国保医療年金課長","answer":"今回、保険料につきましても、１年ちょっと経過したところですが、未納がかさむ前にご案内することは、私ども所管から見ても、いいタイミングではないかですので、補正をさせていただいたところです。","voiceIndex":58,"id":"exchange-022"},{"speaker":"安藤委員","kind":"質問","question":"今の説明では、ちょっと納得がいかない点があるんです。手を挙げた、乗ったというお話がありましたけれども、手を挙げない方向も考えられるということなので、その中であえて、今回は、区としては、いいタンミングだということで乗ったということなんだと思いますけれども、手を挙げない選択肢もあったということでよろしいのでしょうか。","respondent":"本城国保医療年金課長","answer":"私のご説明が少し不十分だったかもしれませんが、今回は、先ほどもご説明させていただいたところですが、私たち国保医療年金課としても、保険料を安定的に納付いただくためには、よりきめ細かく被保険者にお知らせするということが必要だと考えていたところですので。","voiceIndex":60,"id":"exchange-023"},{"speaker":"鈴木委員","kind":"確認","question":"といいますのは、介護保険料の非常勤徴収の方がいらっしゃいますが、あの方たちは、直に行って徴収と同時に、口座振替等もあっ旋しているんですけれども、こういう考え方ではなく、やり方は別だということなのか、どうか。その中で、連絡を密に取っているのか。ですから、財源ありきではなく、事業が主体の補正予算になんだということを、そこの確認をしてもらいたい。","respondent":"本城国保医療年金課長","answer":"後期高齢者と介護保険がダブっているものを、どういうふうに対応していくかとか、それはこれから実態を見て、検討をさせていただければと考えています。","voiceIndex":62,"id":"exchange-024"},{"speaker":"鈴木委員","kind":"質問","question":"最後の部分はわかりました。今、一人の人がせっかく１対１で交渉している中で、別の人がまた別の交渉に入っていったら、受ける人は、区は何をやっているのかと考えて、かえって反発が高くなる。ですから、やる段階においては、区の中では、当然名前は抽出できていて、連絡を取る前には、もう既に一致させていなければならない話だと、私は考えますが、その辺のお考えを。","respondent":"本城国保医療年金課長","answer":"ただ、先ほどご説明させていただいたのは、今のところまだ、実態について把握しているところではございませんが、もし未納になっている人がかぶっているとか、種々の事情があったとしたら、あわせて対応することも考えられないわけではないかもしれませんが、それについては。","voiceIndex":64,"id":"exchange-025"},{"speaker":"鈴木委員","kind":"意見","question":"私は逆に、今の、この部署として考えていくというのは、違うと考える。これは、この委員会でいいのかどうかわからないけれども、区の中の事業部、各担当部署の課の縦のラインだけであって、今の答えは横が全然入っていない。","respondent":"木下健康福祉事業部長","answer":"例えば名簿の突合をして、両方連携してどちらかが行くとか、そういうような協力体制のあり方については、検討をしてまいります。特に介護保険料のほうは順調にいっておりますので、そのノウハウをこちらで生かしながら、適正な執行に努めていくような方法で努めております。","voiceIndex":66,"id":"exchange-026"},{"speaker":"鈴木委員","kind":"意見","question":"やはり、そのような考え方を持っていただいて、せっかくやる中、区民に理解を得ていただくために、ぜひお願いしたいと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":68,"id":"exchange-027"},{"speaker":"飯沼副委員長","kind":"質問・要望","question":"１点目は、まず、職員が増えたというところなんです。７４ページの給与費明細のところを見ると、一般職のところが、補正前と補正後で３人になっているんですけれども、説明では２名で、その辺の違いを、一つ教えていただきたい。生保関係の方とか、その他納付書で納めている方で、その内訳がわかると、私たち少しイメージが浮かぶので、そこを教えていただきたいと思います。","respondent":"本城国保医療年金課長","answer":"最後に時間外勤務の関係ですが、今ちょっと細かい数字を持っていないので、大まかなところになってしまいますが、今回、計上させていただいている中でですが、時間外勤務の合計で１,３５７万１,０００円となっております。","voiceIndex":69,"id":"exchange-028"},{"speaker":"飯沼副委員長","kind":"質問・要望","question":"すみません、最後のところは、後期高齢者医療制度を担当していらっしゃるところの時間外勤務がどのぐらいあるのか、多分、大変だったのだろうなと思ってお伺いしたので、その辺は教えていただけたらと思うのが一つです。それから、督促状が２,３００人ということなんですけれども、さっき、普通徴収が２７.５％と、そのほかの方がということですか。","respondent":"本城国保医療年金課長","answer":"職員の勤務の状況といいますか、それについては、平成２０年度当初はいろいろ制度が目まぐるしく変わったりしたところもございましたので、それに対する事務対応、あるいは被保険者への説明ということで、かなりあわただしい状況でございましたが、全般的には。","voiceIndex":71,"id":"exchange-029"},{"speaker":"飯沼副委員長","kind":"質問・要望","question":"後でもいいので、できたら時間外勤務がどのぐらいあるのか教えていただけたらと思います。それから、最初に質問したのですが、例えば、特別徴収から口座振替になった人とか、普通徴収の部分がどういうバランスになっているのか、わかったら教えていただきたいです。特に福祉の分野で、国保の滞納の状況を教えていただいたら、滞納内容がわかっていらっしゃる方の６０％ぐらいが生活苦なんですよ。","respondent":"本城国保医療年金課長","answer":"被保険者の滞納されている方の状況についてですが、先ほど、ご説明させていただいたのは、個々に数値的にどうとか、どれだけの数とか、そういう形では必ず把握しているものではないという趣旨でご説明させていただいたところですが、当然、窓口だとかに日々。","voiceIndex":73,"id":"exchange-030"},{"speaker":"飯沼副委員長","kind":"質問","question":"最後に。区の職員と連携をして、補助的な従事であるというところは、実際に電話をしたり、訪ねて行かれるのがこの臨時の方ですよね。その辺の区との連携というのがどういう中身なのか、もうちょっと教えてください。","respondent":"本城国保医療年金課長","answer":"補助的従事といいますのは、訪問だとか、電話の中で、一般的なご説明で十分に納得していただく方も、当然たくさんいらっしゃると思いますが、中には種々のことで、なかなか難しい問題を抱えている方もいらっしゃるかと思いますので、そういった方については、随時。","voiceIndex":75,"id":"exchange-031"},{"speaker":"安藤委員","kind":"質問・要望","question":"ちょっとすみません、徴収実態のご説明いろいろいただいたんですが、ちょっとごちゃごちゃになってしまいまして、整理したいので、質問します。それから、徴収率が９７.１％なんだけれども、平成２０年度末で、区内で７％の方は未納だというお話もありましたが、勉強不足もあるんですが、そこら辺もちょっとわかるように、もう一度説明していただきたいんです。","respondent":"本城国保医療年金課長","answer":"収納率が９７.１％で、未納になっている方が７％というご説明をさせていただいたところですが、９７.１％というのは、保険料の全体の額に対して９７.１％の収納があったという意味でございまして、７％といいますのは。","voiceIndex":77,"id":"exchange-032"},{"speaker":"安藤委員","kind":"意見","question":"区も、さらっと説明してしまうんですけれども、加えて、そもそも保険料を払えないような人に対して、実態とかけ離れたような実績に徴収の圧力をかけかけないという問題点もありますし、質疑の中でもありましたけれども、本来、こういう事務は区の職員が丁寧に高齢者の生活実態をつかんで、必要なアドバイスですとか、救済措置を行うべきことではないかと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":83,"id":"exchange-033"}]},{"id":"topic-03","title":"議案審査を続けます。 (3)第７９号議案、平成２１年度品川区介護保険特別会計補正予算（歳出）","agenda":"議案審査を続けます。 (3)第７９号議案、平成２１年度品川区介護保険特別会計補正予算（歳出）","exchanges":[{"speaker":"安藤委員","kind":"質問・要望","question":"今年の返還金の大きさを比較してみたいので、ここ数年間の返還金の額を教えていただきたい。それから、どうして年度末ではなくて、この時期に返還になるのかということのご説明もお願いします。","respondent":"冨岡高齢者福祉課長","answer":"なぜこの時期に返還金をですが、私どもも、３月のぎりぎりまで返還を待っていただくと非常にありがたいのですが、東京都のほうでも、１月に返してほしいというお話がございまして、タイミング的には、大体毎年この時期に補正でお願いをしている状況です。","voiceIndex":91,"id":"exchange-034"},{"speaker":"飯沼副委員長","kind":"質問","question":"返還金が、総額で１億６,３２９万２,０００円ということで、先ほど、すみません、内訳を言ってくださったのですよね、国庫支出金と、東京都の支出金と、それから、４０歳以上の保険料の支払基金と、６５歳以上の方の保険料のところと、ちょっともう１回、数字をゆっくり教えていただけますか。","respondent":"冨岡高齢者福祉課長","answer":"国につきましては、介護給付費負担金と地域支援の交付金の分の返還金です。東京都に関しましては、地域支援事業の交付金の返還金です。","voiceIndex":93,"id":"exchange-035"},{"speaker":"飯沼副委員長","kind":"質問","question":"今、おっしゃったのは、介護保険の全体の構図の中での６５歳以上の方の保険料のところが入っていないんですけれども、これがまだ発生しないのですか。ちょっとそこのところを教えてください。","respondent":"冨岡高齢者福祉課長","answer":"１号被保険者の部分の保険金については、決算のほうになりますけれども、幾ら入って、幾らという形で処理はいたしますが、返還金という処理はいたしておりません。","voiceIndex":95,"id":"exchange-036"},{"speaker":"飯沼副委員長","kind":"確認","question":"返還金にならないで、６５歳以上の保険料のところは返さないわけですよね。国と東京都の支出金と、４０歳以上の支払基金のプールしている部分はお返しするけれども、６５歳以上の保険料のところは返さない。これが基金の積立になるんですよね。その辺だけ、ちょっと確認をさせてください。","respondent":"冨岡高齢者福祉課長","answer":"保険料につきましては、返還という形をとっておりません。保険料と給付との関係で、残った場合については、年度末になりますけれども、基金という形で積ませていただくという形になろうかと思います。","voiceIndex":97,"id":"exchange-037"},{"speaker":"安藤委員","kind":"質問","question":"裏面のほうでは、ご説明された中で、平成１９年４月から開始という事業も多いと思ったんですが、最近の事業だと思うんですけれども、取り組み始めてからそれぞれの事業について、いろいろ深まった問題意識とか、こういうことがもっと必要なのではないかとか、課題などがわかった点もあるのではないかと思うんですけれども、それぞれ簡単でいいんですけれども、伺えたらと思います。","respondent":"高橋障害者福祉課長","answer":"まだ始まったばかりですので、この辺についても、どのぐらい増えるかという推測はつきませんが、やはりそれぞれの子どもの成長を願っているお母様方、お父様方が不安だというものについては、対応していきたいと考えております。","voiceIndex":106,"id":"exchange-038"},{"speaker":"安藤委員","kind":"質問","question":"人数のところは、例えば６.３％という数字は、教師の方々に聞き取りを行った結果、出た数字というご説明がありましたけれども、区内に大体どれぐらいいらっしゃるのかというのは、支援を強めていく上でも、すごく大事な実態把握のデータだと思いますので、確かに把握する手段は難しいかと思うんですが、例えば、医療機関の方にアンケートを取るとか、そういった形で。","respondent":"高橋障害者福祉課長","answer":"実態調査ですが、先ほど申し上げました広汎性発達障害とか、自閉症、スペクトラムとかいうことで、医師の中にも、この辺の診断の基準がなかなか周知とか、研究がなされていないという状況ですので、アンケートを取ったから実態が出てくるか、私のほうはわかりませんので。","voiceIndex":108,"id":"exchange-039"},{"speaker":"山路委員","kind":"質問","question":"裏面の児童デイサービスのグループプログラム、個別プログラム、発達障害、知的障害、それぞれあるんですけれども、具体的にどういう教育をやられているのか、ちょっと教えていただけますか。","respondent":"高橋障害者福祉課長","answer":"個別プログラムにつきましては、排泄の状況をなかなか理解できないということで、排泄の訓練を集中的に行うとかいうのが、個別の知的障害者の場合は多いと聞いております。","voiceIndex":110,"id":"exchange-040"},{"speaker":"山路委員","kind":"質問","question":"そこで、療育事業というのは、大体１年、２年、３年、どのぐらいの年月とともに、大体人並みといいますか、普通になっていくと考えてられているのでしょうか。","respondent":"高橋障害者福祉課長","answer":"平成１９年度からかかった子どもで、退所した人は、今のところございませんので、継続して、１年、２年とやっていくかと思います。","voiceIndex":112,"id":"exchange-041"},{"speaker":"山路委員","kind":"質問","question":"平成１７年の法施行、大分、地域で充実するようになってきたということは、地域のお母さん方からも聞くんですけれども、１２歳を過ぎると、どういう形で行政がサービスをされていくのか、ちょっと教えていただけませんか。","respondent":"高橋障害者福祉課長","answer":"私どもでできるのは、初期の早期発見の支援かなということで立ち上げたもので、今後、この辺の思春期サポート、中学生以上の方についてもサポートが重要になってくるかと思っていますので、今現在、事業の展開を進めているところですので。","voiceIndex":114,"id":"exchange-042"},{"speaker":"山内委員","kind":"質問","question":"１点だけ、教えてください。非常に基本的なことなんですけれども、発達障害と、知的障害の違いというか、先ほどもちょっと説明があったかと思うんですが、具体的にちょっと教えていただけませんか。","respondent":"高橋障害者福祉課長","answer":"例えば、その子どもが知的のところで困っている場合については、発達を進めるよりは知的の療育をやる中で、発達のところが少なくなる場合もありますし、その辺については、その子ども一人ひとりの状況に応じて行っているという状況です。","voiceIndex":116,"id":"exchange-043"},{"speaker":"山内委員","kind":"質問","question":"その辺が非常に難しいのかなと思うんですけれども、その辺は専門家が、家族というか、親御さんに、こちらのほうを選んだほうがいいですよとか、アドバイスというんですか、そういうことをしていただいているのか、どうなんでしょうか。","respondent":"高橋障害者福祉課長","answer":"ですから、１番目は心理相談員の発達検査を受けますが、具体的には、あわせて医師の診断を受けてもらうというアドバイスの中で、両方がかみ合った中で、ご本人なり、ご家族が、その子どもの特徴をつかんだ上で、どういうふうに進めていくかということで。","voiceIndex":118,"id":"exchange-044"},{"speaker":"石田委員","kind":"質問","question":"１点だけ、周知の方法についてお伺いしたいんですが、これはなかなか保護者も、発達障害というのは知られていないというのが現状だと思うんです。例えば、保護者などにどのような周知を行っているのか。こういったさまざまな事業の周知も、どのように行っているのか、簡単でいいので、教えていただければと思います。よろしくお願いします。","respondent":"高橋障害者福祉課長","answer":"保健センターの場合についても、保健師のところに、この辺の周知を行っているところです。年１回程度、学園で、発達障害児の講演会等を行いますので、その辺につきましては、チラシ等を配って行っているものです。","voiceIndex":120,"id":"exchange-045"},{"speaker":"金野委員","kind":"提案","question":"今、ご説明がありました３点目に、品川児童学園で、年１回、講演会をされているというご説明があったのですが、こういった講演会は、そういう子どもを持つお母さんは意識を持って行くんですが、そうではない中で早期発見を、というときには、特に幼稚園や保育園に通われているお母さんは、我が子が園でどういう生活をしているのかすごく興味がありますし、そういった園の生活を見せていく中で。","respondent":"矢野品川区保健所品川保健センター所長、高橋障害者福祉課長","answer":"品川児童学園の子ども発達相談室のほうにもご紹介したりして、連携をしておりますので、発達障害というのは、その１時点で診断をつけるのはなかなか難しいものですし、親御さんの気づきがないと、その後の指導にもつながりませんので。年１回、生活を見せるということにつきましては、それぞれの園なり、それぞれの私立幼稚園なりの状況がありますので、私のほうで、この辺について回答をすることは困難かと思います。","voiceIndex":122,"id":"exchange-046"},{"speaker":"金野委員","kind":"提案","question":"その１点だけではなくて、就学前にもう一つ健診を増やしていくというような考えで、提案をしてみたいんです。１場面を見てどうですかということではなく、継続的に、年１回ではなく、２回、あるいは３回と、できればそれが一番いいですけれども、そういった気づきの面でするものもあってもいいのかなという思いです。","respondent":"高橋障害者福祉課長","answer":"保護者への対応ですが、それが一番重要かと思います。子どもが成長していく上で、日常的にかかわるということですので、２４時間のうち家庭にいる時間が一番長いですので、その辺については必要かと考えています。","voiceIndex":125,"id":"exchange-047"},{"speaker":"金野委員","kind":"質問","question":"わかりました。最後にもう１点だけ。私立幼稚園で、先ほど要請があればということで、今年度も何園かあるということでしたが、何園ぐらいありますでしょうか。その気づきで、それだけこの相談室につなげることができたのか、実績がありましたら、教えてください。","respondent":"高橋障害者福祉課長","answer":"人数についても、その辺については、個別にご相談が入るので、具体的にどこの園から相談されたかというのは、数字的にはつかんでおりません。","voiceIndex":127,"id":"exchange-048"},{"speaker":"鈴木委員","kind":"質問・要望","question":"そのときに、親御さんに対して理解を求めなければいけないんですけれども、そこでどういう反応があるのか、その辺ちょっと、先に教えてもらえますか。","respondent":"矢野品川区保健所品川保健センター所長","answer":"親御さんへの対応なんですが、なかなかいろいろなタイプの方がいらっしゃいますので、例えば３歳の時点で、明らかに言語のおくれがあった場合には、医療機関等へ紹介をしますが、例えば、ご兄弟も同じようでしたとか、なかなか納得されない方については。","voiceIndex":129,"id":"exchange-049"},{"speaker":"鈴木委員","kind":"意見","question":"ご苦労は大変だと思うんですけれども、自分としては、親御さんが理解を示さないようなケースはあるのかなというのが、やっぱり一番心配なんです。大変難しい話だと思うんですけれども、そこら辺、どこまでご理解を受けていただけるか、その辺のニュアンスを。","respondent":"矢野品川区保健所品川保健センター所長","answer":"親御さんがご理解を示さないケースというのは、なかなか保健センターでも対応困難になっているケースですが、いろいろケースを振り返ってみますと、保健センターだけで経過を追っていくと、就学時の問題とかが起こってきますから、経過を見ていく中でも明らかに発達障害が。","voiceIndex":131,"id":"exchange-050"},{"speaker":"鈴木委員","kind":"意見","question":"それと同時に、今度は学校を卒業してしまうと、また担当部署がこちらになってしまう、そこら辺をどうクリアしていくのか。ほんとうは、各部署がお互いにつながりをつくっていきますというのが答えなんでしょうけれども、まだそこら辺が、何となく自分にははっきり見えないところがあるんですけれども、その辺、もう一度お答えをいただけないかと思います。","respondent":"高橋障害者福祉課長","answer":"昨年の後半から、まず最初、区役所の中での連携ということで、それぞれのセクションが何をやっているのかということで、保育課とか、指導課とか、私どもとか、児童学園とか、保健センター等を集めまして、事業の中身についてこういうことをやっているということで。","voiceIndex":133,"id":"exchange-051"},{"speaker":"飯沼副委員長","kind":"質問","question":"先ほど来、定期的な健康診断のときの項目や何かも、多分工夫されているということでしたけれども、その辺、大体わかってきた発達障害のチェックをより早くして、援助をしていくという立場で工夫がされていると思うんですが、その辺を一つお伺いしたい。","respondent":"高橋障害者福祉課長、矢野品川区保健所品川保健センター所長","answer":"この発達障害そのものが、先ほども申し上げた判断基準とか、その辺のところについては、まだまだ確立されているものではないので、この辺についての専門官がどのぐらいいるのかというところも。健診の部分についてです、新たな方法等というのは、私どもで把握してございませんが、５歳児健診等を実施している自治体の内容を見てみますと、単に健診だけを行うということではなくて。","voiceIndex":135,"id":"exchange-052"},{"speaker":"飯沼副委員長","kind":"質問","question":"それは、どうしていったらいいのかというところは、まだよくわかりませんけれども、やはり子どもを社会全体で育てていく、お互いに育ち合っていく、親も育ち合っていくというところにおいての理解というんですか、啓発というのか、そういうところも、自治体が今後力を入れていく部分ではないかなと思うので、その辺、いかがでしょうか。","respondent":"高橋障害者福祉課長","answer":"この辺につきましては、地道に、私どもでも周知するというふうに進めします。","voiceIndex":138,"id":"exchange-053"},{"speaker":"安藤委員","kind":"質問・要望","question":"９月１７日の南議員の、障害者自立支援法の廃止の問題と、安心して暮らせるグループホーム創設を、の質問について、グループホームの基盤整備と利用料負担の軽減のところで質問があったんですが、ちょっと答弁の内容が若干抽象的で理解しづらい点がありましたので、それぞれの内容を、もう少し具体的に説明していただきたいことが１点。そこら辺のご説明も、もう少し踏み込んでいただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":143,"id":"exchange-054"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?Template=document&Id=3246#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=7&TermStart=2009-01-01&TermEnd=2009-12-31"}],"sourceMeta":{"pages":0,"characters":54231,"voices":146}},{"id":"h21-20090924-8","meetingId":"h21-cm09","date":"2009年9月24日","dateIso":"2009-09-24","committee":"建設委員会","time":"午前１０時０３分～午後３時０７分","status":"正式会議録","sourceType":"formal","overview":"建設委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を45件抜き出しています。","hasFullText":true,"topics":[{"id":"topic-01","title":"議案審査","agenda":"議案審査","exchanges":[{"speaker":"菊地委員","kind":"質問・要望","question":"いくつかお聞きしたいんですけれども、１つは、今説明のあった資料３のところで、西大井駅周辺の地区計画という中で、滝王子通りの地区整備計画があるんですけれども、拡幅する理由をまず教えていただきたいんですけれども。","respondent":"吉川防災整備担当課長","answer":"拡幅についての理由ですが、滝王子通りにつきましては、避難道路の機能強化を図るために道路拡幅を行うです。想定で２万３００人が２時間以内に広域避難場所である大井競馬場に到達できるようにするために、現況７.２メートルを１０メートルに拡幅するです。","voiceIndex":7,"id":"exchange-001"},{"speaker":"菊地委員","kind":"質問","question":"わざわざ滝王子通りを拡幅するんだけれども、いざその先に行くと、拡幅する道路から考えれば狭い道路へ入っていくわけだし、その辺の役割を果たしていくのかどうかというのがちょっとわかりませんので、その辺もちょっと教えていただけますか。","respondent":"吉川防災整備担当課長","answer":"避難道路を新たにというお話ですけれども、滝王子通りは現在でももともと東京都に避難道路と指定されている道路です。避難道路としての機能を見た場合に、現況約７メートルですと幅員が国の基準で足りないということですので、避難道路として強化するために拡幅するです。","voiceIndex":9,"id":"exchange-002"},{"speaker":"菊地委員","kind":"質問","question":"ちょっと今のところで、７メートルで足りるということであれば、滝王子通りの拡幅は必要ないということになるんじゃないですか。滝王子通りを２万３,０００人が通りますよと。それで危険性があるので拡幅しますよと言っているわけですから、ちょっとその質問を１つ。","respondent":"吉川防災整備担当課長","answer":"失礼いたしました。説明がちょっと不足していたと思います。２万３００人が通るのは滝王子通り、この方たちは、ルート変更することによって、滝王子通りの先の直進した場合の道路については、約１万５,０００人が通る想定になっております。","voiceIndex":13,"id":"exchange-003"},{"speaker":"菊地委員","kind":"質問","question":"滝王子通りから直線的に競馬場通り、あそこに抜けるその間が７メートルぐらいですよという話ですよね、今のは。要は、説明されている３１号線のところにわざわざ避難路を持っていったわけですから、だから、滝王子通りを１０メートルにするのであれば、あの道路も１０メートルに近いものにしていくという考え方に至るのではないのかなというような気がするんですけれども。","respondent":"岩田防災まちづくり事業部長","answer":"しかし、なかなか３１号線の実施というのは、いまだに途についていないという状況で、品川区としては、これ以上、切迫する大震災に向けて手をこまねくわけにはいかないということで、暫定的に指定されているこの滝王子通りの強化というのは。","voiceIndex":15,"id":"exchange-004"},{"speaker":"菊地委員","kind":"意見","question":"そうすると、避難路として設定をした際に拡幅していかなければならない、そういう流れも当時からあったんだというお話。本当に今、部長が言われていた、いわゆる道なき道の３１号線のところですけれども、３１号線が都市計画道路としてもし事業化といいますか、そういうものがなされていくと、また設定が変わっていくというような、都市計画道路との関係というのはどういうふうになるのか。","respondent":"岩田防災まちづくり事業部長","answer":"したがって、道路として整備をされた暁には、避難道路としての機能は持つことになろうかと思いますが、ただ、今回、それがいつできるかわからない３１号線を手をこまねいていることはもうできないということで。","voiceIndex":17,"id":"exchange-005"},{"speaker":"菊地委員","kind":"質問","question":"道なき道をどうするかというので、これからの問題として上がってくるんだと思いますけれども、ちょっとあわせてお聞きしたいんですが、武蔵小山のほうの計画についてもお聞きしたいんですけれども、今回の改正というのは、３.１ヘクタールあるうちの一部と先ほどご説明がありましたけれども、まちの中には、これからもっともっとあそこのまちが変貌していく、６０メートル級のビルが建ち上がりましたから。","respondent":"青木都市開発課長","answer":"本件地区計画の変更にかかわる条例の改正ですけれども、この地区計画は、武蔵小山駅東地区といいまして、再開発等促進区を定める地区計画という地区計画の種類の一種になってあります。","voiceIndex":19,"id":"exchange-006"},{"speaker":"菊地委員","kind":"質問","question":"今のガイドラインのところ、でき上がっているわけではないという話ですよね。その辺を住民の皆さんがどう、実際に進んでいく開発と、その辺がうまく住民に伝わっていないというのはどういう理由によるものがあるんですか。もうガイドラインそのものは全体でつくり上げていく、一部の方たちが認知している程度なのかもしれませんけれども、ちょっとその辺を具体的に教えていただけないですか。","respondent":"青木都市開発課長","answer":"そういう中で、これまで進めていく中では、まだ必ずしも十分ではなかったなということで、品川区としてもガイドラインのたたき台となるようなものは役所の側から、本来の趣旨とは違いますけれども、ご提案する必要があろうということで、かれこれ３年にわたってですけれども。","voiceIndex":21,"id":"exchange-007"},{"speaker":"菊地委員","kind":"質問","question":"計画全体で見ていけば、これからいろいろな形で地域の営業者の方ですとかに影響が出てくるわけですから、その辺はほんとうに一部の、私は逆に一部の方でこの計画が全体が進んでいくのだろうなと。地域全体にはなかなか説明し切れていないのだろうなというふうに思いますから、やっぱりその辺はかなり丁寧に進める中身であるべきだろうなというふうに思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":24,"id":"exchange-008"},{"speaker":"菊地委員","kind":"意見","question":"東五反田のＢ地区は、これまでも話してきましたけれども、日野学園の３方向が超高層ビル群で囲まれてしまうわけですけれども、教育施設の立地条件について言えば、以前にも話をしたことがありますけれども、やっぱり厳しく環境をどうしていくのか、教育施設をどうするかということが定められていますし、そういう中で、特に教育施設、あるいは開発促進をするというのは大反対です。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":26,"id":"exchange-009"},{"speaker":"菊地委員","kind":"質問","question":"今説明があったように、西地区の再開発の関係での道路認定ということなんですけれども、ちょっとこの道路の認定のところから離れますけれども、同じ中身です。今回の計画というのは、この道路認定というのは、そこの私道部分を権利変換しない限りは道路として成り立たないということになると思うんですけれども、どうしてこういう線引きになっているのかがちょっと、そこからちょっと教えていただけますか。","respondent":"青木都市開発課長","answer":"ここの部分について、区道認定をするという考え方については、もともと私道という形で道路としての機能がありましたので、これを権利変換で宅地に変えてしまったからといってなくしてしまうと、当該の今ご説明申し上げました建物が道路に接しなくなってしまうということから。","voiceIndex":33,"id":"exchange-010"},{"speaker":"菊地委員","kind":"質問","question":"先日、説明会に参加された方から、ちょっと私、参加できなかったんだけれども、聞いたところによれば、まさに今の私道部分を所有されていて線引きの中に入った方、お一人だけでしたけれども、自分は反対だという声を聞いていますけれども、そういう最後まで嫌だよという声を上げる方の私道部分というのはどうなってしまうのかということと、もしこれ、私道部分を区道として認定していったときに、当然。","respondent":"青木都市開発課長","answer":"そういった意味で、それぞれのお気持ちはいろいろあるのはもちろん承知しておりますけれども、トータルとしての組合全体、地域全体としては、この事業を進めていくつもりであるということは共通した認識であるというふうに考えております。","voiceIndex":35,"id":"exchange-011"},{"speaker":"菊地委員","kind":"意見","question":"今、課長が言われたのは容積。私が聞いたのは建ぺい率としてどうなのかということ、そこを聞きたいのと、それともう１つは、さっき、普通の方というのが、そこのところがよくわからなかったんですけれども、実際にじゃあ、変換には応じませんよという方がいらっしゃると、実際にはどうなるのかということを聞きたいので、そこもお願いします。","respondent":"片田建築課長、青木都市開発課長","answer":"建ぺい率の先ほどのお話ですけれども、建ぺい率については、容積、道路の幅員に影響されるものではありませんから、現在の指定が８０％であれば、それが丸々使えるという状況になると思いますので。２点目のご質問です。","voiceIndex":37,"id":"exchange-012"},{"speaker":"菊地委員","kind":"質問","question":"法律上の部分の話ですからね。やっぱりやむなくじゃあ、どうしようかということで、住民の皆さんが再開発するしかないんじゃないかということで、あの地域にも再開発事業が実際に持ち上がって進んできているわけですから、その前段の部分での区の対応というのは、私はしっかり反省すべき部分だというふうに思っています。ですから、この第８４号議案については、反対の表明をします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":40,"id":"exchange-013"},{"speaker":"菊地委員","kind":"質問・要望","question":"ちょっとそこを教えていただきたいのと、もう１つは、今、さっきの論議のあった大井町西地区の補助金のところなんですけれども、当初予算でたしか２５億円くらい出されていたというふうに記憶しているんですけれども、補正で今改めてこの額を出すという、拠出しなくてはならないという状況、先ほどの話だと促進するためにという話でありましたけれども。","respondent":"藤橋都市整備下水道課長、青木都市開発課長","answer":"１点目の家屋損失補償費等負担金の質問についてお答えします。大井町西地区の補助金増額についてご説明申し上げます。前回の委員会でも報告しましたとおり、総事業費１３２億円ほどの事業に対して２６億円ほど、約２０％の補助金を予定していますと前回ご報告申し上げております。","voiceIndex":47,"id":"exchange-014"},{"speaker":"菊地委員","kind":"質問・要望","question":"前段の鉄道関係の損失部分なんだけれども、事業者の地盤沈下について、私、地盤沈下でのクラックだとか、そういう話なのかなと思ったんですけれども、当然そこだと思うんですけれども、地盤沈下そのものの鉄道事業者の当事者というか、そこの責任、過失というのはないという考え方なんですか。今のお話だと、そこら辺がよくわからないので教えていただきたい。","respondent":"藤橋都市整備下水道課長、青木都市開発課長","answer":"１点目の家屋損失の考え方ですけれども、通常、施工業者が施工計画書というものを立案いたします。それはこういう方法でこういう工事を行うという計画書です。そういったものに対する緊急措置でございまして、そういった観点からいうと、品川区内においては幸いこれはどちらかというと傷口が広がる前の予防措置的な見方もあるかもしれませんけれども、いずれにしても。","voiceIndex":50,"id":"exchange-015"},{"speaker":"菊地委員","kind":"質問","question":"有効な補助金の措置かどうかというのは、現時点で解釈の仕方でいろいろ出てくるのだとは思うんですけれども、この問題で最後にもう１つだけ聞いておきたいのは、補助率２０％というのは、北品川の開発でも２０％ぐらいの感じだったような気がするんですけれども、今後の一本橋の再開発は、合わせて２０％に引き上げられると、この間の説明ですと、補助率が２０％まで引き上げられた理由は。","respondent":"青木都市開発課長","answer":"委員がご指摘の話は、前回もご説明した品川区における再開発事業に対する取り組みのあり方です。２０年以上の歴史にわたってやってくる中で、品川区はどちらかといいますと、補助金のルール上、組合に払ってもいい金額よりも低めに抑える形で補助金を支給してまいりました。","voiceIndex":53,"id":"exchange-016"},{"speaker":"菊地委員","kind":"質問","question":"もう１つだけ関連してお聞きしたいのは、この事業そのものは店舗と、それから２００ちょっとの住戸を建設するということで成り立つわけですけれども、今、聞くところによれば、大崎中地区がそろそろオープンですけれども、実際に保留床が約５割ぐらいしか埋まっていないという話を聞いていて、これはまさに今の経済状況の中での問題だと思いますけれども、大崎中地区の場合は、大崎駅。","respondent":"青木都市開発課長","answer":"これは大崎駅もしくは品川駅周辺、品川区の周辺エリアが著しく競争力が劣っているというものではなくて、日本全国、住宅市場というものがそのような傾向にあるというふうに理解しておりまして、ですから、再開発事業を１０年、２０年考えて。","voiceIndex":55,"id":"exchange-017"},{"speaker":"菊地委員","kind":"質問","question":"将来的に、２０年も３０年もどうかという話よりも、実際に使われる税金そのものは、このときに入っていくわけですから、そういう状況がさらに拡大をしていく可能性も含めて、しっかりとした見方が必要なのではないかと思います。そうでなければ、これらの補助金はついてこないものだと思うんですけれども、暫定の整備という形でしか出ていないので、この辺の理由を教えていただけますか。","respondent":"吉川防災整備担当課長","answer":"この７４０平方メートルの今回補正予算で上げております用地ですが、かなり隣接、先ほど申し上げた１,５００平方メートルの用地と隣接したところにありますので、そのまま公園として整備することも可能なんですが、場合によっては。","voiceIndex":57,"id":"exchange-018"},{"speaker":"菊地委員","kind":"質問","question":"場合によっては、私が聞いたのは、これだけのお金を出していくわけですから、当然、役所内で、公園もそうですけれども、公園にしますよと言って補助金を申請したりするわけですね。今の話だと、何だか何に使うかよくわからないけれども、とにかく取得したんだという感じなんだけれども、どうしてそれで土地をわざわざ取得するのか、どうしてそこに補助金がつくのか、そういう話を聞いたんですけれども。","respondent":"吉川防災整備担当課長、岩田防災まちづくり事業部長","answer":"防災上の考え方から申し上げますと、この密集住宅市街地におきましては、単にオープンスペースをつくる、空き地をつくるというだけで防災上、非常に効果が高いものです。ただ、公園が近くに１,５００平方メートルできますから、永久に公園にするということではなくて、まだ事業期間がありますので、その間は一般に暫定的な広場として、普通の公園のようにつくりますけれども、地域の人に使っていただいて。","voiceIndex":59,"id":"exchange-019"},{"speaker":"菊地委員","kind":"意見","question":"この用地取得をした地域においては、地域を見ますと２９号線の計画地にかなり近い場所ですね。今、課長、部長が言われた代替地ですけれども、買える土地としてという話であれば、当然、例えば、この都市計画道路目黒線が本当に事業化されるといったときに、この土地を活用していくという、そういうことも可能なのかどうか。最後にそこだけ。","respondent":"岩田防災まちづくり事業部長","answer":"ただ、１,５００平方メートルのほうは、都市計画道路にもともと一部引っかかっているところですから、東京都が都市計画道路の事業をやれるときには、強制的に土地は収用されますので、適正な値段で売却する、こういう予定です。","voiceIndex":62,"id":"exchange-020"},{"speaker":"武内委員","kind":"質問・要望","question":"３点ありまして、１つは下神明、５１ページの踏切改良事業と、下神明１号踏切警報器設置工事委託、さっきご説明で、改良、今なくて設置するのではなくて、新たに今まであったものを改良、そんな感じだったんですけれども、その辺のもうちょっと細かいことを教えていただきたいのと、それから、その下の橋梁改修事業のところで、施工内容の変更があったと、その内容について簡単に教えていただきたいのと。","respondent":"藤橋都市整備下水道課長、吉川防災整備担当課長","answer":"２点のご質問にお答えします。１点目の下神明１号踏切ですけれども、平成２０年度に踏切内の拡幅をいたしまして、北側、大崎高校側になりますけれども、大崎高校側の警報器を拡幅に伴って外側に移設いたしました。この用地取得費にかかる歳入の国庫補助金なんですけれども、これは国の緊急経済対策にある新たな補助事業を活用するものですが。","voiceIndex":64,"id":"exchange-021"},{"speaker":"武内委員","kind":"質問","question":"最後の部分なんですけれども、そうすると、実際には歳出で５億８５６万円かかるけれども、補助金をいただけるんですけれども、国からこれだけ来たものを都が２３区とか、市町村のところで、全部足してしまうとそれを上回ってしまうというところで、按分されたというか、少し減らされてしまったと、こういう考え方ですか。","respondent":"吉川防災整備担当課長","answer":"委員のおっしゃるとおりで、各区、それから各市町村、一定程度減額されております。","voiceIndex":67,"id":"exchange-022"},{"speaker":"菊地委員","kind":"意見","question":"実際の開発に賛成される皆さんの考え方というのも、私は否定はできないわけですけれども、やっぱり先ほどもあったように、１つには、大崎駅西口中地区でさえこういう状況でこの計画を進めていけば、大きな問題が起きるし、先ほどの補助金の問題でも、本当にこの計画がまちづくりに資するものかどうか、公共性が高いものかどうかという。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":70,"id":"exchange-023"}]},{"id":"topic-02","title":"請願・陳情審査","agenda":"請願・陳情審査","exchanges":[{"speaker":"武内委員","kind":"質問・要望","question":"比較的、多分、野球場に比べると、サッカーなどというような場が少ないのかもしれないんですけれども、そういう例えばサッカーとか、そういったチームの方からの要望みたいなものもあった上で、区のほうでこういう指定をという段階なんでしょうか。その辺をちょっと教えてください。","respondent":"藤橋都市整備下水道課長、齋藤道路公園課長","answer":"平日の利用も少ないという、いろいろな事情がありますので、それぞれを勘案して最終的にはこういった方向の公園にしようというようなことを、これからいろいろな意見を踏まえて検討しようですので。補足をさせてください。維持管理の点は道路公園課でやっております。平成１９年度で申しますと、野球は区内に５８チームありまして、１,４８０人の方がメンバーです。サッカーは３４チームで１,０９８名。","voiceIndex":77,"id":"exchange-024"},{"speaker":"武内委員","kind":"質問","question":"理由はわかりました。その中で、この請願の代表の方たちと何らかの交渉というか、お話し合いはされているのでしょうか。","respondent":"齋藤道路公園課長","answer":"団体の方々たちも、一身専属で排他的に野球ができるということが時代に合わないというのは十分認識されているのだと私は思っております。","voiceIndex":80,"id":"exchange-025"},{"speaker":"武内委員","kind":"質問・要望","question":"確かにいろいろなスポーツがあって、グラウンドとか、いろいろなことも含めて、場をどうやって公平にというか、利用できるかというのは、非常に難しい課題だし、限られたグラウンドなので、そういう面では、やっぱり流れとしては多目的にやっていけるというほうがいいのかなと思いつつも、今までやっぱり長い歴史の中でやってこられた方たちの思いというのも当然わかる部分がありますので。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":82,"id":"exchange-026"},{"speaker":"藤原委員","kind":"質問","question":"このグラウンドの設計等は、都市整備下水道課で設計をするのですかということが質問と、まずそこから行きますか。ごめんなさい、何で都市整備下水道課でやるのか。","respondent":"藤橋都市整備下水道課長","answer":"先ほど来、請願にあります大会の支援ですとか、いわゆるそういう団体との連絡の窓口につきましては青少年育成課のほうで携わっていまして、私どものほうは、道路公園下水道にかかわるいわゆる改修工事を行う所管になっておりますので、今回につきましては。","voiceIndex":83,"id":"exchange-027"},{"speaker":"藤原委員","kind":"質問・要望","question":"私は、ずっと言い続けていたんですけれども、この辺は１つの部がいいというのはずっと言い続けているので、必ず縦割り行政という形で来たお客様に関しては、今まではこうですけれども、維持管理は道路公園課ですということを丁寧に、一般の人というのはよくわからないんですから、その辺はよく連携をとってやっていただきたいということが要望です。","respondent":"岩田防災まちづくり事業部長","answer":"今回、私どもがハードで検討するのは、将来の需要に備えたいかようにも使い勝手ができるような施設としてまず基本を考える、こういう姿勢だというご理解をお願いしたいと思います。","voiceIndex":85,"id":"exchange-028"},{"speaker":"菊地委員","kind":"質問","question":"今、部長の答弁で優先順位をという話なんですけれども、これ、今は少年野球場として、昼間はほかの方も最近は使っていらっしゃったんだけれども、実際に、じゃあ、多目的広場にして優先順位と考えたときに、例えば、そもそも野球場だったので野球をする方をまず最優先にして考えるという意味合いなのか、それとも平日については、先ほど利用率の話がありましたけれども。","respondent":"岩田防災まちづくり事業部長","answer":"先ほどちょっと申しましたように、実際、少年野球の方たちにどのように使っていただくかというのは、これからの検討課題なんです。","voiceIndex":87,"id":"exchange-029"},{"speaker":"阿部副委員長","kind":"質問・要望","question":"ちょっと教えていただきたいのですが、ここに匹敵するようなサッカーのメッカみたいなサッカー場というのはありますか。","respondent":"齋藤道路公園課長","answer":"岩田部長がご説明申し上げましたとおり、野球場のメッカ、サッカー場のメッカ、いずれのメッカにもなってほしいという区民の願いを……。失礼いたしました。ございません。","voiceIndex":89,"id":"exchange-030"},{"speaker":"阿部副委員長","kind":"質問","question":"例えば、ここが、ほかに全く使わないということでなくても、少年野球中心に使っていくということであれば、逆に意図的にどこか、今、野球で主に使っているようなところでも、サッカーの中心となるようなグラウンドというのも逆につくってあげることで、ここだけで両方のメッカになるというよりは、野球はここの区民公園で、サッカーはこのサッカー場で。","respondent":"松代都市計画課長","answer":"今、委員からのご質問にありました将来的にはサッカー場をということで、両方ともあけておるんですけれども、大体９,０００平方メートルから１万平方メートルぐらいの土地というのは非常に確保が難しいものですから、今の既存の中での多機能、もしくは少年野球の人は。","voiceIndex":91,"id":"exchange-031"},{"speaker":"阿部副委員長","kind":"意見","question":"あまり深入りするつもりはないんですが、完全に本格的なプロがやるとしても、今ある中でサッカーに適したところを、ここはサッカーを優先的に使うというところをきちんとつくってあげた上で、こちらについても、請願の内容についても考えるというような、そういったことも必要ではないかなとおります。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":93,"id":"exchange-032"},{"speaker":"市川委員","kind":"質問・要望","question":"今、多目的で使われているところが３つあると、天王洲と、南埠頭と、八潮北公園、これについて、今、多目的で使っている利用者の声というのは、どのようなことが上がっているのか。使い勝手が悪いとか、そういう意見とかがあると思うんですけれども、どんなふうになっているのでしょうか。教えていただきたい。","respondent":"齋藤道路公園課長","answer":"野球のほうが優先という形になっておりますので、どちらかというと、サッカーの利用者はほとんどとれていません。もっと野球をしたい、サッカーをやらせてほしい等、私どもに聞くご要望としては、サッカーの利用者からのご要望のほうが多いということです。","voiceIndex":94,"id":"exchange-033"},{"speaker":"市川委員","kind":"質問","question":"使い勝手が悪いとかという意見はないんですか。グラウンドそのものの。","respondent":"齋藤道路公園課長","answer":"マウンドがそのままになってサッカーで使用しております。したがって、途中ででこぼこみたいに、サッカーの人にとってみると、やりにくいということがあります。","voiceIndex":96,"id":"exchange-034"},{"speaker":"市川委員","kind":"質問","question":"先ほど説明の中に、マウンドを外してサッカーをやれるようなご答弁があったかと思うんですけれども、その辺はそうではないということですか。","respondent":"岩田防災まちづくり事業部長","answer":"だから、利用者からそういう声が出るのは、試合をしている、フットサルの試合のところは真っ平らなんですけれども、ボールが外へ出てとりに行くときに、すぐ近くにもっこりとしたピッチャーマウンドのところがありますから、そういうのがちょっと危ないとか。","voiceIndex":98,"id":"exchange-035"},{"speaker":"武内委員","kind":"質問・要望","question":"先ほどいろいろな幅広く多くのスポーツの方ができる環境づくりという面では、請願、ちょっとそれとは反しているところがあるんですが、ただ、先ほどのご答弁の中から、今日の話し合いの中で、全く強行に野球専用としているというよりは、その中で少し象徴的な、例えばマウンドだとか、いろいろな部分で話し合いの中で譲れる部分があるようなニュアンスでございましたので。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":102,"id":"exchange-036"},{"speaker":"菊地委員","kind":"意見","question":"私としては、平成２３年度から工事着工ということなんですよね。だから、もう少し利用者の皆さんとの論議というのが可能な時間があるのかなというようなことで、継続にするのがいいのかなというような感じはしているんですけれども、全体が趣旨採択ということであれば、そのような結論でもよい感じです。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":103,"id":"exchange-037"},{"speaker":"阿部副委員長","kind":"質問・要望","question":"先ほども言いましたように、やっぱり区内に１つのメッカ、あこがれの地を持つというのは大切なことだと思いますので、ここでおっしゃるような、専用にするかどうかは別として、少なくともマウンドのある球場ということを選択肢に入れつつ決めていっていただきたいということと、あわせてさっき申し上げましたように、あこがれの地が必要なのは野球だけではありませんので、そういう意味では。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":104,"id":"exchange-038"},{"speaker":"高橋委員","kind":"質問・要望","question":"今日結論を出すことで。この請願にありますように、これまでの経緯を十分考えて、やはり区のほうも運営、ここにありますようにいろいろな連盟等の活動に影響が出る可能性はあるので、これまでの経緯を含めて対応していただきたいという要望と、先ほど、会長とお話があったといいますが、やはり利用者の意見を十分聞いていただいて、理解を得る形で進めていっていただきたいというふうに考えます。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":105,"id":"exchange-039"},{"speaker":"藤原委員","kind":"意見","question":"さっき、部長の答弁で、これは専用というのは野球オンリーだよということでというお話があったので、採択はできませんが、特にマウンドということにおいて、これからいろいろな案を出していくということで、マウンドというのは大事になってくると思いますので、趣旨を、そういう意味においてのグラウンドの整備とか設備の意味において、マウンドとかというのはいいと思うので。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":106,"id":"exchange-040"},{"speaker":"市川委員","kind":"意見","question":"今日結論を出すということで、ネットとしても趣旨採択ということでお願いしたいと思います。やはり限りある施設をいろいろな団体で使うということが当たり前のことだと思いますが、今まで専用のグラウンドを使っていた方たちにとっては、このマウンドを維持したいというお気持ちもわかりますので、マウンド面での使いたいというところを汲んでいただいて、この趣旨については採択ということで。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":107,"id":"exchange-041"}]},{"id":"topic-03","title":"委員会での質疑","agenda":"委員会での質疑","exchanges":[{"speaker":"藤原委員","kind":"質問","question":"いわゆるゼロヒャクというやつですよね。１００が区というんですけれども、具体的にこの案件で区の過失はどこですか。","respondent":"諸石交通安全担当課長","answer":"雨が降っていたということで、あのバリケードは前照灯が当たれば確認はできると思うんですが、バックライトで、しかも雨が降っているということで、非常に確認しづらい状態だったということで、今回のこの件については。","voiceIndex":115,"id":"exchange-042"},{"speaker":"武内委員","kind":"確認","question":"そういうことはあり得るんですか、通常。それで、バリケード自体も「品川区」と書いてあった、区境だから、多分、大田区との境だから大田区のものかななんて気もしたけれども、品川区ということが書いてあるから、だれか責任者はわからないけれども、品川区、しようがない、そういうことなんですか。","respondent":"諸石交通安全担当課長","answer":"まだ結論がこちらのほうへ届いておりませんけれども、それを踏まえて、今後は管理をされていないものについては、申しわけございませんが、私どものほうで撤去をする。管理をされているものだけ使っていただくということでいきたいというふうに考えております。","voiceIndex":117,"id":"exchange-043"},{"speaker":"武内委員","kind":"質問・要望","question":"わかりました。それなんかもあわせてご確認しておいていただいたほうがいいのかなと、そういうような要望で終わります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":119,"id":"exchange-044"}]},{"id":"topic-04","title":"報告第２７号","agenda":"報告第２７号","exchanges":[{"speaker":"菊地委員","kind":"質問","question":"南議員が質問させてもらいました耐震化のところで、なかなか進んでいかない理由として、この間の調査で本会議の中では、意識の未成熟の問題ですとか、経済的な事情だとか、あるいは高齢化という問題が出されていましたけれども、この辺の実際に目標に向けてどうやって進めていくのかというところを、改めてこの分析の結果として導き出されるもの、その辺で少しご報告願えればなというふうに思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":138,"id":"exchange-045"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?Template=document&Id=3956#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=8&TermStart=2009-01-01&TermEnd=2009-12-31"}],"sourceMeta":{"pages":0,"characters":48608,"voices":145}},{"id":"h21-20090924-9","meetingId":"h21-cm09","date":"2009年9月24日","dateIso":"2009-09-24","committee":"文教委員会","time":"午前１０時０３分～午後１時５１分","status":"正式会議録","sourceType":"formal","overview":"文教委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を59件抜き出しています。","hasFullText":true,"topics":[{"id":"topic-01","title":"第７７号議案、平成２１年度品川区一般会計補正予算（歳出文教委員会所管分）","agenda":"第７７号議案、平成２１年度品川区一般会計補正予算（歳出文教委員会所管分）","exchanges":[{"speaker":"中塚委員","kind":"質問・要望","question":"今回の補正はわりと多岐にわたっているので、幾つか伺いたいと思うんですけれども、初めに４１ページの女性福祉資金貸付事務のことですけれども、先ほどの説明の中で、修学資金の実績増に伴うというお話がありましたけれども、事務事業概要を見ていますと、例年では年間七、八件ほどですけれども、現在までに申込者数というのか相談数というのか、その実績と、あと貸付の実績。","respondent":"安井子育て支援課長","answer":"女性福祉資金は一応予算のほうでは、修学資金、就職・就業支度資金とか、その他いろいろ見込んでおるところなんですけれども、現在のところ修学資金のほうは１０人ほど申し込みが来ておりまして、一応それで見込みが、あとは就学支度資金を１人見込むぐらいで。","voiceIndex":7,"id":"exchange-001"},{"speaker":"中塚委員","kind":"質問・要望","question":"あわせて、認証保育所の助成事業のほうをお伺いしたいんですけれども、先ほどのご説明の中で、２年分に対応してというご説明があったのかな。","respondent":"安井子育て支援課長、吉岡保育課長","answer":"状況の分析ということなんですけれども、やはり経済情勢が厳しいということで、また就業等がなかなか増えないというような中で、どうしてもお子さんたちの修学。それからもう１園が、この１０月１日に開設を予定しておりますさくら大崎保育園、こちらは設置者、経営主体のほうは株式会社さくら保育園です。","voiceIndex":9,"id":"exchange-002"},{"speaker":"中塚委員","kind":"質問・要望","question":"当初予算では１園分だったのが、今回、さくら大崎保育園が入ったため２園分になったということでよかったんでしょうか。それと１カ所の助成金額が上限３,０００万円と伺っているんですけれども、これについても引き上げを考えているのか、どういうふうにその辺を考えているのか、お考えをご説明いただければと思います。","respondent":"吉岡保育課長","answer":"それから３,０００万円を今回の補正で、１,５００万円を追加をいたしまして４,５００万円ということで、補正をお願いしているわけですが、こちらの理由は、先ほども申し上げましたように１園で予定をしておりましたところ、もう１園の申請が出てきたということと。","voiceIndex":12,"id":"exchange-003"},{"speaker":"中塚委員","kind":"質問・要望","question":"いわゆる株式会社が対象になっているところで、今のご説明ですと、その開設をするための誘導策というお話でしたけれども、いわゆる認証保育所の開設、企業からの要望があれば、例えば開設数の増加に応じて常に予算をつけるという考えなのか、逆に青天井ではなくて区の歯止めといいますか、そういうのはどのように考えているのか。そこはいかがでしょうか。","respondent":"吉岡保育課長","answer":"歯止めですけれども、歯止めはあくまでも予算の範囲内というのが補助金の通常の考え方ですので、歯止めとしては上限３,０００万円というのが１つの歯止めになっているのかなと考えています。","voiceIndex":14,"id":"exchange-004"},{"speaker":"中塚委員","kind":"質問","question":"開設準備金として税金を入れるわけですから、この２つの保育園事業者について、区は何をどこまで把握をしているのか。職員の配置や保育料の設定や、さらには安定した保育園の運営の力量というんですか、そういうところは区はしっかり独自に把握していらっしゃるのか、ご説明いただけますか。","respondent":"吉岡保育課長","answer":"職員配置等ですけれども、初めに申し上げましたように認証保育所というのは、認可保育園が児童福祉法に基づくのと同様に、東京都の認証保育所事業の実施要綱に基づくものでございまして、その基準に基づいた内容での運営ができるかどうかは。","voiceIndex":16,"id":"exchange-005"},{"speaker":"中塚委員","kind":"質問・要望","question":"しかも必要な職員の配置をしていなかったということも、ここだけではなく都内各地で明らかになっていて、これでは安心して預けられないという声がたくさん上がったと思うんですけれども、区はこの窓口に開設準備金を用意しながら、認証保育所の運営のところをどのように精査しているのか、どのように把握をしているのか、そこがよくわからないのでご説明いただきたいという点と。","respondent":"吉岡保育課長","answer":"保育料のほうですが、今資料が出ませんので、ちょっとお時間をいただきたいと思います。","voiceIndex":18,"id":"exchange-006"},{"speaker":"中塚委員","kind":"確認","question":"もちろん、東京都に申請された書類で区は確認すると言いますけれども、それでは本当に大丈夫なのかなという心配をするんです。高いなと私は思いました。しっかり品川区の子どもたちが利用するといいますか、お世話になるといいますか、ですからそういう運営のところもつかむ必要があると思うんですけれども、認証保育所についてはこれで最後ですけれども、いかがでしょうか。","respondent":"古川子ども未来事業部長","answer":"それぞれ厳しい中での認証保育所を利用される方については、一定の助成制度をもって対応していますし、認可保育園と制度は違いますが、比較的それに近い形での経済的負担については助成が効果を持って果たしてきていると考えていますので、制度の違いを完全に埋めるというのは。","voiceIndex":20,"id":"exchange-007"},{"speaker":"中塚委員","kind":"質問・要望","question":"確かに補助制度ができて、補助制度は必要なことだと思います。それと、教育委員会のほうで１件だけ伺いたいと思ったんですけれども、５５ページの学校ＩＣＴ環境整備事業なんですけれども、地上波デジタルに対応するというご説明が先ほどありましたけれども、デジタルテレビを各学校１台ずつということでいいんでしょうか。もう１つ、このテレビは一括購入になるんですか。それとも地元の電気店なんですか。","respondent":"富田学務課長","answer":"各校１台ですので、可動、動かせるキャビネットつきでということを考えております。購入に当たりましては、入札により業者を選定することを考えています。一括です。","voiceIndex":22,"id":"exchange-008"},{"speaker":"中塚委員","kind":"質問","question":"１台１台を変えなくても、アナログ放送からデジタル放送ですか、専門的なことはわからないので申しわけないんですけれども、そういう集合マンションの仕組みがあると。学校もそういうふうにすれば安くなるのではないのかという話も聞いたんですけれども、各教室のテレビは今後どのような対応をしていくのか、ちょっとご説明いただけますか。","respondent":"富田学務課長","answer":"現在各学校等に聞きましても、授業の中でリアルタイムでテレビを見ることは大変少なくなってきているというような状況がありますので、今後のＩＣＴ化の推進とあわせ、どういった展開の仕方が望ましいのか検討をしています。","voiceIndex":24,"id":"exchange-009"},{"speaker":"井上委員","kind":"質問","question":"今のに関連してから入りたいと思うんですが、５５ページのところでデジタルテレビ等購入ということで、「等」についてお伺いしたいと思ったら、デジタルテレビとブルーレイということで、各１台の予算だということだったんですけれども、ここの歳入のところでちょっと見ると、この費用というのは２分の１の負担なんですけれども、歳出のほうでは国庫、国等の支出金が全額になっておりますけれども。","respondent":"富田学務課長","answer":"歳入については、あす、総務委員会でご審議いただくということになっておりますが、この予算案の見方ですけれども、３０ページ、３１ページにあります総務費補助金の地域活性化・経済危機対策臨時交付金の充当事業と、３２ページ、３３ページ。","voiceIndex":26,"id":"exchange-010"},{"speaker":"井上委員","kind":"質問","question":"総務費補助金のほうの地域活性化・経済危機対策臨時交付金という歳入については、いろいろな項目があるというふうに企画のほうから伺って、その中で選べるものは随分広範囲に使用できるものというふうに伺っているんですけれども、その中で、支出でこのデジタルテレビに充当したということは、相当この重要性があると考えてのことなのかというふうには推測するんですが、その辺について。","respondent":"富田学務課長","answer":"区全体としてさまざまな項目の中から、全体調整した結果であると考えております。私どもといたしましては、地デジ対応等々のための必要な経費であると考えております。","voiceIndex":28,"id":"exchange-011"},{"speaker":"井上委員","kind":"質問・要望","question":"区としてそういうふうな検討をしたということですが、２０１１年から対応として、本当に今、それが最適なものなのかということが、今回の補正予算は品川区としても大変厳しいタイトなスケジュールの中で、いろいろな検討をされて補正がついたということは理解をしているんですが、所管のほうに問い合わせましたら、こういう各特定財源の分については、全庁的というよりも。","respondent":"市川教育次長","answer":"使える特定財源が国から、あるいは東京都からどういうふうに示されるのかということが、実は昨年来、今年度の予算を組む段階からそういう検討、あるいは状況の推移を見守ってまいりました。","voiceIndex":30,"id":"exchange-012"},{"speaker":"井上委員","kind":"質問","question":"特定財源のその手当てという部分では、今後ないかもしれないということでおっしゃられて、さっき各小学校にあるテレビというのは、この話の専門はよくわかりません状態なんですが、自宅であればチューナーをつけたりとか、そういうのをつけて見る対応をすることができますよとか、いろいろあると思うんですけれども、そういう今まで使っていたテレビはどうするんですかと。","respondent":"富田学務課長","answer":"なお今回、各学校に１台ずつと考えておりますのは大型テレビでございまして、最初は５０インチ程度ということを考えたのですが、ちょっとキャスター台も含めますと扉を入るのが大変なぐらい大きな形になってしまいますので。","voiceIndex":32,"id":"exchange-013"},{"speaker":"井上委員","kind":"質問","question":"これからの検討課題ということで伺いましたけれども、ちょっと新聞報道で恐縮なんですけれども、文部科学省絡みで見直しをするというようなニュースがある中で、地デジテレビも凍結の項目として入っていくというように新聞にありましたけれども、そういうふうになった場合に、品川区としては、私は今、これが本当に最優先というふうにはどうなのかなという疑問を持ちながらの質問なんですが。","respondent":"富田学務課長","answer":"このＩＣＴ関連の国の学校情報通信等々にかかわる補助金の予算額は２,０００億円ということで、すべて凍結ということではないだろうと思いますけれども、いずれにいたしましても国等の補助金が該当事業について凍結されるということになりました場合には。","voiceIndex":34,"id":"exchange-014"},{"speaker":"井上委員","kind":"質問・要望","question":"わかりました。学校への地上波デジタルテレビとか電子黒板とかパソコンの普及のための８,０６０億円が見直しされるかもしれないというような報道があったので、そこのところは１回通してしまったからということではなくて、精査をしていただきたいなと考えています。もう既に決まっているのであれば、そこの学校名をお知らせいただきたいんですけれども。","respondent":"冠木指導課長","answer":"それから中学校１校につきましては、荏原第一中学校です。全体の経緯といたしましては、既に品川区の研究学校としての研究が進んでいるというような部分もございまして、今回の小学校における英語教育の検討という意味でふさわしい学校ということでの選定です。","voiceIndex":36,"id":"exchange-015"},{"speaker":"井上委員","kind":"確認","question":"確認です。英語教育改善調査研究事業というのは、もう品川区で進めていて、なおかつそこに６００万円余の予算を上乗せするということですか。","respondent":"冠木指導課長","answer":"この事業につきましては、今回の新しい小学校の学習指導要領等にも、小学校における外国語活動を平成２３年から、これは全国的に外国語活動、それも原則として英語とするということで実施をするということがございまして、もう既にご案内のように。","voiceIndex":38,"id":"exchange-016"},{"speaker":"井上委員","kind":"質問","question":"ちょっと伝わらなかったのですが、事業計画としてあったものに対して上乗せをするということで、何か研究内容が変わるのかどうかということをちょっと伺いたかったんです。","respondent":"冠木指導課長","answer":"研究内容につきましては、それぞれの学校、小山台小学校については先ほどお話ししたように少し一歩進んでいるという状況がありますけれども、事業としてはそれぞれ新規事業というふうにお考えいただければ結構だと思います。","voiceIndex":40,"id":"exchange-017"},{"speaker":"井上委員","kind":"意見","question":"幾つもあるのであれなんですが、４５ページの保育園の運営費追加分なんですけれども、これは緊急雇用としての予算組みということなんですけれども、緊急雇用がなければ、こういった保育園の設備修繕等という内容がちょっとよくわからないんですが、今までにやろうとしていた事業に対してちょっと上乗せをして事業をしていこうとしたのか、たまたま庭木の剪定などは予算がつかないとやらない事業なのか。","respondent":"吉岡保育課長","answer":"こちらで考えております、緊急雇用創出事業の財源を使っての保育園の維持管理費ですけれども、ここに書いてありますように庭木の剪定ですとか、あと設備の修繕ですとか、当然、必要があれば行うもので、お金がつかないからやらないというものではございませんけれども。","voiceIndex":42,"id":"exchange-018"},{"speaker":"西本委員","kind":"質問・要望","question":"所管がちょっと違うのかもしれません。歳入との関係を教えていただきたいんです。それと、品川区の中で１０分の１０ではないと思うので、ある程度品川区もプラス一般財源のほうから出していくよというなものがあるのかどうか。１０分の１０であればそういうのはないと思いますけれども、そこら辺の全体の予算づけというか、それを教えていただきたいんですが。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":44,"id":"exchange-019"},{"speaker":"西本委員","kind":"質問","question":"要は本当にやらなければいけないということであれば、一般財源をもう品川区の財源から出すべきだと思うし、そうではなくて、たまたま機会があったから、補正としてかけられるから、国とか都からお金が出るから、ではそれを使いましょうというふうになって、それは別に出たものについては当然つくんだからいい話なんですけれども。","respondent":"市川教育次長","answer":"今回計上させていただいた歳入の委託金に係る歳出事業につきましては、さっき指導課長のほうから説明申し上げたように、私どもが平成２１年度の予算案の内容を決定した時点では、東京都のほうでは枠組みだけは持っていて。","voiceIndex":48,"id":"exchange-020"},{"speaker":"西本委員","kind":"質問","question":"ただ、本当にこの品川区としてこういう事業をやっていく、例えばこの英語教育というのは先行してやっていたという部分があるわけです。そうすると、では品川区全体の教育を考えたときにどういう考え方で、このプラン２１の中に入っているわけですから、全体図を見た中でどういう方向性を持ってこういう政策を持っていくかということになるのではないかなと思うんです。","respondent":"市川教育次長","answer":"ただ結論から言いまして、委員のおっしゃるように、必要なものは特定財源があろうとなかろうとやる。これは基本的にはそのとおりだと思います。ただ、使える特定財源についてはできる限り活用していこうという考え方です。","voiceIndex":50,"id":"exchange-021"},{"speaker":"西本委員","kind":"質問","question":"最後にＩＴ化の件なんですけれども、今後のスケジュールですね。今、地デジ対応でデジタルテレビの購入となっていますけれども、多分これだけではないと思うんですが、デジタル化という広い意味で全体像がどういうふうに今後なっていくのか、そのお考えを最後にちょっとお聞きしたいと思います。","respondent":"富田学務課長","answer":"は来年度の予算編成の段階でどういった内容にしていくかを、それに向けて検討し、固めてまいります。地デジ対応、校内ＬＡＮ等々を含めて行ってまいります。","voiceIndex":52,"id":"exchange-022"},{"speaker":"西本委員","kind":"質問","question":"来年度中にというそういう近々のお話ですか。それとも二、三年かかりそうだということなんでしょうか。","respondent":"富田学務課長","answer":"は今年度購入した上で、その後のテレビ、レコーダー等の活用の検証もしたいと考えております。そういったことを含めまして、来年度からある程度の年次計画等々をかけて展開していくような形で検討を進めたいと考えております。","voiceIndex":54,"id":"exchange-023"},{"speaker":"浅野委員","kind":"質問・要望","question":"私から数点ほどお願いしたいんですけれども、今、ほとんど皆さんの質問の中に出たかと思いますけれども、５５ページの学校ＩＣＴ環境整備と、その下の新型インフルエンザ発生に伴う修学旅行費キャンセル料公費負担ですけれども、この修学旅行キャンセル料公費負担なんですが、１０校がその対象となったと先ほど説明いただきまして、それに伴う補助ということだったんですけれども。","respondent":"富田学務課長","answer":"１点目、修学旅行についてですけれども、延期の日程、８月下旬から実施をしておりまして、今日出発したところを含めて８校が実施をしておりまして、残りが２校です。従来より秋の日程に組んでいる学校が２校ということで、４校がこれからを予定しているということになっています。","voiceIndex":56,"id":"exchange-024"},{"speaker":"井桁委員","kind":"質問・要望","question":"態度のほうから、賛成です。今回、このような補正が組まれて、今後また国の動向というのも変わってくると思いますので、ぜひ品川区でやっていくんだというような強い意思表示を、今後とも国、都にぜひとも働きかけていただきたいということを願いまして、賛成といたします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":60,"id":"exchange-025"},{"speaker":"浅野委員","kind":"質問・要望","question":"今、ご意見にもあった予算の関係、今回の補正予算、今後どうなるかということ、新聞でもまたニュース報道でもされておりますけれども、ぜひとも区のほうとしましても、文教委員会だけではなくて他のところでも同じような論議がされていると思いますけれども、やはり区として総力を挙げて今回の補正予算を取ってこれるような、そのような取り組み等で。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":61,"id":"exchange-026"},{"speaker":"中塚委員","kind":"意見","question":"この補正予算、いろいろ問題点はありますけれども、態度としては反対はしません。賛成です。ただ、認証保育所の問題点につきましては幾つか指摘させていただきましたけれども、部長のほうから最後の答弁の中で、品川の子どもが通っているわけだから、把握についてお話がありましたけれども、それが具体的にどのように仕組みとして担保されるのか、そういう問題点は指摘しておきたいと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":62,"id":"exchange-027"},{"speaker":"本間委員","kind":"意見","question":"賛成いたします。一言申し添えるならば、国の緊急経済対策のねらいが雇用の反映にまで及ぶような形で進んでいかれたら非常にありがたいなと。結果が出るような形で進めていただけたらありがたいなと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":63,"id":"exchange-028"},{"speaker":"西本委員","kind":"質問・要望","question":"皆さんおっしゃるように、今後どういう状況になるのかなということが非常に厳しいところがありますけれども、要は一過性にならないように、継続的に進める政策はやはり継続的にやっていくべきだと思いますので、そこは今後の政策の中に取り入れて、もちろん財源は国とか都からのそういう補助とかについてもキャッチしていただきたいと思いますけれども、やはり大切なことは何かと言った場合に。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":64,"id":"exchange-029"},{"speaker":"井上委員","kind":"意見","question":"今回、特定財源として１２億円から１３億円の補正ということは、非常にこれ自体には問題がないわけではないというふうにはとらえていますけれども、自治体としてこういった国の補助金や都の補助金などを区民に還元するということは必要なこと、大賛成であるということではありませんけれども、こういう自治体の義務としてはいたし方がないというふうに思っておりますので賛成をします。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":65,"id":"exchange-030"}]},{"id":"topic-02","title":"インフルエンザへの対応につきまして","agenda":"インフルエンザへの対応につきまして","exchanges":[{"speaker":"井上委員","kind":"質問・要望","question":"何件か教えていただきたいんですが、小学校のほうで学級閉鎖・学年閉鎖の中で、教職員の皆さんの罹患という状況がどういうことになっているのかということと、あと周知の方法ですが、ちょっとホームページを確認してありませんのであれなんですが、こういったふうに文教委員会には学年・クラスも含めて周知をしていただいていますけれども、ホームページのほうでは学年のみだったと思います。","respondent":"冠木指導課長、富田学務課長","answer":"教員の罹患の状況ですが、この連休に入る前の段階で１名の報告をいただいております。現在１名です。教育委員会としても、こういった状況を把握するように努めてまいりたいと考えます。","voiceIndex":72,"id":"exchange-031"},{"speaker":"井上委員","kind":"質問・要望","question":"それについて、学校の先生には通じているんでしょうけれども、いろいろな小児科に受診に行くわけですので、そういった情報を医師会を通じてなのか、小児科医のグループとかあると思いますけれども、そういうところに保健所を通じると１週間ぐらい経過したデータしか届いてこないということで、もっと適切に情報を小児科医院のほうにも提供してほしいんだというご意見がありまして、それは当然だと思うので。","respondent":"富田学務課長","answer":"区立小・中学校につきましては、日々の学校ごとのインフルエンザ様疾患による欠席状況ならびに臨時休業の状況について、両医師会にお知らせを毎日しています。","voiceIndex":75,"id":"exchange-032"},{"speaker":"中塚委員","kind":"質問・要望","question":"具体的に小学校・中学校のこの新型インフルエンザの対応について、臨時休業の基準や出席停止の考え方が示されましたけれども、保育園・幼稚園についてはどのような基準というか、考え方で対応を行っているのか、ちょっとご説明がなかったのでご説明いただきたいというのが１つ。現状の保育園・幼稚園では登園自粛と。","respondent":"吉岡保育課長","answer":"今後インフルエンザがさらに拡大をして休園が予想されるような事態ですけれども、当初新型インフルエンザが発生をいたしましたときに、事業継続計画の中で考えておりましたことは、休園もあり得るんだけれども、実際のところ先ほど申しましたように。","voiceIndex":77,"id":"exchange-033"},{"speaker":"中塚委員","kind":"質問・要望","question":"ご家庭はさまざまだと思うんです。子どもの最善の利益に立って、自治体は具体的な対応策をやる必要、責任があるわけですけれども、いろいろな保護者から、やはり秋や冬にかけてどうなっていくのだろうという不安の声も伺いますので、それぞれ保育園と、あと幼稚園のほうは学校に準ずるという話がありましたけれども、学校のほうと、休園または休校のときの保護者への対応をご説明いただきたい。","respondent":"吉岡保育課長、富田学務課長","answer":"休園に至るような事態になったときの検討する内容と、それから課題というような話がございましたけれども、一応、今、申し上げましたように、現在の時点では、今のところ１週間程度の自粛をお願いすることによって。今般の新型インフルエンザ対応の中では、学級閉鎖また学校閉鎖等した場合には、当該の学級、学年、学校については、すまいるスクールも利用できないこととしております。","voiceIndex":79,"id":"exchange-034"},{"speaker":"中塚委員","kind":"質問","question":"学校、保育園、それぞれ休園・休校をしたときに、もちろん自分の子どもが具合が悪いわけですから、そういうときは会社を休んで、会社自体も休める状況・体制、そういう役割も果たすべきだと思いますけれども、その中でもどうしても休めない家庭の事情があって、今の学務課長のご説明でも、基本的には家庭で見る、お知り合い、地域でという話がありますけれども。","respondent":"市川教育次長","answer":"先ほど学務課長が申し上げましたけれども、先週の４日間の休校の間、学校サイドにどういう声が寄せられたか、あるいはまた事後に今週になってからいろいろ保護者の方からお声も届くでしょうから、そういったことをよく聞き取りをして今後の対応に備えていきたいと考えています。","voiceIndex":82,"id":"exchange-035"},{"speaker":"西本委員","kind":"確認","question":"１点だけ確認します。保育園のほうですが、給食代行に給食を頼まれていると思うんですね。その方たちの健康管理というのは、逐次報告は来ているんでしょうか。","respondent":"吉岡保育課長","answer":"給食の調理代行のほうにも、園の状況についてはお知らせをするとともに、先ほど申しました園児、保護者とか職員に対すると同様な健康の管理を行うように注意喚起を強く促していますので、何らかのそういう情報があれば、園を通じまして報告が上がるような形になってあります。","voiceIndex":84,"id":"exchange-036"},{"speaker":"西本委員","kind":"質問","question":"そうすると、今までに給食代行で入っていただいている方々は、まだ罹患されていないという理解でよろしいですか。","respondent":"吉岡保育課長","answer":"現在のところ、給食調理の職員の方が罹患したということは報告されておりません。","voiceIndex":86,"id":"exchange-037"},{"speaker":"浅野委員","kind":"質問・要望","question":"聞き逃したところもあるかと思うので、ちょっと確認を含めてお伺いしたいんですけれども、東京都の対策をベースにして、今回考えられているということですけれども、ニュースによりますと小学校１年生の方がインフルエンザで亡くなられたということで、本当に親御さんとしては何かご無念としか、大変なことだと思いますけれども、ぜひとも教育委員会としましても。","respondent":"富田学務課長","answer":"そういった罹患が広がらずにそのまま終息をして再開するという学校もあります。そういう意味では、これまでに２度の学級閉鎖等を行った学校は今のところありませんけれども、今後の可能性としては十分そういったことはあるだろうと考えています。","voiceIndex":88,"id":"exchange-038"},{"speaker":"浅野委員","kind":"意見","question":"お子さんも家族の方が感染すると感染危険性が高いということで、この点につきましては今後、どのような形でインフルエンザが蔓延してくるかということも含めまして、きめの細かい対応をぜひともお願いしたいと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":90,"id":"exchange-039"},{"speaker":"林副委員長","kind":"質問","question":"品川区の教育委員会の考え方をちょっとお聞きしたいんです。都立学校の基準というのは、２枚目のこの第９９報ということと認識すればいいんですか。この２枚を読むと、あくまでも東京都の教育委員会が決定しないとならないというふうに受け取れてしまうんですけれども、その辺、都教委と区教委と学校というそれぞれの立場が違う人たちがどういうふうに取り計らっているのか、ちょっと説明してください。","respondent":"富田学務課長","answer":"教育委員会が決定をするに当たりましては、その学校、学級等々の状況、例えば先ほど申し上げました重症化するお子さんの状況ですとかそういったもの、さまざまなことを勘案して、学校長の意見を最大限に尊重して、教育委員会が決定するということにしております。","voiceIndex":91,"id":"exchange-040"},{"speaker":"林副委員長","kind":"質問","question":"学校で決定ではないんですね。それはわかりました。この措置状況の一覧表で、今、閉鎖されているのは３２番と３３番、第三日野小学校と御殿山小学校、今日、あすということになっているわけですけれども、この表を見ていると、３０番の伊藤学園は、９月１８日金曜日、これは１日だけ学級閉鎖で休み。この１日だけ休みと、３日、４日休むというその判断はここの表にはないんだけれども、どういうことですか。","respondent":"富田学務課長","answer":"基本的には休業期間４日間の原則に従っております。","voiceIndex":93,"id":"exchange-041"},{"speaker":"林副委員長","kind":"確認","question":"ちょっと確認しますけれども、例えば、では３０番の伊藤学園は９月１８日の金曜日から１９日土曜日、２０日、２１日、２２日、２３日と休んだと勘定してしまうんですか。","respondent":"富田学務課長","answer":"そのとおりです。１８日を含め、昨日まで休んでおります。","voiceIndex":95,"id":"exchange-042"},{"speaker":"林副委員長","kind":"意見","question":"それは、だけど改めて説明する必要があるのではないか。１日しか休まないのと、１８日から２３日まで５日間休んでいるというのと、一般の人に誤解を生むのではないか。１日だから軽いなというふうに受け止められる。学校のほかの人たちにとって、うちの学校は金曜日だけ休めばいいんだというふうにとらないか。ちょっともう１回だけ説明してください。","respondent":"富田学務課長","answer":"土曜、日曜、休日については、当初から学校が休業日ですので、臨時休業措置というものをとった日にちのみをここには記載していますが、実際には休業日、臨時休業日合わせて休んでおりまして、保護者に学校がお知らせをするに当たりましても。","voiceIndex":97,"id":"exchange-043"},{"speaker":"中塚委員","kind":"質問","question":"この指定管理者による管理に対するモニタリング・評価の結果についてという形で報告があったのは、今年でたしか３回目というか、３年目に当たるんでしょうか。毎回この報告を受けるたびに、納得できないと疑問が残るんですけれども、つまり改めて伺いたいのは、このモニタリング評価の結果を議会に報告する意味を執行機関としてはどう思っているのかという点なんです。","respondent":"吉岡保育課長","answer":"そういった意味で、その指定管理をうけている団体について、どのような内容で業務を遂行しているのかを各年ごとに議会のほうにご報告するという位置づけで、ご報告をさせていただいているものです。","voiceIndex":106,"id":"exchange-044"},{"speaker":"中塚委員","kind":"意見","question":"改めて、この家庭あんしんセンターとぷりすくーる西五反田で、どのような内容で業務が遂行しているのかを報告しているというお話だと思うんですけれども、それならばこの総括シートをつくったのはだれなのか。このシートの裏面の下に、経営会議における検証とありますけれども、この経営会議とは区の組織なのか、指定管理者となっている事業体内の組織なのか、そこをご説明いただけますか。","respondent":"古川子ども未来事業部長","answer":"そういう資料として、こういったものを毎年作成をし、所管の委員会にご報告申し上げるということになりますので、もしご意見等ございましたら何なりとおっしゃっていただければ、また所管に伝えてまいりたいと考えております。","voiceIndex":108,"id":"exchange-045"},{"speaker":"中塚委員","kind":"質問","question":"ここで言っている経営会議というのは、区の会議だというご説明はわかりましたけれども、この総括シート、要は今日提出があったこの文書をつくったのはだれかということを伺ったんです。一方で議会としては、自分たちの意思としてどういうふうに実行されているのかをチェック監視する責任が私はあると思っているんです。はこの総括シートをつくったのはだれなのか、教えていただけますか。","respondent":"吉岡保育課長","answer":"総括シート自体は、子ども未来事業部長もお答えしましたように事業を所管しておりますそれぞれの課におきまして、指定管理をうけております団体との日々の接触といいますかやりとりの中、あるいはその中で指導をし、実際現場にも行って現場の確認をしているわけですけれども。","voiceIndex":110,"id":"exchange-046"},{"speaker":"中塚委員","kind":"質問・要望","question":"つまり今日のこの資料では、指定管理者に議決を経て選定された業者が、事業目的に沿って安定的に運営できているのかどうかがよくわからない。区の評価はこの評価です。具体的に伺いますけれども、とりわけこの福祉の分野ですから、福祉は人だと思いますので、職員体制を伺いたいと思うんですけれども、家庭あんしんセンターとぷりすくーる西五反田の現在の職員体制はどうなっているんでしょうか。","respondent":"安井子育て支援課長、吉岡保育課長","answer":"母子生活支援施設のひまわり荘ですけれども、こちらについては常勤とか嘱託とかおりますけれども、専門相談員を含めて１２名、子育て支援センターについては１０名の職員が配置されております。ぷりすくーる西五反田の職員定数ですけれども、平成２０年の数字ですが、保育園部門が全部で２５名。それから幼児教育部門が９名。それから管理部門等をあわせまして、全部で４３名となっています。","voiceIndex":112,"id":"exchange-047"},{"speaker":"中塚委員","kind":"質問・要望","question":"ぜひそれはしっかり検討していただきたいなと思います。ただ実際の運営がどうなっているのかという生のデータをしっかり示していただけないと、どういうふうに運営がされているのか、また利用者からどういった声が上がっているのか、また声を集めるにはどういった調査をしているのか。だから運営の全体が見える資料をしっかり添付していただきたいなと要望だけしておきます。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":115,"id":"exchange-048"},{"speaker":"井上委員","kind":"質問","question":"適切に執行されているというのを、何をもって議会はそれをそうですねというふうに思うのかといったら、執行されていますよというものだけで判断をしてくださいというのは、ちょっとこれは無理があると思いますので、こういったところを明らかにしていくことが必要であるということで、なおかつ法人の中でいろいろな複数の指定管理の委託を品川区の場合には行っておりますけれども。","respondent":"吉岡保育課長","answer":"財務につきましても、それぞれの所管の課におきまして詳細な財務評価の報告等も受けておりますし、それを踏まえた形で判断をした上で、一定の書式についてこの総括シートというフォーマットをもってご報告をさせていただいているというものです。","voiceIndex":116,"id":"exchange-049"},{"speaker":"井上委員","kind":"質問","question":"そういう意味では、各指定管理の内容によって少し違っても、別にそれは構わないと思うんですが、財政のところで、どうぞ信頼してくださいということではなくて、出すということについての見解を区としてどういうふうにとらえて、この報告書にしていくかということに関係すると思うので、その辺のところのお考えをちょっとお伺いしたいと思います。","respondent":"古川子ども未来事業部長","answer":"そういう限りにおきましては、この総括シートが必要十分な内容が当然網羅されているだろうと、私自身そう思ってありますけれども、先ほど中塚委員、ただいま井上委員からも重ねてそのような添付資料等のご意見がございましたので、このことにつきまして。","voiceIndex":118,"id":"exchange-050"},{"speaker":"井上委員","kind":"質問・要望","question":"ちょっと家庭あんしんセンターのほうで、先ほど職員体制のお話が出てきましたけれども、その中でやはり相談業務というか、関係性を持って密に対応していかなければいけない部署だと思っているんですけれども、具体的には継続年数というか、非常勤を含めて人がどんどん回転するような状況ではよくないと思うんですが、勤務形態、その辺がどのぐらいでかわってしまわれるのかとか。","respondent":"安井子育て支援課長","answer":"は嘱託と非常勤という形で対応しております。臨床心理士とかそういう方もみえておりますけれども、そういうような形になっております。ファミリー・サポート・センターについては常勤はおりませんで、嘱託のほうで対応しております。","voiceIndex":120,"id":"exchange-051"},{"speaker":"井上委員","kind":"意見","question":"子育て支援事業のところで、継続年数がどのぐらいか。常勤３人はそうでも、あと非常勤と嘱託だったら毎年毎年かわっているのか、その辺がよく見えないんですけれども。継続して働く年数というのはどういう仕組みになっているのか。法人内でどんどん異動しているのか、ここできちんと対応されているような職員体制になっているのか。","respondent":"安井子育て支援課長","answer":"子育て支援センターにつきましては、特に常勤で長年相談等も継続してやらなければ、相談者と密接な信頼関係が図れないということで、そこら辺で話し合いの継続性とか、そういったものを重視しておりますので、ほとんど。","voiceIndex":122,"id":"exchange-052"},{"speaker":"井上委員","kind":"質問・要望","question":"やはり、個々にそういう話でやりとりをするよりも、しっかりとそういうことがこのデータでこういうふうにということであれば、それが一番ベストかなというふうに思いますので、先ほどの件も含めてきちんと説明が果たされるような資料提供ということで、検討いただきたいというふうに思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":124,"id":"exchange-053"},{"speaker":"西本委員","kind":"確認","question":"幾つか確認をしますが、先ほどの意見の中にもだれの評価だということで、これは所管のほうが書いて、経営会議でそうだといったものが出てきたというところだと思うので、これだけではちょっとわからないなというのが正直な話です。というのは、そもそも設置目的のところで、どういう姿であったら評価が高いのかというところの視点というのがどこに入っているのかなというふうに思うんです。","respondent":"吉岡保育課長、安井子育て支援課長","answer":"ただ職員についても一定の入れ替わりはありますし、実際にその職員の人件費をどの水準で維持していくかということにつきましては、当然区の職員の保育園関係。相談件数についても２,０００件くらい増えてきておりまして、療育のほうはお子さんを連れてこないとなかなか相談というのができないんですけれども、虐待の場合は電話での相談、匿名性みたいなものもありまして。","voiceIndex":125,"id":"exchange-054"},{"speaker":"西本委員","kind":"質問・要望","question":"ということは、毎年どういう目的で、何をどういうふうにしてもらいたいのかという満足度というのは、評価の判定をするときにどこまで行ったら満足度が上がっていくかというところをどういうふうに考えているのでしょうか。","respondent":"古川子ども未来事業部長","answer":"指定管理者制度全般にわたってお答えするのは非常に難しいだろうと思います。それぞれの施設の管理のみの委託にかかわる分なのか、あるいは事業も含めたものになるのか。事業の質をはかるというのは、これは確かに難しいんです。","voiceIndex":128,"id":"exchange-055"},{"speaker":"西本委員","kind":"質問・要望","question":"どうしても折り合わないという場合、これを必ずやってほしいんだという場合には、やはりお金をかけなければいけないと思うんです。そういう判断を私たちがしていかないといけない部分だと思うので、そこの指定管理者側の要求というのがどういう要求か、もしも具体的なところがあるのであれば示していただきたいし、それによって調整される項目はあったのかどうかをちょっとお聞きしたいと思います。","respondent":"吉岡保育課長","answer":"指定管理者側からのいろいろな要望につきましては、日常のやりとりの中でお受けしておりますので、予算編成の時期になればそれなりのご要望をいただくようなことはございまして、それも予算の話ですから、反映できるもの、反映できないものありますけれども。","voiceIndex":130,"id":"exchange-056"},{"speaker":"中塚委員","kind":"質問・要望","question":"一年一年だとよくわからないんですけれども、この間伊藤学園からずっと続いている部分があるので、その事業の経過というんですか、法律ではない定義というんですか、背景というんですか、その経過をちょっとご説明いただきたい。ですからそのあたりの、繰り返しになるけれども、初めは文部科学省の指定で研究開発校で始まって、今はある意味違うわけですよね。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":135,"id":"exchange-057"},{"speaker":"中塚委員","kind":"質問","question":"ひとこと、いいですか。この検証の位置付けですか、先ほどの一般質問にも関連するんですけれども、これがどこに位置付けられているものなのか。例えば新教育プログラムの流れがあったり、いろいろな予算の根拠の流れで、先ほどの説明だと３年間の検証とありましたけれども、その位置付けだったり根拠だったり、それをご説明いただきたかったので、明日の一般質問とのかかわりもあるので、明日で結構です。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":140,"id":"exchange-058"},{"speaker":"林副委員長","kind":"質問・要望","question":"買入れること自体の契約は総務委員会でやるけれども、この内容を、こういうものが出てきている、なぜかと言ったら、今、２学期が始まった途中ですよね、この教材を、この時期に買入れるという理由とか、この教材が果たす役割とかいうのは、文教委員会に報告をしてほしい。こういう議題に上ったときは。明日、さっきの一般質問とは別に報告をしてほしいと思うんですけれども、いかがですか。","respondent":"市川教育次長","answer":"したがいまして、委員長のほうでよろしければ、明日、学習指導要領の改訂に伴う教材の整備についてというようなことで説明をするようなことで、おはかりいただければと思います。","voiceIndex":142,"id":"exchange-059"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?Template=document&Id=4680#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=9&TermStart=2009-01-01&TermEnd=2009-12-31"}],"sourceMeta":{"pages":0,"characters":49429,"voices":145}},{"id":"h21-20090924-5","meetingId":"h21-cm09","date":"2009年9月24日","dateIso":"2009-09-24","committee":"総務委員会","time":"午前１０時０２分～午後２時０８分","status":"正式会議録","sourceType":"formal","overview":"総務委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を42件抜き出しています。","hasFullText":true,"topics":[{"id":"topic-01","title":"第８１号議案 大崎駅西口駅前交通広場（Ｃ地区デッキ部）整備工事委託契約","agenda":"第８１号議案 大崎駅西口駅前交通広場（Ｃ地区デッキ部）整備工事委託契約","exchanges":[{"speaker":"宮崎委員","kind":"質問","question":"契約金額は約１１億９,０００万円ということですけれども、都市再生総合整備事業でやるんですけれども、補助金が幾ら入っているのかということと、その補助金額の算定根拠、考え方はどういうふうになっているか伺いたいんですが。","respondent":"青木都市開発課長","answer":"お答え申し上げます。都市再生総合整備事業として整備いたしまして、現在予定しております国の補助金は、総額２億４,５００万円ほどを想定しております。","voiceIndex":6,"id":"exchange-001"},{"speaker":"宮崎委員","kind":"質問","question":"そうすると、国がやるとなると４億９,０００万円で計算するということだけれども、グレードを上げるということで１１億９,０００万円となると。前回もちょっと質問があったんですけれども、４つの開発の事業者で共同で運営していくというような説明だったと思うんですが、そこをもうちょっとお伺いしておきたいのと、今後の維持管理とか、そういう費用はどういうふうになっているのか、伺いたいと思います。","respondent":"青木都市開発課長","answer":"費用の上げ方からご説明申し上げます。","voiceIndex":8,"id":"exchange-002"},{"speaker":"宮崎委員","kind":"質問","question":"国の標準の考え方でつくれば４億９,０００万円、それが今回１１億９,０００万円ということなんですけれども、これだけ増える決定的なものは何ですか。細かいことは別として主に、これとこれとこれが加わったのでこれだけの金額になったという、国の考え方との違いといいますか、どういう点なんでしょうか。","respondent":"青木都市開発課長","answer":"もちろん仕上げ材等細かく違うんですけれども、基本的に違いますところは６ｍでいい幅のデッキを今回は１１ｍにしているということで、かなり余裕を見た設計をしております。","voiceIndex":10,"id":"exchange-003"},{"speaker":"宮崎委員","kind":"質問","question":"道幅６ｍでいいところを１１ｍということですけれども、例えば街路灯と言うんですか、いわゆる当初の投資だけではなくて、運転していく費用も大きく変更があるんでしょうか。","respondent":"青木都市開発課長","answer":"例えば街路灯というご指摘ですけれども、明るさが十分かどうかという点では多少明る目にしたいというようなこともいろいろありますけれども、基本的にランニングコストについては、環境対策も含めてできる限り負担の少ないものにしたいというのが。","voiceIndex":12,"id":"exchange-004"},{"speaker":"宮崎委員","kind":"質問","question":"それともう一つ聞きたいのは、４つの地区でそれぞれ分担して、今回のこの部分についてはソニーが担当するということですけれど、この西口のところはこれから、南地区への延伸も予算に出ていますけれども、あと中地区ですか、ずっと伸びていくということですけれども、そうするといわゆるプラスアルファ、ここだけグレードを上げるというのでなく、ずっと続いていくわけですよね、おそらく。","respondent":"青木都市開発課長","answer":"さらに南地区のほうに行きますと、今度は南地区の再開発事業の施工地区の中になりますので、その中で整備していくことになるんですけれども、現段階では、原則としては同じグレードでやっていきたいということで設計協議を進めているところです。","voiceIndex":14,"id":"exchange-005"},{"speaker":"須貝委員","kind":"確認","question":"ちょっと確認なんですが。随意契約ということで、現在工事をやっている事業者が引き続きということだと思うんですが、その随意契約になった理由を教えてください。","respondent":"市岡総務部長","answer":"３点目には、先ほど来説明がありましたけれども、大崎駅西口全体の事業推進のためコーディネートを委託しておりますので、各地区との調整業務を熟知しながら本工事との連携をスムーズにやっていく。こういう３つの理由から随意契約としたものです。","voiceIndex":16,"id":"exchange-006"},{"speaker":"宮崎委員","kind":"質問","question":"今お話を聞いたんですけれども、人が通る道の部分になるということで、うちのほうもいろいろ検討したんですけれども、国の標準の４億９,０００万円からかなりグレードアップして倍以上の金額になるというところに税金を、やはり税金の使い方としておかしいということを言っておきたいと思います。ですから、これはちょっと認められないと。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":18,"id":"exchange-007"}]},{"id":"topic-02","title":"第８２号議案 （仮称）荏原西地区小中一貫校新築外構その他工事請負契約","agenda":"第８２号議案 （仮称）荏原西地区小中一貫校新築外構その他工事請負契約","exchanges":[{"speaker":"宮崎委員","kind":"質問","question":"今回の契約のところで、戸田建設なんですけれども、この金額だとすごく不自然というか、今、大きなところも仕事がないみたいですが、小さいと言ったら失礼かもしれませんけれど、区内の事業者の仕事の確保は非常に厳しくなっているんじゃないかと思います。そこら辺の考え方はどういうふうにしているのかということと、例えばＪＶを組むときはどういうふうにやっているのか。そこら辺を伺いたいと思います。","respondent":"市岡総務部長","answer":"この荏原西については、ご案内のとおり一連の入札経過の中で、不調に終わったとかいろいろなことがある中で、十分な競争性を確保するということで今回こういう入札をし、結果的に先行する工事との関連も含めて経過がありますが、原則は先ほど申し上げたとおり、区内中小事業者。","voiceIndex":30,"id":"exchange-008"},{"speaker":"宮崎委員","kind":"質問","question":"もう一つ報告事項との関連ですけれども、報告事項のほうは契約日が平成２１年８月２１日でもう契約が終わっていると思うんですけれども、外構工事は議案ですから、議決しないとだめなんですよね。私もよくわからないのでお伺いするんですけれど、例えば報告事項の資料の３ページのところの１番、２番というのは、外構工事が決まらないとだめなんじゃないかと思うんですけれど。","respondent":"宍戸施設整備課長","answer":"いろいろ使う設備類を発注したり、本体工事とすべて関連が出てきますので、その辺の関連について検討したいという準備行為がありますので、そうしたことから工事会社としては早く決まれば決まるほどその期間が長くとれますから。","voiceIndex":32,"id":"exchange-009"},{"speaker":"宮崎委員","kind":"質問","question":"やるとなるとそうだと思いますけれど、手続上、外構工事が否決されちゃった、だめだとなったら、これはもう８月２１日に契約しちゃっているんですよね。それは手続上どういうふうになるんでしょうか。","respondent":"宍戸施設整備課長","answer":"もちろん工事の段階ではいろいろ関連は出てきますけれども、手続的には分離発注でそれぞれ独立した工事ということですので、建設会社が決まる前に発注しても、手続上は全く問題ないのではないかと考えております。","voiceIndex":34,"id":"exchange-010"},{"speaker":"宮崎委員","kind":"質問","question":"私が聞いたのは、この議案が仮に否決となっても報告事項のほうの発注は続くということなんでしょうか、ということを聞いているんです。","respondent":"市岡総務部長","answer":"これは仮定のお話ですけれども、もし万が一そういうことがあれば、工事に支障が生ずるということになれば、法的には後処理のことをやらなければいけないということに理論的にはなりますけれども、先ほど施設整備課長が申し上げたとおり。","voiceIndex":36,"id":"exchange-011"},{"speaker":"宮崎委員","kind":"意見","question":"その辺、やはりおかしな話ですよね。議決されることが前提で話を進めているとしか思えないですよね。議会にちゃんと議案として出すのであれば、例えば否決された場合、今の部長のお話では、例えば損害賠償ということもあり得るんじゃないかという話じゃないかと思いますけれども、そういうことを想定されるということであれば、契約の仕方として、やり方が違うんじゃないかと。","respondent":"市岡総務部長","answer":"私が申し上げたのは、そういうことを想定しているわけではなくて、全体として工事を円滑にし、区内業者にも必要な時期に別途発注をするということが、工事全体の進捗を同時に進めていくためにどうしても必要だという観点から。","voiceIndex":38,"id":"exchange-012"},{"speaker":"宮崎委員","kind":"質問","question":"それはやはり議案のほうが前提になって、それに関連してこの工事が出てきているわけですから。今の説明はやはりちょっと。確かに手続は、小さな工事はそれはそれでやれるということなんでしょうけれど、いわゆる外構工事、本体工事が進まないということになれば当然こちらも進まないものですから、今の説明はおかしいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":40,"id":"exchange-013"},{"speaker":"土井委員","kind":"質問","question":"今のお話にも関連があるのでお聞きしたいんですけれど、何で分離発注をするのかというところにかかっていると思うんですよ。逆に言えば分割発注しなければこんなこと起きないわけで、全部ボーンとやってしまえば。それをなぜやるかという精神も生かさないでやれば、中小の区内の業者さんには物が行かなくなる可能性がありますよ、そういうことで私はそうじゃないですかと思うんですが、いかがでしょうか。","respondent":"市岡総務部長","answer":"土井委員がおっしゃるとおり、できるだけ受注機会の拡充、特に全体の工程の中で適しているものであれば区内の事業者に受注機会を拡大したいということがありまして、このような分離発注をしているものです。","voiceIndex":41,"id":"exchange-014"},{"speaker":"須貝委員","kind":"確認","question":"かえって地元の業者に注文を早くすることで、私はそれなりによいと。それで、ちょっと１点だけ質問を。報告案件についてですが、参考としてご意見をお聞きしたいんですが。グラウンドの照明設備。どうしても違和感がある。逆に南ふ頭公園、確かに場所が違うので地域に迷惑がかかる、かからないというのはあると思うんですが、はっきり人の顔も見える、競技するスポーツのボール等もちゃんと確認できる。","respondent":"宍戸施設整備課長","answer":"その辺は少し調べさせていただきたいと思います。グラウンド面については計算をして、それで設置しておりますけれども、そういう声があるのであれば、できる範囲の調整をしていきたいと思います。","voiceIndex":43,"id":"exchange-015"},{"speaker":"須貝委員","kind":"質問・要望","question":"できるだけ使う方の身になって、せっかく開放して区民の方に使っていただくんですから、できるだけよりよい方向で、もちろん地域の方にご迷惑をかけることは問題があると思うんですが、その辺照明のほうは上手く考えていただきたいという要望です。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":45,"id":"exchange-016"},{"speaker":"宮崎委員","kind":"提案","question":"うちは反対です。２つほど理由を挙げたいと思います。１つは、今の発注の仕方がやはりおかしいと思います。親がいいから、子どもも孫もというわけにはならない、親があるから孫もあるよという話はないですから、それはおかしいと。前提がこれは通ると、修正等あるいは否決もないということが前提での提案という報告にしか思えない。そういうやり方はやはりおかしいと思います。共産党としても反対です。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":50,"id":"exchange-017"}]},{"id":"topic-03","title":"第８３号議案 理科・算数教材の買い入れ","agenda":"第８３号議案 理科・算数教材の買い入れ","exchanges":[{"speaker":"土井委員","kind":"質問","question":"科学技術が進んでいるので教材もそういったものにと思うんですが、平成２１年度より先行実施をするということは、いつどういう形でどんな経過なのかによって、なぜ補正なのというのが一つ当然出てまいりますよね。ですから、この補正になぜのっているのということをお聞きしたい。それからもう１点は、国からの補助等はどのようになっているのかお聞きしたいと思います。","respondent":"金子企画財政課長、市岡総務部長","answer":"予算にかかわるご質問ですけれども、この理科・算数教材に関しましては当初予算にのっているものでございまして、今回補正でご提案をしているものではございませんので、ご理解いただきたいと思います。本件の契約議案の予算の財源ですが、基本的には国庫２分の１という制度があります。","voiceIndex":57,"id":"exchange-018"},{"speaker":"宮崎委員","kind":"質問・要望","question":"こういう学校で必要なものはその都度買う、私はそのほうが自然じゃないかと思うんですけれども、まとめて発注というのは何でこういうやり方になったんでしょうか。","respondent":"市岡総務部長","answer":"今回は、先ほど来ご説明のとおり学習指導要領の改訂ということで、単に備品を買うだけではなくて、理数教育の重視といいますか充実ということが政策目標となっておりまして、それに合わせて、備品購入だけでなく理科の授業時間の増なども含めて。","voiceIndex":60,"id":"exchange-019"},{"speaker":"宮崎委員","kind":"質問","question":"ちょっと、わかったような、わからないような感じなんですけれども。理科とかが弱いというので力を入れるよという話は聞いていたんですけれど、実際に現場でどういう教材が必要で、どういう授業をやるのかというのは……。その辺のところはどうなんでしょうか。今回こうやって教材をまとめて発注するというのは、私は今まで見たことがなかったので、それで聞いているんですけれど。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":62,"id":"exchange-020"},{"speaker":"須貝委員","kind":"質問","question":"参考までにお聞きしたいんですが、国の、文科省の学習指導要領で学習内容が変わって、こういうふうに器具、教材を購入することになったと思うんですが、品川区は平成２１年度より先行実施ということになりますと、まだ国の補助金として区のほうにくれるということは確定していないということですか。それはもう先に動いて購入して、問題がないんですか。それだけちょっと参考にお聞かせください。","respondent":"金子企画財政課長","answer":"先ほども申し上げましたとおり、２分の１の国庫補助を想定していますけれども、これについては一定程度内示の決定というのをいただいておりますので、確実になっていると考えております。","voiceIndex":65,"id":"exchange-021"}]},{"id":"topic-04","title":"を行います。 初めに、(1)新型インフルエンザ対策","agenda":"を行います。 初めに、(1)新型インフルエンザ対策","exchanges":[{"speaker":"土井委員","kind":"質問・要望","question":"インフルエンザ対策事業計画の増補版の３ページですが、勤怠管理の整理をちょっと説明していただきたいんです。どういうことなんですか。","respondent":"伊勢危機管理室長","answer":"現在これは既に行っているところでございまして、本人はもちろん病欠あるいは年次有給休暇で、家族または同居の親族の場合は、今現在の状況ですけれども、お医者さんの新型インフルエンザという診断書があれば、事故扱いという形でお休みしてもらっているです。","voiceIndex":78,"id":"exchange-022"},{"speaker":"宮崎委員","kind":"意見","question":"ちょっと具体的なことですけれども、学校のほうは学校閉鎖・学級閉鎖とあるんですけれども、保育園では登園の自粛というのと休園と２つの対応があるんですけれども、具体的にどういうふうなことになると登園自粛、休園となるのか。その２点です。","respondent":"伊勢危機管理室長","answer":"そういう面では、十分保護者の方に事前にご説明して、やむを得ない場合は来ていただくということで、休園としても、結局緊急保育ということでどうしても必要だろうということで、ほとんど全員の人が感染するということはちょっと考えにくいですけれども。","voiceIndex":82,"id":"exchange-023"},{"speaker":"宮崎委員","kind":"質問","question":"３名以上というお話だったんですけれども、休園の場合はかかっていない子も含めて、もうその保育園は休んじゃうわけですよね。そうすると、かかっていない子も休んでくださいという対応にならざるを得ないということですか。","respondent":"伊勢危機管理室長","answer":"基本的には登園自粛で、自主的に保育園に預けないということで。全員に休業ということはなかなかできないという実務的な問題がありますので、どうしても親の就業の関係でお預かりすることも想定して、今対応を考えているところですが、実質的にはそういうことが今の現状です。","voiceIndex":84,"id":"exchange-024"},{"speaker":"宮崎委員","kind":"質問・要望","question":"親御さんもいろいろ心配しているので、説明してあげてほしいというのは要望しておきたいと思います。ちょっと話が変わるんですけれど、前は発熱センターに電話が来て、そこで指示を仰いでということだったんですが、今はそれは変わっているんですけれども、発熱センターの役割が変わったよというお知らせは徹底しているんでしたっけ。","respondent":"伊勢危機管理室長","answer":"発熱センターができたときは、特定の病院を紹介していたですけれども、７月の終わりから、いわゆる特別な病院じゃなくて一般の診療所でも受診できるということになってありますので、今の相談センターにつきましては、かかりつけ医がいる方はかかりつけ医に。","voiceIndex":86,"id":"exchange-025"},{"speaker":"宮崎委員","kind":"意見","question":"ある方で、発熱センターに電話したら「混んでいるのでまたかけてください」という対応だったと言うんですよね。今のお話だと、もう大分切りかわっていて、そのまま受診してくださいということですけれども、前の宣伝が行き渡っていたからだと思うんですけれど、そういうものが解除になりましたとか、そういうお知らせが必要なのかなと思ったんですけれど、どうなんでしょう。","respondent":"伊勢危機管理室長","answer":"基本的にはホームページ、あるいは広報しながわでも随時、相当回数を重ねてやってありますので、その辺のお知らせは徹底してやっております。","voiceIndex":88,"id":"exchange-026"},{"speaker":"須貝委員","kind":"質問","question":"最近は健常者、どこにも持病がない方にも死亡例が発生しています。死亡とかそういう例が出てきているのは強毒化なのか、たまたま肺のほうに影響が来て亡くなるということもあると思うんですが、やはり危機管理としてそういう対応も必要じゃないかなと思うんですが、その辺、区としてさらに一歩対策をとるとか、そういうことはお考えなんでしょうか。","respondent":"伊勢危機管理室長","answer":"センサーはともかくといたしまして、そういう対応がいつでも機敏にとれるように、現在準備を進めているところです。","voiceIndex":90,"id":"exchange-027"},{"speaker":"土井委員","kind":"質問・要望","question":"子どもがかかって、ある種の解熱剤等を飲ませると、かえって悪くしてしまって脳症になりかねないものがあると言われていて、子どもの風邪薬には一般的には入っていないんだけれど、大人の風邪薬にはかなり入っているものがあるということなので、それを注意してくださいと言っているところもあるんですけれども、そういうことも細かに知らせてあげていただきたいと思いますので、つけ加えます。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":92,"id":"exchange-028"},{"speaker":"山元委員","kind":"質問・要望","question":"区の主催イベントの対応についてお聞きしたいんですけれども、感染の拡大につながる一つの基準、中止とか延期する基準というのは、どういうときに中止にしようとお考えなのかちょっと教えていただきたいと思います。それからその周知の方法、急遽中止になるとか延期になるというのはどういうふうに周知するとお考えになっているのか、教えていただきたいと思います。","respondent":"伊勢危機管理室長","answer":"以前の国等の行動計画ですと、必要に応じて国から都道府県あるいは市町村に中止等の要請をするということがうたわれていましたけれども、弱毒型の対応では今のところそういうことはございません。","voiceIndex":93,"id":"exchange-029"}]},{"id":"topic-05","title":"続きまして、報告事項の(2)「出資による権利」の譲渡","agenda":"続きまして、報告事項の(2)「出資による権利」の譲渡","exchanges":[{"speaker":"宮崎委員","kind":"質問・要望","question":"何点か聞きたいんですけれども、まずこの中沢ヴィレッジの経営が傾いた、いろいろ手を出してだめになったというふうに聞いておりますけれど、そこら辺をかいつまんで教えていただきたいということと、リゾート開発等に手を出して失敗しているところは多いんですけれど、区のほうはそういうことをつかんでいたのか、いなかったのかお伺いしたいと。次に、３,９００万円の保証金を出して３８０泊分あったと。","respondent":"榎本人事課長","answer":"そのときには現地に視察に行きまして、財務状況等の説明を受けたところ、ホテル事業自体はちゃんと収益が上がっていて、年商大体３０億円ぐらいの売上高があると、それが維持されていた状況でした。","voiceIndex":100,"id":"exchange-030"},{"speaker":"宮崎委員","kind":"質問・要望","question":"３８０泊の七、八割の利用ということだと、今回１１６泊に減ると逆に足りない感じになるのかなと思うんですけれど。これは計画案の可決となっていますけれど、場合によったら難しいということもあるのか、ないのか。その辺のところ、私は中身がよくわからないので、どういうふうに思っておられるかお伺いしたいと思います。","respondent":"榎本人事課長","answer":"この１,２００万円の保全の見通しですけれども、再生計画案どおり可決されればその部分の施設利用権は保証されますけれども、万が一計画がとんざしてしまうと、この部分の保全はなくなりますけれども、実際上は通常どおり営業をずっと今年も続けておりますので。","voiceIndex":102,"id":"exchange-031"},{"speaker":"宮崎委員","kind":"意見","question":"わかりました。最後に１点なんですけれど、区の職員互助会が受け入れるということだったんですけれども、職員互助会のほうはどういう手続でこれを決めるのか、そのとき意見はあったのか、なかったのか。受ける側の手続というか、そこら辺を聞きたいんですけれど。","respondent":"榎本人事課長","answer":"先ほど議員がおっしゃったように３８０泊を割ってしまうという部分がありますけれども、その部分も今後検討するという附帯をつけまして、理事会でこういう形での賛成という決定をいただいたところです。","voiceIndex":104,"id":"exchange-032"},{"speaker":"土井委員","kind":"意見","question":"やはり互助会ではありますけれども、職員の皆さんの福利厚生を担当する会というあれを持っているわけですね。したがってこの会が、余計なことだと言われれば余計なことで、心配するなと言われたらそれまでなんですけれど、どうなっていくのか、１,２００万円余をどう工面して進めていくのかというところがちょっと心配なので、少しだけ説明を。","respondent":"榎本人事課長","answer":"ということで、互助会会員に還元される事業ですのでこの負担をしていただいて、今後の事業継続を図っていくという形です。特別区互助組合からの返還金がありましたので、それも少し活用しながら、事業については継続をしていきたいと考えています。","voiceIndex":106,"id":"exchange-033"},{"speaker":"須貝委員","kind":"質問・要望","question":"品川区としての情報収集と素早い対処については、本当に感心します。ご苦労さまでした。ただ、ちょっとおかしいなというのは、２の経過のところで、職員の利用者数が減ってきたため、区は退会を申し出たとあるのに、下の区の対応では「福利厚生事業で一定の職員利用が見込まれることおよび職員互助会からの事業継続の要望を受けて」とあるんですね。その辺ちょっと見解をお聞かせください。","respondent":"榎本人事課長","answer":"決して互助会に押しつけたとかそういうことではなく、互助会のできる範囲の中で一番いい選択肢を見つけるという形で、こういう対応を実施してきたです。","voiceIndex":108,"id":"exchange-034"},{"speaker":"須貝委員","kind":"意見","question":"別に責めるとかそういうことではないんですが、品川区として実害が出る云々ということは確かに想定される、いかにうまく持っていって実害が双方ないようにというのはよくわかります。ですが、今後こういうふうに使うならば、区民の税金ではあるにしろ、つぶれないということがある程度認識できるような、将来の見通し的に大丈夫そうなものならば、区で持つ。もしほかに意見がありましたら。","respondent":"市岡総務部長","answer":"そのためにはどうしたらいいかという自主的なご意見がありまして、決して１人４,０００円ずつ供出したわけではありませんで、互助会の財源全体の見通しのつく中で、特定の人が負担をこうむることがないように、職員全体でこの利用継続をし、あるいは区の会計にも迷惑をかけない。","voiceIndex":110,"id":"exchange-035"},{"speaker":"若林副委員長","kind":"確認","question":"３,９００万円を分割返還にして、そもそも平成１７年に見直しがあったということで、いわゆる公費負担ということで理解をしていいのかということが１つ。両方同じような意味かもしれませんが、確認をさせていただいて。今、決算の時期ではあるんですが、そもそも区の財産として今までどういうふうに処理をされていたのか。ちょっとお聞きしたいと思います。","respondent":"榎本人事課長","answer":"ただし、互助会として福利厚生事業の責任をとりますので、その中でどういう形がいいのかというのは、この再生計画案が通った後、また互助会として全体の計画を見ながらどういう形が一番いいのか検討していきたいと聞いてあります。","voiceIndex":112,"id":"exchange-036"}]},{"id":"topic-06","title":"品川区役所職員食堂での食中毒","agenda":"品川区役所職員食堂での食中毒","exchanges":[{"speaker":"須貝委員","kind":"質問","question":"検体・検食をやっているということですが、主に食材は何だったのか特定はできたんでしょうか。","respondent":"榎本人事課長","answer":"特にどれを食べたからということではなく、メニューの中の複数にわたってサルモネラ菌が検出された、要はそのサルモネラ菌に感染した人の手から、接触でずっと伝わった形というふうに聞いてあります。","voiceIndex":118,"id":"exchange-037"},{"speaker":"若林副委員長","kind":"質問・要望","question":"この文面の、従業員１人の方から感染が広がっていったという理解をしていいのかという確認と、直接には関係ないですけれど、この契約はどうなっているのか教えていただきたいと。","respondent":"榎本人事課長","answer":"そういった意味で、全員に治癒するまで営業再開できないということで、営業の再開がおくれたということもあります。１名がその菌にさわった関係で、ほかの人も接触感染みたいな形で広がったというふうに聞いてあります。","voiceIndex":120,"id":"exchange-038"},{"speaker":"若林副委員長","kind":"意見","question":"前段の、要するにだれがとか、どの食材がというのはそもそも特定できないというふうに理解をしますが、それでいいのかどうか。その辺の見直し、これはこれとして、別にどの業者がやっても起きたかもしれませんけれど、そういう部分で見直しというのは考えておられるのか。","respondent":"榎本人事課長","answer":"やはりこのアターブル松屋フードサービスは長くずっと入っておりますので、今後実際にどういう形で継続するのかも含めまして、プロポーザル方式等も含めまして、ある程度刷新した形でできるかどうかは検討していきたいと考えております。","voiceIndex":122,"id":"exchange-039"}]},{"id":"topic-07","title":"庁舎耐震工事に伴う梁補強工事","agenda":"庁舎耐震工事に伴う梁補強工事","exchanges":[{"speaker":"宮崎委員","kind":"質問","question":"ちょっと細かいことですが、スリットの件なんですけれど、柱と壁の間にすき間をつくるということで、庁議室は何かあるんですか。","respondent":"宍戸施設整備課長","answer":"このスリット工事ですが、柱の粘り強さを生かすために、壁が柱にくっついていると構造的に悪さをするというか、寸断破壊と言うんですけれど、応力が集中して構造的に粘り強さが発揮できないということが、阪神淡路の地震のときの経験などでわかってまいりまして、それ以来。","voiceIndex":128,"id":"exchange-040"},{"speaker":"宮崎委員","kind":"質問","question":"そうすると、柱と壁で頑丈にするんですよというふうにしていたんだけれど、耐震化という面では全く意味がないという感じになっちゃうんですか。","respondent":"宍戸施設整備課長","answer":"この辺非常に、構造計算的には上下の階についてのバランスですとか、平面的なバランスもありますが、そういったものを全部考慮して、建物としてうまく地震力に対応していくということで、壁を足して全体を強くする部分と。","voiceIndex":130,"id":"exchange-041"},{"speaker":"宮崎委員","kind":"質問","question":"何となくわかったんですけれども。そうすると、今も工事はやっていますけれど、それとの関連で出てきたということなんでしょうか。それと、この平面図は５階ですけれども、各階そういうふうにやるのか。免震工事は３６億円という説明だったと思うんですけれども、契約的にこれは入っているのか、入っていないのか。伺いたいと思います。","respondent":"宍戸施設整備課長","answer":"そういうことから、庁議室その他の部分については真ん中のところで踏ん張って、周りは比較的軽目の構造ということでもともと設計されたもので、免震装置で地震力を吸収しても、なお対処をしておいたほうがいいだろうという場所について。","voiceIndex":132,"id":"exchange-042"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?Template=document&Id=1832#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=5&TermStart=2009-01-01&TermEnd=2009-12-31"}],"sourceMeta":{"pages":0,"characters":40409,"voices":137}},{"id":"h21-20090925-6","meetingId":"h21-cm09","date":"2009年9月25日","dateIso":"2009-09-25","committee":"区民委員会","time":"午前１０時０１分～午後 １時４１分","status":"正式会議録","sourceType":"formal","overview":"区民委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を16件抜き出しています。","hasFullText":true,"topics":[{"id":"topic-01","title":"の１ 報告事項","agenda":"の１ 報告事項","exchanges":[{"speaker":"渡部委員","kind":"質問・要望","question":"平塚小学校の体育館を、広域の団体の方が利用されていると思うんです。少年・少女の野球をやったり、サッカーをしたり使われています。やはり、平塚小学校の一時避難所の機能はどういうような形で、来年からは解体工事が始まるということですので、再来年以降はどういうふうにその辺がなっていくのか教えていただきたいと思います。","respondent":"堀越文化スポーツ振興課長","answer":"防災の部分ですが、平塚小学校は一時避難所という形ですので、新しい施設になった後も、基本的には同じような防災機能を維持するような方向で検討を進めているというふうに、防災課のほうからも聞いておりますので、そのような形で進んでいくというふうに思います。","voiceIndex":5,"id":"exchange-001"},{"speaker":"渡部委員","kind":"質問・要望","question":"広場という言葉は、実はここにも当てはめていた経緯があって、広場というと更地というイメージがあって、使えるのかと勘違いをしていて、絵を見たらぽっかり山が出ていて、ここは公園みたいな感じだというようなところがあって、ぜひ地域との話し合いの中で、ここはこういう形だというようなご説明をいただきたいというのは要望としてあります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":7,"id":"exchange-002"},{"speaker":"三上委員","kind":"質問・要望","question":"ですから、そういった点にいたっては、十分地元の意見を調整していただきながら、不満が出ないような形でしっかりと今から準備していただきたいと思います。これは要望しておきたいと思います。ですから、１階平面図を見ると、東側広場は階段しかないような感じですけれども、きちんとスロープをつくるということはやったほうがいいんじゃないかと思います。","respondent":"堀越文化スポーツ振興課長","answer":"大変見にくくて恐縮ですが、そちらのほうからグラウンド部分から入っていただけるという形になってありますので、そういった点も配慮していきながら進めていきたいと考えています。","voiceIndex":8,"id":"exchange-003"},{"speaker":"三上委員","kind":"質問・要望","question":"今までの平塚小学校で防災訓練をやろうとすると、荏原三丁目と荏原四丁目町会、平塚四丁目町会がここに集まって防災訓練をやるということになったときに、町会関係の機材置き場はそれぞれ分散する形で置いたほうがいいのか、それとも１カ所に三つの町会から要望のある同じような広さのものを整備してつくるという部分も含めて、町会との話し合いの中にも、そういった点を視点において。","respondent":"堀越文化スポーツ振興課長","answer":"実際の使い方ですけれども、町会のほうはどうかというあたりにつきましては、防災課のほうで十分検討しておりますし、実際に全庁的な検討の打ち合わせの場にも防災課も参加していますので、ご指摘のあった部分も含めて伝えて、どういうやり方をするかというのは。","voiceIndex":10,"id":"exchange-004"},{"speaker":"三上委員","kind":"質問・要望","question":"最初の説明はそういう話ではなかったので、倉庫というのは備蓄倉庫的な、区が防災面の倉庫として用意をするというようにおっしゃられたと思ったので、そういうことでなるならば、それはそれでしっかりとやっていただきたい。仮に、防災備蓄倉庫という、備蓄の面に関してはどうするのかということについては、どう検討されているんですか。","respondent":"堀越文化スポーツ振興課長","answer":"実際、これから実施設計に入っていく段階で、運用面も含めて検討していく段階だと思いますので、私のほうからどういう形になっているというのは、現在承知しておりません。ご要望があったということは、所管の防災課のほうに伝えさせていただきたいと思います。","voiceIndex":12,"id":"exchange-005"},{"speaker":"三上委員","kind":"質問","question":"そういった点も含めたものを、きちんと考えたものにしていって、防災という視点がここで説明できないということであるならば、同じ施設の中につくるわけですから、そういった点でのどこの所管に聞いたら、これが、あれがというような説明であっても、これは行革委員会でどこまで説明しているのかわからないけれども、そういった点ですべてを含んだものが検討されているのかどうかということが。","respondent":"堀越文化スポーツ振興課長","answer":"先ほどの防災倉庫をはじめといたしまして、それから下水道ですとか防火水槽、それから非常用電源装置と防災無線、避難所として中の部屋をご利用いただくような設備も提供させていただいていますので、細かい使い方については、先ほど答弁をさせていただいたとおりですが。","voiceIndex":16,"id":"exchange-006"},{"speaker":"渡辺委員","kind":"質問・要望","question":"先ほども指摘があったので、行革委員会での申し入れとか提言にもあったように、これまでの経緯を十分尊重した施設利用という点で、お願いしたいということと、その辺の認識を伺えればと思います。広場と公開空地の中で、例えば中を例に取ってみても、管理をされたら制限時間を設けた施設であるのか、それとも２４時間敷地内は出入り自由であるのか、この辺の確認を教えていただければと思います。","respondent":"堀越文化スポーツ振興課長","answer":"地元の方のご意見も伺っているんですが、夜遅くまで９時、１０時まで施設が開いているのであれば、閉鎖してもいいんじゃないかというご意見もいただいておりますので、引き続き地元の方のご意見を伺いながら検討を進めていきたいと考えております。","voiceIndex":18,"id":"exchange-007"},{"speaker":"渡辺委員","kind":"質問・要望","question":"駐車場の件で、開いていたら一般開放というか、料金制でいいんじゃないかという意見もあると思うんですが、段階的に、弾力的に検証した上で、オープンした後、検証するという前提の打ち出し方も一つかなと思っています。最初に決まったからこうだという固い考え方ではなくて、実態に見合うところも、最初の途中であってもいいかなと。要望で終わります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":20,"id":"exchange-008"},{"speaker":"松澤委員","kind":"質問・要望","question":"今の駐車場の件ですけれども、この施設についての３０台ぐらいというでしたけれども、みんなとの協議の過程で、商店街から駐車場を増やしてほしいという要望があります。それと、ここはホームレスがよくいたところですから、公園のほうのトイレを。時間的には十分に近隣の方たち、あるいは所管で検討する時間があったというふうに理解してよろしいですか。","respondent":"堀越文化スポーツ振興課長","answer":"幼保一体施設の部分ですが、一貫校の移転日が確定して、内部の検討をして、それから実際に地域の説明ですとか、町会長会への説明、それから議会への報告、それからパブリックコメント等の経過を踏んでおりますので、内部の検討期間、それから説明する機会については。","voiceIndex":21,"id":"exchange-009"},{"speaker":"三上委員","kind":"意見","question":"それも嫌だという人は、時間貸しの駐車場がこの辺に増えてきたがために、今は値段を下げる時間貸しのところが結構増えてきたということで、あわせるような部分の感じの地域かもわかりませんけれども、できたところに入れてというようなことから考えたときに、私は３０台弱というのがいいのかどうかといったら、私は決していいとは思っていない。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":23,"id":"exchange-010"},{"speaker":"南副委員長","kind":"質問・要望","question":"スポーツ施設について、ここで言っているのはどんなスポーツができるのか、例えばスリー・オン・スリーとか、フットサルとか、結構少人数で対抗試合ができるようなスポーツが結構若者に好まれているということで、私たちも要望をたくさん受けるんですけれども、そういうスポーツが利用可能なのかどうか、道具も含めてやってほしいのと、それから施設を申し込むときにホームページで申し込む方が結構多いです。","respondent":"堀越文化スポーツ振興課長","answer":"障害者の客席については、舞台・ホールの客席も車いすスペースを用意する予定です。トイレについても、そういた対応を取るという形で準備を進めています。それから、駐輪場が１８０台程度を予定しています。","voiceIndex":24,"id":"exchange-011"},{"speaker":"南副委員長","kind":"質問・要望","question":"多岐にわたって、ありがとうございました。とりわけ、先ほども申し上げたんですけれども、若い人たちが経済的にも十分にない中で、しかしスポーツは楽しみたい、文化的な状況にも触れたいという気持ちは高いし、あって当然だと思うし、それを満たしてあげられるような施設の内容であってほしいと思います。要望でいいです。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":26,"id":"exchange-012"},{"speaker":"南副委員長","kind":"質問・要望","question":"品川区立体育館の部分で、裏面の区民満足の視点のところに書かれていた利用者の要望を把握した教室運営ということで、何回か繰り返し説明があったんですけれども、例えばどんな教室内容なのか、それを教えていただきたいと思います。それから、そういう角度で利用状況というか、内容を選考したというのは、文化振興事業団のほうではなかったのか、あったのか、その辺だけ知りたいと思います。","respondent":"堀越文化スポーツ振興課長","answer":"文化振興事業団につきましては、施設の運営という形が指定管理上ありますので、事業について対象というような形になってございませんので、施設運営においていろいろな工夫を図ってきたです。","voiceIndex":31,"id":"exchange-013"},{"speaker":"南副委員長","kind":"質問","question":"そういう点で、所管としてこういう内容で報告を受けて、「わかりました。是非とも、効率的な運営とか効果的な施設のあり方だとか、指定管理者制度をしながら、本当に区民の要求に合った、区の目的に沿った内容の施設になってきているのかというところが、これだけでわからないので、その辺の評価というのは、区としてはどういうふうに持っておられるのか伺いたいと思います。","respondent":"堀越文化スポーツ振興課長","answer":"今、ご紹介をさせていただいた人気のあるメニューのほかに、バトミントンでの利用ですとか、さまざまなスポーツ、種目についてもご利用をいただいておりますし、細かいところの要望でいえば、例えばすのこを設置してくださいとか、細かいものもありますが。","voiceIndex":33,"id":"exchange-014"},{"speaker":"南副委員長","kind":"質問・要望","question":"しかし、ご意見箱でいろいろな要望を受け止めてということがあるけれども、もう少し区が指定管理者制度として、こういう団体に委託をして事業運営をしていただくという点で、そこの団体から出てきた評価、自分たちが持った評価をもってよしとするということじゃなくて、やはりもう少し別の角度から、第三者的な視点から掘り下げて見ていくことを抜きにしていいのかという不安を持っています。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":35,"id":"exchange-015"},{"speaker":"三上委員","kind":"質問","question":"平塚橋会館の耐震改修は、来年あたりからやるのかなと思ったけれども、基本的には平成２４年からやるというだけの話ですか。","respondent":"中山地域活動課長","answer":"区営住宅を計画的に耐震改修を図るということで、それと併せて耐震化工事を行うですので、建設委員会で資料による報告がありましたということで、当委員会でも集会所に係るということで、ご報告をさせていただきましたが、工期等。","voiceIndex":45,"id":"exchange-016"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?Template=document&Id=2562#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=6&TermStart=2009-01-01&TermEnd=2009-12-31"}],"sourceMeta":{"pages":0,"characters":25337,"voices":53}},{"id":"h21-20090925-7","meetingId":"h21-cm09","date":"2009年9月25日","dateIso":"2009-09-25","committee":"厚生委員会","time":"午前１０時０２分～午後２時２３分","status":"正式会議録","sourceType":"formal","overview":"厚生委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を40件抜き出しています。","hasFullText":true,"topics":[{"id":"topic-01","title":"２番目の、都営大井林町アパート跡新高齢者住宅等基本設計簡易プロポーザル実施","agenda":"２番目の、都営大井林町アパート跡新高齢者住宅等基本設計簡易プロポーザル実施","exchanges":[{"speaker":"安藤委員","kind":"質問・要望","question":"区のこういう施設をつくるという考えに基づいて設計業者を公募するということなんですけれども、地域優良賃貸住宅ということを中心にこの住宅をつくるということなんですが、この地域優良賃貸住宅というのはどういう施設なのかというのを、改めて教えていただきたい。","respondent":"冨岡高齢者福祉課長","answer":"それで、これから予定をしております新高齢者住宅ですけれども、原小学校跡の施設につきましては、これは特定の介護保険上の網もかかっておりますけれども、これは新高齢者住宅でございまして、これにつきましては建設のときから助成をいただける。","voiceIndex":9,"id":"exchange-001"},{"speaker":"安藤委員","kind":"質問","question":"今のご答弁の中でわからない点がありましてお伺いしたいんですが、従来とどう違うのかというところで、新しいところ、原小学校跡地のところを例で出されてご説明いただいたんですが、家賃助成も可能になったということだったんですけれども、従来と、とりわけ利用料の面ではどういうふうに違うのかなというのがちょっとわからないので。お伺いします。","respondent":"冨岡高齢者福祉課長","answer":"ハードの部分でも強化しているし、ソフトの部分でも強化しているですので、それに応じて同じ家賃形成になるかどうかというのは、それぞれ性格が違えば、高齢者優良賃貸住宅という制度の中での家賃形成になるかと思いますので。","voiceIndex":11,"id":"exchange-002"},{"speaker":"安藤委員","kind":"意見","question":"将来どうなるか不安を抱えながら暮らしている高齢者の方というのは、孤立しがちな方も増えているなと実感しているんですけれども、今までにない機能を備えた高機能な施設ということでも、一部の方しか入れないような施設、高嶺の花ですと、せっかくの意味も薄れてしまいますので、できる限り多くの方が入れるような配慮というのも、今回は設計の話ですけれども、これから考えていただければと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":13,"id":"exchange-003"},{"speaker":"山路委員","kind":"質問・要望","question":"２点目は、住み替え用住宅の説明があったんですが、アンケートをとってということですけど、例えば３ＤＫに高齢者１人で住んでいる人がコンパクトなこちらに住み替えをして、その広いところは処分すると言われましたけど、若い人に貸すマッチングを解消するのがあくまで住み替えの目的じゃないでしょうかね。そこをしっかり説明していただきたいと思うんですが。","respondent":"冨岡高齢者福祉課長","answer":"手元には資料はございませんけれども、設備的にも今まで以上の最新の設備を使って対応できるというふうに理解しているところです。","voiceIndex":14,"id":"exchange-004"},{"speaker":"山路委員","kind":"質問・要望","question":"特に関西地方で幾つか、非常に人気が高くて、設置されたところがあるんですけど、地方自治体が、高齢者の方が住宅で年をとって介護の必要があったら施設に入所できるという、最も安心な、一番求められていることではないかと思うんですけれども、最後にもう１点。住み替え用は１人用ではないんでしょうか。世帯用が入っていますけれども、これでいいんでしょうか。説明していただきたいと思います。","respondent":"冨岡高齢者福祉課長","answer":"ご指摘いただきましたこの施設ですけれども、先ほどの原小学校跡の展開版ということで、原小学校跡につきましては、１０月１日に国土交通大臣から大臣表彰をいただける先駆的な事業だということで、それを踏まえまして、今後も利用者。","voiceIndex":16,"id":"exchange-005"},{"speaker":"鈴木委員","kind":"質問","question":"そうすると、区の方向性が、例えば２０室つくると言ったときと４０室つくると言ったときと、その考え方によって運営に開きが出てしまうと思うんです。例えば今、１０月２０日で第一次選考が終わってしまって、そこから先に全く違うパターンの部屋が出てきたときに運営できるんですかと私は疑問に思うんですけれども、そこら辺、どうお考えになっていらっしゃるのか。","respondent":"冨岡高齢者福祉課長","answer":"アンケートにつきましても、当然基本設計をやっている間の時期にはまとまって、それの評価が反映できるような形で対応できるということで、進みぐあいに合わせましてその辺の話は事前に織り込み済みで説明をしておくということで、支障のないように進めてまいりたいと思います。","voiceIndex":18,"id":"exchange-006"},{"speaker":"鈴木委員","kind":"質問・要望","question":"内容としてはわかるんですけど、基本設計の段階というのは、すでにある程度事業所としては数字が固まっている中で、飲み込めるだけの変動なのか。いい場所ですし、近くに小規模多機能があるところにもう一つ小規模多機能が並んでしまうような地域にはなるんですけれども、ぜひいいものをつくっていただくことはお願いいたしますので、それは要望です。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":20,"id":"exchange-007"},{"speaker":"飯沼副委員長","kind":"質問・要望","question":"どういう施設にでき上がるのか、まだちょっとイメージがよく浮かばないのでお伺いしたいんですけれども、原小学校の後は介護保険の網かけがかかっている。その辺の高めていく予定というあたりを、もうちょっと具体的に教えていただきたいのと、対象者がどういうぐらいの人たちを対象としてイメージを描いてつくるのかというのをまず教えてください。","respondent":"冨岡高齢者福祉課長","answer":"対象者の方と、どういう性格の住宅かということだと思います。介護保険上の特定の施設ということは予定をしておりません。下に地域密着型の多機能ホームもつきますので、そうしますと、入口につきましては、現在の高齢者住宅に入居されている方と同じような状況になります。","voiceIndex":21,"id":"exchange-008"},{"speaker":"飯沼副委員長","kind":"質問","question":"ということは、高齢者住宅としていらっしゃって、１階の小規模多機能の介護機能が必要になったときに使えるというような形でいいのでしょうか。その辺と、これからプロポーザルで契約をするわけなんですけれども、運営がどうなっていくのかというのと、住み替えのとかいろいろ入っているのでなかなか難しいと思うんですが、従来型の優良賃貸住宅と比べると利用料はどうなのか。その辺もお願いします。","respondent":"冨岡高齢者福祉課長","answer":"その候補者ということでは、また議会でご審議をお願いして、その後進めていくということになろうかと思いますが、今の段階ではまだあくまでも事業者ということで、それで進めします。","voiceIndex":23,"id":"exchange-009"},{"speaker":"飯沼副委員長","kind":"質問・要望","question":"２万５,６００円ですか。お金の面でどうなっているのか教えていただきたいのと、今後の日程のところで、第一次選考で大体５社ぐらいに絞るとさっきご説明があったんですけれども、この辺はどういう資料に基づいて第一次で絞られるのか、その工程の作業のところで教えていただきたいと思います。","respondent":"冨岡高齢者福祉課長","answer":"助成金につきましては、建物についても建設費の助成金が出てまいります。それから、利用に際しましては、利用者に２万５,６００円という先ほど申し上げた減額の措置を高齢者型の地域優良賃貸住宅にも適用されるです。","voiceIndex":25,"id":"exchange-010"},{"speaker":"飯沼副委員長","kind":"意見","question":"高齢者の住宅は不足をしている状況なので、いろいろな方が待っていらっしゃると思うので、無事にできるといいなと思っているのが一つと、住宅がものすごく高くて、経済的なところで負担も大きいというところでは、都営をつくってほしいとか、区営をつくってほしいという要求もいっぱいあるので、なるべくいろいろな手立てで、少しでも安く利用できるような住宅を希望して終わります。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":27,"id":"exchange-011"},{"speaker":"山内委員","kind":"質問・要望","question":"これはちょっと要望になってしまうかもしれませんが、建設後の運営についてということでちょっと触れさせていただきたいんですけれども、私ども自民党が２年前ですか、愛知県の豊田市に伺ったときに、愛知県は比較的喫茶店の文化が非常に根づいているところで、ある喫茶店に入ったときにこれはおもしろいなと思ったんですけれども、配食サービスが普及しているという中で。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":28,"id":"exchange-012"},{"speaker":"金野委員","kind":"質問・要望","question":"１点目に、すごく初歩的なことなんですが、この地域優良の優良という意味は、これまでご説明いただいたお答が来るのかもしれないですが、あえてこの優良というのはどういうふうにいいものなのかを一つお聞きしたいのと、２点目に、先ほどもある委員からご質問がありましたけれども、ここの住宅は現在の高齢者住宅と入口が同じということですが、入居要件というんでしょうか。","respondent":"冨岡高齢者福祉課長","answer":"そうしますと、高齢者の方というのはなかなか思い出の家具とか、愛着のある道具とかをお持ちになって引っ越してこられるということでありまして、それを逆に、どういうふうに収納スペースにとったほうがいいのか。","voiceIndex":29,"id":"exchange-013"},{"speaker":"金野委員","kind":"質問・要望","question":"要件については、制約がないということですので、その制約がないというのがどこまでなのかというのはこれからなんだろうと思うんですけれども、すごく抽象的な言い方ですけれども、戸数は限られておりますが、今までの要件よりは緩和された形で住まいを求める方に対して入っていかれる要件にしていただきたいという要望と、あと、住み替え用というところでの要件はどういったところがあるのか。","respondent":"冨岡高齢者福祉課長","answer":"住み替えにつきましては、先ほども申し上げましたように所管が異なるということと、今後詰めていくということでご理解いただきたいと思います。","voiceIndex":31,"id":"exchange-014"},{"speaker":"鈴木委員","kind":"質問・要望","question":"２回目の質問になって申しわけありませんが、確認してもらいたいことがあります。その辺の状況はどうなっているのかというのが１点。閑静だし。たしかあの敷地の中に大きな木が２本、まだ残っているんじゃないかと思うんですけれども、緑を生かすという意味で、でき上がった建物が地域にマッチするような形の設計も、このプロポーざるの中に入れておいてもらいたいという、その辺の確認を二つお願いします。","respondent":"冨岡高齢者福祉課長","answer":"その後、契約等に入ってくるという進みぐあいです。それから、緑を生かすマッチングにつきましては、これは承りまして、これから進めます基本設計の中でどういうふうに反映させるか検討します。","voiceIndex":33,"id":"exchange-015"},{"speaker":"鈴木委員","kind":"意見","question":"考えてみれば、まだ土地を取得していない中でどこまでいけるのか。それから緑を生かすことで、公園と小学校がくっついている中で、その辺も立会小学校がちょうど隣接している状況で、敷地の部分によって道路を挟むかどうか、小学校とほとんどくっついた部分もあるので、その辺もうまく活用できればというのは今でも思っていまして、その辺も設計に生かしていただけれるようお願いします。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":35,"id":"exchange-016"},{"speaker":"石田委員","kind":"質問・要望","question":"１点だけ要望を含めて区のお考えをお伺いしたいんですが、こういった高齢者のための住宅だったり、また障害者のための施設を造る際に、そこの施設の部分だけではなくて、その周りの道路とかをある程度把握していかないと、そこの施設ができたら交通の環境というのががらっと変わってしまって、例えば今まではあまり気にしなかった段差が。","respondent":"冨岡高齢者福祉課長","answer":"それで、今回の林町の後の住宅ですけれども、これはさっき鈴木委員がおっしゃったように住宅地ということで、今までも都営住宅ということで利用されていたという形で、基本的には住宅機能ということで機能を変えるわけではありませんが、道との接合部分とか。","voiceIndex":36,"id":"exchange-017"},{"speaker":"飯沼副委員長","kind":"質問","question":"小規模多機能のことについてお伺いしたいんですが、１階部分が小規模多機能の居宅介護ということで、規模とかどういう内容なのかというのがわかる範囲でいいんです。地域的に小規模多機能がどの辺を網羅して受けとめる施設になるのか教えてください。","respondent":"冨岡高齢者福祉課長","answer":"エリアでありますけれども、これは先ほど委員からもお話ありましたが、通りを隔てましてありますので、大体その辺で別れて東大井の方のエリアになるのかなというのが一番わかりやすいと考えていますが、詳細についてはまた今後詰めてまいりたいと思います。","voiceIndex":38,"id":"exchange-018"},{"speaker":"飯沼副委員長","kind":"質問","question":"内容についてなんですが、デイとショートですか。もうちょっと膨らむんですか。もうちょっとその内容的なもの、どういうものが期待できるのかなと思っているんですが。","respondent":"冨岡高齢者福祉課長","answer":"あわせて、介護者の方で必要に応じて、そんなに長い時間ではないというふうに聞いていますけれども、ちょっと気がかりな場合には訪問もどうですかというような形で、地域にお住いになって、そのまま慣れたスタッフにケアを受けるという仕組みでありますので。","voiceIndex":40,"id":"exchange-019"}]},{"id":"topic-02","title":"３番目の平成２０年度指定管理者の管理に対するモニタリング・評価の結果","agenda":"３番目の平成２０年度指定管理者の管理に対するモニタリング・評価の結果","exchanges":[{"speaker":"安藤委員","kind":"質問・要望","question":"区としては、この裏面の総括、評価に対してどのように支援を行っていって改善につなげていくのかというところを見ると、２ページの方では特にそこに関して「こういうことで打開できるんじゃないか」とか、「こういう支援を行っていく必要があるんじゃないか」とか、そういう点が若干欠落しているように見えてしまうんですが、ここら辺のお考え、事業者の方で出されている改善の必要な内容に関して。","respondent":"冨岡高齢者福祉課長、木下健康福祉事業部長","answer":"ご指摘のように介護職の慢性的な人材不足という表現があったということで、これは文章に出ると強調している部分があるかと思いますが、私も先ほど説明の途中で申し上げました。ただし２カ所だけ、７ページと９ページについては、「利用率のさらなる向上に努めること」というのが上がっているということでありますので、経営会議の方の評価と。","voiceIndex":49,"id":"exchange-020"},{"speaker":"安藤委員","kind":"質問・要望","question":"そういうような状況もあるので、今年も決して楽観はできないと思っていますし、それならば、平成２０年度の総括シートが出たわけですから、その時点で出された問題に対してもう少し突っ込んで検証して、裏の２ページのところの「区側の評価の視点」というところで、そこに関して突っ込んだ何らかの分析ですとか、今後の改善方向というのを出してしかるべきなんじゃないかと思いますけれども。","respondent":"木下健康福祉事業部長、冨岡高齢者福祉課長","answer":"私の方からは、経営会議における検証ということですけれども、まず、指定管理者の方からは報告書というのを、うちの方でマニュアルが決まっておりますけれども、その前年度の報告書が大体６月ごろに上がってまいります。しかも、期限を５年なら５年ということで、その中間のところですが、まず、各施設がいろいろな人的状況があった場合は、これは法人に指定管理委託をしているわけですので、法人は法人のお考えがあって、法人の方針により。","voiceIndex":52,"id":"exchange-021"},{"speaker":"安藤委員","kind":"質問","question":"「慢性的な」というところがポイントなんじゃないか。ですから、去年は乗り切ったので今年は大丈夫だというふうに考えてしまうのはどうかなと思うんです。そして、それはあるべきだったし、今後もまだまだ続く慢性的な人材不足、介護現場の未来がなかなか見えない、区民サービスも向上させていけないという点から見てすごく大事だと私は思っているんですが、ぜひお考えをもう一度お伺いしたいと思います。","respondent":"木下健康福祉事業部長","answer":"この総括シートに職員体制を書くべきだというお話かと思いますけれども、これはどちらかというと指定管理者側が国の定めた基準、つまり３対１に基づいて人員配置をするというのが指定管理者側の責務でありますから、当然そのとおりになされている。現実にされております。","voiceIndex":55,"id":"exchange-022"},{"speaker":"山内委員","kind":"質問","question":"これはちょっと理解できないなと思うんですけれども、いわゆる利用率が低いほうが、逆にしっかりとした家庭での介護なりそういうことができているという中で、そういうことができない方がこの施設を利用するというようなことだと私は思うんですが、品川区は逆にこの利用率を下げることに努力をして、施策として行っていかなきゃいけないんだけど、最後に「利用率の向上を図る」というのは。","respondent":"木下健康福祉事業部長","answer":"しかし、ＳＯＳの方については、上手につなげることによって在宅介護が引き続き続けられるように応援していきましょうと、こういうことでトータルに見ていただければと考えています。","voiceIndex":57,"id":"exchange-023"},{"speaker":"山内委員","kind":"質問","question":"経営的に見たらそれは利用率を上げたいというのはわかるんですよ。ただ、介護を経営的に見るというのは、我々からしてみるといまいち納得いかないというか、いまいち浮かんでこないんですよね。例えばこの「さらなる利用率の向上を図ること」というのも、もう少しこの言葉というんですか、文言を変える必要があるのではないかなと思うんですよ。","respondent":"木下健康福祉事業部長","answer":"そういう側面の見方が一つありますが、今のご指摘の部分について申し上げると、必要な方に必要なサービスがつながるよう、さらなる努力が必要だということになるんだと思いますけれども、さっき申し上げましたように。","voiceIndex":59,"id":"exchange-024"},{"speaker":"鈴木委員","kind":"質問","question":"例えば品川総合福祉センター全体がどういう運営をしているかというのはここには出さないというのは当然わかっているんですが、逆に言うと、そういう事業主体が現在経営が成り立っているのかどうかというのもどこかにうたっておいてほしいなという気がします。それとも事業所と指定管理者との接触状況、その連絡状況というのは区はどう把握しているか。その辺の答えをいただけないでしょうか。","respondent":"木下健康福祉事業部長、冨岡高齢者福祉課長","answer":"そういうような、心配しなければいけないようなことが起こらないように、我々としては、これは品川方式になると思いますけれども、心配するような状況にならないようないろいろな面での支援をしていくことによって。近隣の居宅介護支援事業所からの部分ですけれども、これにつきましては区の方にも事業所から相談がありました場合には近隣の方に話をつないだり、もちろん支援はしてまいっているところです。","voiceIndex":61,"id":"exchange-025"},{"speaker":"鈴木委員","kind":"質問・要望","question":"私どもがその事業所の全部の決算を見ちゃうというのは変な話になると思うし、でも、役所がいろいろな事業をやっている中で、この介護部分だけなのか、全体の事業まで見なきゃいけないのか、全体論になっちゃいますけど、その辺も十分注意しておいてもらいたいなというのを要望しておきます。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":64,"id":"exchange-026"},{"speaker":"飯沼副委員長","kind":"質問","question":"この間、私は区内だけじゃなくて、介護施設もそうですし、障害者の施設もすごく人が足りなくて大変だという声をあちこちで伺っているんですね。先ほど来からのご答弁を伺っていると、「解決しています」というような感じで、一つには認識がすごく大事で、それをどう一緒に解決していこうかなというところがすごく大事であると私は思う。夜勤なんかがものすごい。夜勤の回数とかも把握されているのかどうか。","respondent":"冨岡高齢者福祉課長","answer":"ただ、もちろんこれは介護の基準を満たしながら、利用者のために一生懸命サービスを提供しているという側面もありますし、確かに平成２０年度はこういう状況があったということでありますが、今回の介護報酬の改定。","voiceIndex":65,"id":"exchange-027"},{"speaker":"飯沼副委員長","kind":"質問・要望","question":"夜勤の回数とかなんかは教えていただけるんですかね。細かくはいいんですが、特養のところの夜勤の回数とかは、今、出るんでしょうか。例えば１３０％とか。そういったところの調整がうまくいっているのかなというのをお伺いしたいのが一つです。その辺は、施設に対しての基準とか、マニュアルとか、そういった水準を保つような避難訓練のあり方とかというのがあるのかどうか、教えてください。","respondent":"木下健康福祉事業部長、冨岡高齢者福祉課長","answer":"利用率の問題については、先ほど申し上げた数字は、区内の各事業者が大体目標としている平均的な数字として申し上げましたので、いわゆる損益分岐点とイコールではありません。それから避難訓練でありますけど、これにつきましては区がどうこうということもありますが、例えば消防計画に基づいて、当然月に１回とか、そういう計画に基づいて実施をされているということで。","voiceIndex":67,"id":"exchange-028"},{"speaker":"飯沼副委員長","kind":"質問・要望","question":"グループホームのところをお伺いしたいと思います。そういうところでの夜勤体制、ケアホームだと区立だから夜もいるのかなと、そこがちょっとあいまいなので教えていただきたい。この両施設ともあまり入れかえがない状況ですよね。こういったところで、お仕事に行っていらっしゃる方が多いと思うんですが、就労状況がどの程度なのか。お仕事に行かれない方もいらっしゃるのか、その辺も含めて教えてください。","respondent":"高橋障害者福祉課長","answer":"両つばさの家の状況ですが、ケア状態の人は両方とも入所しておりません。ケアホームということになりますと、区分の２条ですので、両施設とも入所している人が一般就労、もしくは通所施設に通所しているという状況ですので、その辺については安心していただければと思います。","voiceIndex":70,"id":"exchange-029"}]},{"id":"topic-03","title":"では２の行政視察についてでありますけれども、先にその他を行います。 まず１番目の所管質問","agenda":"では２の行政視察についてでありますけれども、先にその他を行います。 まず１番目の所管質問","exchanges":[{"speaker":"安藤委員","kind":"質問","question":"質問でもありましたけれども、基盤整備の点で整備の目標値を示すべきではないかということでも質問がありましたが、そこに関してのお答えがなかったようですので、そちらの考え方をお伺いしたいのと、あと、障害をお持ちの方も、本人の希望があれば生まれ育った区内の中で生活していけるというところが基本にあるべきだと思うんですけれども、そちらのお考えがおありなのかどうかということもお伺いします。","respondent":"高橋障害者福祉課長","answer":"１階が精神障害者の共同作業所、２階が知的障害者のグループホームということで、定員６名のところを来年早々に開設を予定しておりますということで、この辺につきましても状況を勘案しながら着々と進めているという状況かと思いますので、その辺については適地の取得の問題。","voiceIndex":76,"id":"exchange-030"},{"speaker":"安藤委員","kind":"質問・要望","question":"親も子も高齢化している中で、親なき子の問題、すごく不安に感じているし、要望のトップにも掲げられておりますので、これが十分な計画なのかどうかというのを検討する必要がありますし、その上で、次の計画はありますけれども、長期的に区内にこれだけの必要な基盤、これだけの数が必要で、それに向かってどうあるべきかという目標値というものを示していくのはすごく大事になってくると思うんです。","respondent":"高橋障害者福祉課長","answer":"実際、相談後待機ということではなくて、「もし空いたらお願いしたい」ということは五、六人の方が常におりますが、空いた段階でお声をかけると「いや、今の段階では断る」というところが多いので、必ずしも緊急的に設置するという状況ではないと私どもは考えます。","voiceIndex":79,"id":"exchange-031"},{"speaker":"安藤委員","kind":"質問・要望","question":"そういった点で、一般質問の中でもそういった交通費に当たって、区の指導、支援強化を求めますということで質問したと思うんですね。そこら辺でもう少し踏み込んで、必要な調査、あるいは指導など、あるいは手当、必要であれば区独自の支援策みたいなものは必要なんじゃないかと思うんですけれどもいかがでしょうか。ぜひお願いしたいんですけれども。","respondent":"木下健康福祉事業部長","answer":"通所の方について月３,０００円、自力で通っている方についてはプラス３,０００円の合計６,０００円、こういう体制をとって、今のご指摘の部分について言うと、品川区としては制度の建前はともかくとして。","voiceIndex":81,"id":"exchange-032"},{"speaker":"山内委員","kind":"質問","question":"教えてください。今、施設の話もございましたけれども、待機者は区内で大体何名ほど。少数というようなことをちょっと伺ったことがあるんですが、具体的な人数というのをもし把握されていたら、何名ほどいらっしゃるのかということをお伺いしたい。","respondent":"高橋障害者福祉課長","answer":"この辺につきましても状況を踏まえながら、先ほどの施設の建設についても着実に進めするという状況です。","voiceIndex":83,"id":"exchange-033"},{"speaker":"山内委員","kind":"質問","question":"大体その五、六人というのは、常に大体そのぐらいの人数で推移しているということで理解をしてよろしいんでしょうかね。そうすると、その人たちが例えば区内の施設じゃなくて、先ほどの答弁にもございましたけれども、いろいろな事情があって区外へ行きたいという方もいらっしゃると思うんですね。個人情報とかそういう問題もありますし、私はそう考えますので、それは意見とします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":85,"id":"exchange-034"},{"speaker":"飯沼副委員長","kind":"質問・要望","question":"私はぜひ、精神のところもあわせてお伺いしたいなと思っているんです。体験型のショートステイも、短期間じゃなくて例えば１カ月ぐらい、だめなときは１回家に戻ってきてという体験をして、安心をして預けていきたいということでは、体験型のステイをもっと充実させてほしいという声もあります。アンケートとかをとって、実際に「こうだったら預けたい」とか、ちゃんとニーズをつかんでいらっしゃるのか。","respondent":"高橋障害者福祉課長","answer":"したがいまして、体験型のショートステイとか、いろいろなことでシステムが整わないからグループホームに入所できないということではなくて、それぞれの家庭なり、私どももご相談に応じながら。","voiceIndex":86,"id":"exchange-035"},{"speaker":"飯沼副委員長","kind":"質問・要望","question":"送迎を使っていらっしゃる方にも３,０００円出ていますよね。９割参加しようとも出ないんですね。この前の質問のご答弁で、家賃は品川区は比較的低額ですというご答弁をいただいたんですけど、その辺の考えって、ほかと比べてなんですか。あわせて月に１１万４,５００円。私は本当に総体的に見てほしい。よそと比べて安いんですかね。私はすごく過酷な負担であるなと思っているんですがいかがでしょうか。","respondent":"高橋障害者福祉課長","answer":"それと、グループホームでかかる利用料を７万７,０００円というふうにおっしゃっていただいたんですが、在宅におきましても食費、光熱水費については必ずかかるものですので、この７万円程度の中には食費も必ず含まれていますので、それが高いというふうに言われちゃいますと。","voiceIndex":88,"id":"exchange-036"},{"speaker":"飯沼副委員長","kind":"質問・要望","question":"細かい数字を言っちゃうとなかなかあれなんですけど、本当にこの方が障害を持って、かつ、通所の授産所に、就労支援のＢ型なんですけれども通って、１カ月しっかり働いて生活をしている、この方が本当に人間らしくいろいろやりたいこともやって生活をしていきたい、自立支援法の中で質問させていただいたので、これを保障する制度になっているのかというのを総体的に、家賃一つとってどうだろうか。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":90,"id":"exchange-037"},{"speaker":"安藤委員","kind":"質問","question":"先ほど、対応はどういうふうにされているかということで説明がありましたけれども、所持金は４円です。どうするつもりかということで聞かれたんだと思いますけれども、結果的に、路上生活者の対応に当たっては、その日その人は行くところがないような状態だったわけですよね。緊急一時保護施設はいっぱいだったとしたら、どういう対応が考えられるのか、どういう手当があるのかというのをお伺いします。","respondent":"平澤生活福祉課長","answer":"したがいまして、午後の一定の時間帯までに相談者の方をお連れしなければいけない。先方でのアセスメントも必要だ。そういったこともありまして、なかなか５時間際となるとそういったところには難しいという現状はあります。","voiceIndex":100,"id":"exchange-038"},{"speaker":"安藤委員","kind":"質問","question":"何か手当はないのかということなんです。そこで、待ったなしの時間を問わない緊急急迫な方が来た場合の対応はほかには何かないんですかということで伺っているんです。例えば、一般質問でも紹介しましたけれども、敷金を支給する、あるいは民間のアパートを紹介するというようなことも考えていますということを部長も答弁されたと私は記憶しているんですが、そういうのもあるということなんでしょうかね。","respondent":"平澤生活福祉課長","answer":"大変厳しいお話で、お亡くなりになるということも想定されるというお話でございました。そういった、住宅を喪失した方に対して、昨日ご承認いただきました住宅手当といったものも考えているところですので、そういったものをご利用いただければと思っておるところです。","voiceIndex":102,"id":"exchange-039"},{"speaker":"安藤委員","kind":"質問","question":"しかも６カ月の間に生活を立て直すということも可能だとは思うんですけれども、これが今のところは長くても３年しか続かないという制度の中で、その先をどうするのか。それ以外にはないのかというこの２点ですね。この制度が終わってしまった後はどうなるのか。先ほど言った敷金の支給、あるいは民間アパートの案内とか、そういう手立てというのはないんですか。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":104,"id":"exchange-040"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?Template=document&Id=3248#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=7&TermStart=2009-01-01&TermEnd=2009-12-31"}],"sourceMeta":{"pages":0,"characters":57393,"voices":119}},{"id":"h21-20090925-8","meetingId":"h21-cm09","date":"2009年9月25日","dateIso":"2009-09-25","committee":"建設委員会","time":"午前１０時０３分～午後０時１１分","status":"正式会議録","sourceType":"formal","overview":"建設委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を38件抜き出しています。","hasFullText":true,"topics":[{"id":"topic-01","title":"委員会での質疑","agenda":"委員会での質疑","exchanges":[{"speaker":"武内委員","kind":"質問","question":"ちょっと気になったのは、両方とも主催は品川区ということですか。その上で、それぞれ人数が１５人、２４人となっていますけれども、これは事前申し込みじゃなくて、もう来た順にという……。","respondent":"工藤環境課長","answer":"私ども区が主催しているです。それで、申し込みですけれども、一応先着順ということで、期限を設けて周知しています。周知の方法に関しましては、広報に出しましたり、ホームページに掲載しています。","voiceIndex":5,"id":"exchange-001"},{"speaker":"武内委員","kind":"質問・要望","question":"今回初めてではなくて、前に何回かやっていらっしゃったかなと思うんですけれども、それに前回出た人の実績、どのぐらいの人であって、どれぐらい来たかということ、それからあと、大変申しわけないんですけれども、エコドライブの手法というのが、詳しくはここで講義しているわけですけれども、私はあまりわからないものですから、アイドリングストップぐらいしかイメージがわかないんですけれども。","respondent":"工藤環境課長","answer":"エコドライブの事業ですけれども、昨年度新たに始めたものでございまして、今回は２年目ということになります。昨年度は、２３区でも一番先に、さきがけてやったという事業です。","voiceIndex":7,"id":"exchange-002"},{"speaker":"阿部副委員長","kind":"質問","question":"２点ほど教えてください。エコドライブ、どちらも日曜、祝日に開かれて、そこに一般募集をかけて、参加してくださいという形で、もともとエコにかなり関心のある方じゃないと集まりにくいんじゃないかと思うんですけれども、これは前回なんかも、まさに一般の方がいらしているんですか。","respondent":"工藤環境課長","answer":"来年度に向けて、そういった部分でわかりやすい形の広報を工夫、検討していきたいと考えています。","voiceIndex":9,"id":"exchange-003"},{"speaker":"阿部副委員長","kind":"意見","question":"今、広報と動員と半々ぐらいと、最初は仕方がない部分はあるかもしれないですけれども、団体に声をかけていくと、すぐにルーティン化してしまったり、内容の充実がおろそかになりがちなので、そこは気をつけていただければと思います。名称についても工夫していただければと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":11,"id":"exchange-004"}]},{"id":"topic-02","title":"品川区ホームページによる道路台帳平面図の公開","agenda":"品川区ホームページによる道路台帳平面図の公開","exchanges":[{"speaker":"菊地委員","kind":"意見","question":"そうすると、例えば、建築計画を立てる際には当然行政のほうに、役所のほうに来なければならないと思うんですけれども、業者が主体なんだけれども、来庁しなくても済むようにこうやりますというのは、ほかのことも含めて、こういう業者は必ず来庁しなければならないと思うんだけれども、活用の価値として、わざわざこうやって事前に、では、道路をホームページ上で見てくださいという。","respondent":"小野土木管理課長","answer":"委員がおっしゃいますように、確かに例えば、現実に取引をするというような場合には、きちっとした確認、証明みたいな、現況がこうだということが必要になりますので、それは今お話ししましたように、年に１回ここでホームページ上にアップしているデータと。","voiceIndex":16,"id":"exchange-005"},{"speaker":"菊地委員","kind":"意見","question":"そうすると、従来だと窓口に来られて、コストというのもおかしいのかな、職員が対応したりしてやる部分だろうと思うんですけれども、その部分と、こうやってホームページに載せていく手間というか、その辺のコスト、１年ごとに見直しをしていくということであれば、その辺の問題もちょっと出てくる、あるのかなという気がするので、そこだけもう１度。","respondent":"小野土木管理課長","answer":"年に１回メンテナンスをしていくということについては７７万円ほどかかっているということで、それなりの経費はかかるわけですけれども、インターネットを通じてこういう情報、これは区内どこでもこうやって引き出していただけますので、そういう部分では、情報提供という意味で。","voiceIndex":18,"id":"exchange-006"},{"speaker":"菊地委員","kind":"意見","question":"もう１つだけ、こうやって載せますよね。これは１年後の話になってしまいますけれども、実際にこれを活用される方をホームページではチェックしている、何人の方がこれを閲覧したとか、使ったとかというところというのは、最終的にチェックされるのかどうかちょっと……。","respondent":"小野土木管理課長","answer":"システム的には、このページを見たというログをカウントすれば、どれぐらいの方がご利用にしたかというのは記録する形になります。","voiceIndex":20,"id":"exchange-007"},{"speaker":"原委員","kind":"質問","question":"これは菊地委員と同じような、ダブった質問になるかもしれません。あくまでもサービスの一環ということですよね。その辺のところをまず教えてほしい。要するに、行政のほうとしたら、多分宅建業法の３５条の重要事項の説明なんかにも必要だからというところからのスタートだと思うんですけれども、知りたいのは、品川区も参考として出していると受けとめればいいのかなという、もしそれを教えていただければ。","respondent":"小野土木管理課長","answer":"これはちょっと別の図面ということでご理解をいただきたいと思います。","voiceIndex":22,"id":"exchange-008"},{"speaker":"原委員","kind":"確認","question":"もう１回確認しますと、個人だろうと、業者だろうと、あくまでも参考として見るという感覚でのサービス提供ということでいいのかなと。さっきのご説明されたのからいくと、あくまでも来庁して、ほかのことは全部証明書という形でのものであれば、そうしなければならないというお話だったんですけれども、そこをもう１回。","respondent":"小野土木管理課長","answer":"おっしゃるとおり、参考ということで、証明の能力はございません。それは新たに窓口でとっていただく必要があります。","voiceIndex":24,"id":"exchange-009"},{"speaker":"原委員","kind":"質問・要望","question":"参考としては、例えば、最近航空写真でいろいろな裁判の問題とかも出てはいるんですけれども、便利さを出すためには、ですから、要望としては、年１回ということなんですけれども、コストの問題があるので、まあ、しようがないのかなとは思うんですけれども、なるべく現況に即した形での対応をしていただければと思います。これは要望です。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":26,"id":"exchange-010"},{"speaker":"藤原委員","kind":"質問・要望","question":"この施策ですが、まず、どこからか強い要望があって、予算をつけて反映したのか。要望でなければ、課でこういうふうにやろうと決めたのであるならば、改めてなぜやろうと決めたのか、改めて教えていただきたい。","respondent":"小野土木管理課長","answer":"したがって、そういう意味で、台帳の電子化ということが一段落して、インターネットに載せる状況が出てまいりましたので、それを広くホームページに載せて、区民の方にお役立ていただくという形で、区のほうから考えたと。","voiceIndex":27,"id":"exchange-011"},{"speaker":"藤原委員","kind":"質問・要望","question":"参考程度ということで、２００万円初期投資をして、その後毎年７０万円ぐらいかかっていくということをしてまで、こういう施策をしていくべきなのかなという思いがあるんですけれども、一般の区民に対してのサービスになるのかなというのが、もしいろいろな意味において、地域に戻って説明を受けたときに、ちゃんとした説明ができないなという気が非常にするので、これこれこうで、これだけ投資をしても。","respondent":"小野土木管理課長","answer":"それを踏まえて、窓口ではさらにいろいろな相談ができるという形になりますので、こういう基礎的な情報というのを公開するというのは、広い意味で区民の利益になると考えています。","voiceIndex":29,"id":"exchange-012"},{"speaker":"市川委員","kind":"質問","question":"１つだけお聞きしたいんですけれども、調査ために業者の方が来庁されたときに、今、窓口の職員の方というのはどういう対応をされているのかということ、それから、例えば、２３区の中では、こういうホームページによる公開というのが、今どんな状況でされているのかと、そこの状況を教えてください。","respondent":"小野土木管理課長","answer":"窓口の対応ということですけれども、まずご相談に見えまして、どこの場所かということをお伺いして、何を知りたいかということをお伺いして、それで、今システムでこういうものが電子化されておりますので、その窓口に端末がございまして、そこでそれぞれ画面を呼び出して。","voiceIndex":31,"id":"exchange-013"},{"speaker":"阿部副委員長","kind":"意見","question":"こういうものを公開するというのは基本的にいいことだと思います。職員はそれだけほかの仕事をすることもできますし、来庁した方もさまざまな、環境コストですとか、社会全体でとてもいいことだと思っています。逆に言えば、これを公開すれば、大分来庁者を減らせる、あるいは居ながらに調査ができるだろうなと思われるような資料というのはありますか。","respondent":"片田建築課長","answer":"既に道路台帳のお話がありました中でですね、用途地域の情報をあわせて開示しておりますけれども、今後の考えとして、今、建築紛争でよく２項道路とか、道路の法律上の種別、これを今検討して、作業計画を立てて判断をしていくというような国の法律改正の施行と合わせて。","voiceIndex":33,"id":"exchange-014"}]},{"id":"topic-03","title":"武蔵小山駅バス運行開始","agenda":"武蔵小山駅バス運行開始","exchanges":[{"speaker":"武内委員","kind":"質問","question":"今まで品川区内は五反田からここはとまらずに世田谷区民会館と弦巻営業所に行っていたということ、それで武蔵小山ができたから、武蔵小山を経由するようになったということですか。","respondent":"松代都市計画課長","answer":"ここの経路は現在も運行されております。武蔵小山駅の直近でいきますと、裏面の図面をご覧ください。補助２６号線と表示しています、ここの側に停留所が現在もあります。そこで乗降していただきまして、補助２６号線を相互に通行したと。","voiceIndex":39,"id":"exchange-015"}]},{"id":"topic-04","title":"併設施設のある区営住宅耐震化工事","agenda":"併設施設のある区営住宅耐震化工事","exchanges":[{"speaker":"武内委員","kind":"質問","question":"１つだけ聞きたいんですが、８つの住宅があるというのは、今回平成２４年までに３つの施設ですね。そうすると、あと残りの５住宅というのは順次やっていくという意味合いなんですか。ちょっとその辺。","respondent":"柏原住宅担当課長","answer":"おっしゃるとおりでございまして、まず、来年度、平成２２年度に１住宅予定しておりまして、私どもの区営住宅の耐震化ということで、人が住んでいるところの耐震化工事をするというのは区としましても初めてのところですので、平成２２年度はまず１住宅をやりまして。","voiceIndex":45,"id":"exchange-016"},{"speaker":"武内委員","kind":"質問","question":"教えてほしいんですけれども、併設と併設じゃないのも含めてなんですけれども、入居している方が、工事中にどこかに出てもらう場合には、こういうのは初めてだとおっしゃっていたので、今までの例がないかもしれないんですけれども、その間、その方たちが住んでいる場所というのは、基本的には自分たちで探してやるのか、それとも何か補償というか、家賃が。","respondent":"柏原住宅担当課長","answer":"工事の間の居住者の方ですけれども、基本は居ながら工事ができるところは居ながら工事をしていきたいと考えておりますけれども、場合によりましては、中の工事をしなければいけないというような場合が出てきた場合には、こちらとしましては、一たん仮の住宅ということで、例えば。","voiceIndex":47,"id":"exchange-017"},{"speaker":"武内委員","kind":"質問","question":"居ながらできるほうが多いと考えていいんでしょうか。","respondent":"柏原住宅担当課長","answer":"基本的にはそういった方向で進めたいと考えています。","voiceIndex":49,"id":"exchange-018"},{"speaker":"阿部副委員長","kind":"確認","question":"これは確認なんですけれども、保育園の利用も居ながらが基本と考えていらっしゃるんですか。","respondent":"柏原住宅担当課長","answer":"仮に居ながら工事ができない場合は、代替施設をどうするのかというのは、現在調整をしているというところで、その辺も含めて、所管課と調整しながらです。","voiceIndex":51,"id":"exchange-019"},{"speaker":"阿部副委員長","kind":"質問","question":"基本は居ながらということですが、これは平成２３年度工事予定で、居ながらで済むのか、やっぱり代替施設になるのかはいつごろ決まるものなんでしょうか。","respondent":"柏原住宅担当課長","answer":"現在設計をかなり進めているんですけれども、今年度は基本設計ということで、平成２３年の工事につきましてはやっておりますので、今年度中には大方のところは出てくるだろうと考えています。","voiceIndex":53,"id":"exchange-020"}]},{"id":"topic-05","title":"大崎駅西口駅前交通広場（Ｃ地区デッキ部）整備工事委託","agenda":"大崎駅西口駅前交通広場（Ｃ地区デッキ部）整備工事委託","exchanges":[{"speaker":"菊地委員","kind":"質問・要望","question":"ここのデッキを利用される方の構成、今は明電舎のところまでですので、明電舎ビルに勤めていらっしゃる方が圧倒的に多いかと思いますけれども、ソニーまででき上がったんだったら、ソニーのほうも事業所ビルですから、その辺の実際に利用される方の構成で、今考えておられる部分があれば、教えてちょっといただきたいんです。","respondent":"青木都市開発課長","answer":"そちらをご利用される方、さらに、補助１６３号線を通って、大崎から区役所方面に歩く方はそんなに多くないんですけれども、そういった方々、それとさらに、現在老朽化しておりますけれども、かけ替えを予定しています百反歩道橋を渡って。","voiceIndex":59,"id":"exchange-021"},{"speaker":"菊地委員","kind":"質問","question":"そうすると、設定が区道的な設定になっているのかどうかというのはよくわからないんですけれども、道路としての設定になると、例えば、街路灯もついてくるでしょうけれども、その辺のランニングコストみたいなものというのは、実際どこが、でき上がっていく負担をするものか、その辺も教えていただけますか。","respondent":"青木都市開発課長","answer":"管理につきましては、整備費も含めてですけれども、地元の開発事業者４社、明電舎、ソニー、西口中地区、西口南地区とで西口開発に関する協定を結んでいて、整備および管理に関して応分の負担をいただくということにしておりまして、管理費についても。","voiceIndex":61,"id":"exchange-022"},{"speaker":"原委員","kind":"意見","question":"協定締結の相手ですけれども、一番初めのときに独立行政法人との間でスタートしたと思うんです。それで、今のご説明だと、総務委員会のほうのＯＫが出ているので、こちらは建設委員会としての範囲で結構なので、ちょっとお話を願います。","respondent":"青木都市開発課長","answer":"平成１５年にまず基本協定というのを締結しております。","voiceIndex":63,"id":"exchange-023"},{"speaker":"原委員","kind":"質問・要望","question":"確認させていただきたかったところだったのと、もう少し、総務委員会じゃなくて、建設委員会としてもう１回いただきたいのは、独立行政法人に対するスタンスの、区との間の問題で、多分今後変わってこようかと思うんですけれども、先に、逆に少しでも、考えておいたほうがいいようなことが何かあれば、すごく雑駁な質問なんですけれども、建設委員会に対する意見ということなので、伺いたいと思います。","respondent":"青木都市開発課長、岩田防災まちづくり事業部長","answer":"そういった点で、まだ先行きいろいろな国の情勢を見るのも難しいんですけれども、都市再生機構の民営化とか、いろいろな問題もあるでしょうから、そういった点は連絡を密にとって、いつまで都市再生機構に任せられるのか。ご案内のとおり、ＵＲというのは旧住宅・都市整備公団の流れなんですが、全国でこういったハードなまちづくりを各自治体がやろうと思っても、どこの自治体もそれなりの職員の手当てができないんです。ノウハウもない。","voiceIndex":65,"id":"exchange-024"},{"speaker":"原委員","kind":"質問・要望","question":"これは最後に要望なんですけれども、私の考えとしては、品川区というのは、そういう面では、地方自治体の中でも、手前みそかもわかりませんけれども、ほかの自治体よりはかなり能力を持っている集団というか、自治体であると思っているんです。ただ、今後において結構いろいろな意味でダイナミックに変わってくる可能性があるので、それをしっかりと見きわめてやっていただきたい、最後に要望です。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":68,"id":"exchange-025"},{"speaker":"菊地委員","kind":"質問・要望","question":"住宅のほうなんですけれども、これは今説明があった、一番最後の品川宅建管理センターのところで、滞納者１件当たりの対応回数は、ほかのところに比べて非常に少ないので、対応するようにという指示をしているという話なんですけれども、この辺は具体的に、区からの指導としてそれぞれに、これぐらいの回数はきちんとやってくださいみたいな。","respondent":"諸石交通安全担当課長、柏原住宅担当課長","answer":"そういうところをこれから検討していきたいと考えておりますので、内容につきましてはこれから検討しますので、研究もしますので、今ここでこういう形だということは申し上げられませんけれども、弾力的な運用というのは。滞納者に対する指導の部分ですけれども、こちらは特に区のほうから何回行きなさいとかといった指示はないんですけれども、実際のところは、先ほども申しましたように、区の中に住宅が点在しているというところがございまして。","voiceIndex":75,"id":"exchange-026"},{"speaker":"菊地委員","kind":"質問","question":"今、短時間であれば、無料でも、１５０円よりもっと少なくてもいいんじゃないかと、そういう部分も当然あるんだと思いますけれども、ただ同時に利用料金制度となれば、そういうふうに低くなる方もいらっしゃるということで、もし、制度として利用料金制度をつくっていくと、逆に、１日利用で１５０円をはるかに超えるとなっていく可能性もあるんだと思うんですけれども、そこだけ、対応をお聞きしたいのと。","respondent":"諸石交通安全担当課長、柏原住宅担当課長","answer":"利用料金制度を導入した場合に、例えば、今１５０円でやっているものが、もっと高い料金設定になるのではないかという委員からのご質問についてお答えしますが、駐輪場の利用料金につきましては、品川区の条例に規定されております。それで、多分委託料云々のお話だと思うんですけれども、委託料につきましては、毎年予算編成時期に一定の額ということで、お互いに話し合いをしながら、この業務ではこのぐらいの金額で適当かどうかというところで。","voiceIndex":78,"id":"exchange-027"},{"speaker":"藤原委員","kind":"確認","question":"住宅だけお伺いしますけれども、滞納者って出てくるじゃないですか。ですから、改めて確認ですが、区民住宅に入るからには、家賃を払うということは当たり前のことなのか、違うのか、改めて質問したいと思います。","respondent":"柏原住宅担当課長","answer":"そもそも区民住宅は中堅の所得のファミリー層の方等々に入っていただくというのが、区民住宅を設置する目的の１つでもありますので、使用料、そういった方が入居する際には、きちんと審査をしているんですけれども、その分。","voiceIndex":81,"id":"exchange-028"},{"speaker":"藤原委員","kind":"質問","question":"そうすると、当たり前のことと言うならば、家賃収納率は１００％になるのが当たり前ですよね。だけれども、この品川宅建管理センターは、みずから決めた収納率がなぜ９８％、１００％になるのが当たり前ですよね。みずから９８％でいいやと、そんなおかしいことはないんじゃないですか。","respondent":"柏原住宅担当課長、岩田防災まちづくり事業部長","answer":"こちらは区民住宅も区営住宅も管理しているところもございまして、もちろん１００％と設定するということが望ましいところですけれども、いろいろな方がいらっしゃいまして、例えば、単純に納付。ちょっと考えなければいけないのは、区営住宅のように、いわゆる福祉住宅として低所得者向けにやっている住宅と、区民住宅のように、福祉ではなくて、別の目的でやっている行政サービスとは、当然対応は変えなければいけません。","voiceIndex":83,"id":"exchange-029"},{"speaker":"武内委員","kind":"質問","question":"これはおそらく三井不動産からの報告じゃなくてファミーユの自治会から出したんじゃないかと思うんですけれども、こういう形で、例えば、区がこちらに来て、見たりとか、管理上を見たり、また別の角度で調査したり、利用者の方に聞いたりするということはあるかどうかなんですけれども、どのぐらいの頻度でどんな感じでやっていらっしゃるのかなと、これは単なる書類だけで評価しているんじゃなくて。","respondent":"諸石交通安全担当課長、柏原住宅担当課長","answer":"報告でも申し上げましたが、ＮＣＤの担当者が毎日区の自転車係のほうへ連絡で顔を出しますので、その際にも区の担当者といろいろと仕事上の連絡をさせていただいているです。それはそのまま上がってまいりますので、その内容を見たり、それからあと、区営住宅等につきましても、なるべく自治会の方々とお話ができるように、先ほどもご報告しましたように、いろいろな案件、例えば、耐震化の話であるとか。","voiceIndex":86,"id":"exchange-030"},{"speaker":"高橋委員","kind":"質問","question":"区のほうで、どこまでそういうふうにしているか。何でそんなことを言うかというと、注意したことによって、管理員の方が区民の方に暴力を振るわれてけがをされたなんていうこともお聞きしているので、その辺の線引きはどういうふうにしているのか、その２つを教えてください。","respondent":"諸石交通安全担当課長","answer":"そうしたものについては、管理員の方が区に連絡をしていただいて、これはＮＣＤを通じてということにもなりますけれども、連絡をしていただいて、区と連携をとった上でこれを速やかに撤去するということでやらせていただいているものです。","voiceIndex":89,"id":"exchange-031"},{"speaker":"阿部副委員長","kind":"質問","question":"その上で２点ほどお伺いしたいんですけれども、まず、駐輪場の先ほども出ていました料金形態の導入というのは、改善に必要な事項と、検討を続けていくということなんですが、検討するのは指定管理者がこういう料金形態に変えるというように、このシートでは読めてしまう、検討するということなんですけれども、実際にはむしろ区の政策であって、区が決めるなり。","respondent":"諸石交通安全担当課長、柏原住宅担当課長","answer":"平成２３年度に入りますと、もう新しい指定管理者の選定の作業に入らなければいけませんので、それまでに区は料金の体系について、いろいろ研究・検討していきたいと考えています。ただ、平成２０年度から人員が大分変わりまして、今年度にかけて安定化してきているところではあるんですけれども、大きなミスというのは大分なくなってきておりますが、定期的な打ち合わせであるとか。","voiceIndex":93,"id":"exchange-032"},{"speaker":"阿部副委員長","kind":"質問","question":"自転車のほうは短時間無料化など、放置自転車の減少に効果があるというような社会実験もかなり積み重なっているようですので、また別の機会があれば、お聞きしたいと思います。品川宅建管理センターのほうは、もう頑張ってもらうしかないんでしょうね。ぜひよろしくお願いします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":96,"id":"exchange-033"}]},{"id":"topic-06","title":"その他を議題とします。まず、（１）の所管質問","agenda":"その他を議題とします。まず、（１）の所管質問","exchanges":[{"speaker":"菊地委員","kind":"質問","question":"ですから、区が分析をして出されていたこれらの３つの問題、これまでももちろんいろいろな形で手を打ってこられたわけですけれども、この問題点として挙げられる部分をどういうふうにクリアしていくのかということが、早急に必要なのではないかと思っています。ですから、その辺についてもう少し詳しい答弁をもらえればと思っています。","respondent":"吉川防災整備担当課長","answer":"高齢者等の建て替えや住み替えの啓発につきましては、今検討中の住情報センターの検討とも連携して、取り組みを考えていきたいと考えています。","voiceIndex":99,"id":"exchange-034"},{"speaker":"菊地委員","kind":"質問","question":"ただ、意識の啓発といっても、要は、９０％という大きな目標があって、そこにたどり着くためにどうするのというのが、本当に命を守る課題ですから、９０％の目標に対してどうするのかというのは、こういう形で努力をしていますというのはわかるんですけれども、では、意識啓発だけとってみても、どういう手だて、今までの手だてでいいのかというのがあると思うんです。そこをもう１度……。","respondent":"吉川防災整備担当課長","answer":"それと、耐震診断は５年間実施しておりまして、３００件近い実績も上げているところです。","voiceIndex":101,"id":"exchange-035"},{"speaker":"菊地委員","kind":"意見","question":"ただ、そもそも９０％という目標に対してどのように、その目標そのものをどうとらえるかという前提があるんだとは思いますけれども、最後に、９０％目標をどのようにとらえているか、そこをちょっとお聞かせ願えますか。","respondent":"岩田防災まちづくり事業部長","answer":"幾ら上げれば、どれだけ上がるかというデータが全くありません。だから、計画のしようがありません。それよりもまず、今回、去年やった住民の方々の認識度の低さ、向こう数十年の間に東京直下の地震があるということは、８割以上の方が認知されている。","voiceIndex":103,"id":"exchange-036"},{"speaker":"菊地委員","kind":"質問・要望","question":"わかります。ですから、その辺の目標設定、こういう施策、こういう手だてを打てば、これくらいは上がっていくんじゃないか、意識、教育のことも含めて、上がっていくんじゃないかと、そういう目標設定をしていっていただきたいなと思いました。最後に意見です。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":105,"id":"exchange-037"}]},{"id":"topic-07","title":"行政視察","agenda":"行政視察","exchanges":[{"speaker":"菊地委員","kind":"質問・要望","question":"最後の環境モデル都市、今、新しい首相が２５％削減するとどおんと打ち出したんですけれども、こういう構想に沿って、堺市にしても、品川区にしても、これが切り替えていかなきゃならない部分につながるものなんですか。そこだけ教えていただきたい。","respondent":"久保田都市環境事業部長","answer":"品川区の今の考え方というのは、今、まさしく策定検討中ですので、もちろん大きな世界観、国の方針、これは当然踏まえながらの品川区の、例えば、計画づくりになるだろう、それは基本だろうとは考えています。","voiceIndex":118,"id":"exchange-038"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?Template=document&Id=3958#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=8&TermStart=2009-01-01&TermEnd=2009-12-31"}],"sourceMeta":{"pages":0,"characters":38863,"voices":120}},{"id":"h21-20090925-9","meetingId":"h21-cm09","date":"2009年9月25日","dateIso":"2009-09-25","committee":"文教委員会","time":"午前１０時０３分～午後３時０１分","status":"正式会議録","sourceType":"formal","overview":"文教委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を71件抜き出しています。","hasFullText":true,"topics":[{"id":"topic-01","title":"はじめに(1)区営住宅に併設する図書館の耐震化工事","agenda":"はじめに(1)区営住宅に併設する図書館の耐震化工事","exchanges":[{"speaker":"中塚委員","kind":"質問","question":"工事期間とかは未定と書いてあるんですけれども、要するに何も決まっていないという感じで、つかみようがない報告だったんですけれども、概要でいいので、平成２３年度中に工事を始めるということなのか、それとも終わりたいということなのか、工事期間中、原則として休館という話ですけれども、利用者にとってはどれぐらい休館になるのか、半年なのか、１年なのか、それ以上なのか、全然わからなかったので。","respondent":"小川品川図書館長","answer":"工期の見込みですが、予定では平成２２年度に実施設計を行う予定です。ですので、平成２２年度の今ごろ、ちょうど秋ごろには青写真が見えてくるかと思います。","voiceIndex":8,"id":"exchange-001"},{"speaker":"中塚委員","kind":"質問","question":"二葉図書館の休館はおそらく半年以上ということでしょうから、利用者にとっては大事な話だと思うので、しっかりお知らせのほうはよろしくお願いします。新耐震の基準で建てられたのか、それ以前なのか、そこだけちょっと教えていただけますか。改めてどこの会社に委託をしているのか、それといわゆる休館中というのは窓口の委託契約というのはどういう扱いになるのか、ちょっと教えていただけますか。","respondent":"小川品川図書館長","answer":"１点目のゆたか図書館の建設年度ですが、設立は昭和５０年１０月になります。それから二葉図書館の現在の窓口業務委託をしている業者ですが、日本コンベンションサービス株式会社という会社です。","voiceIndex":10,"id":"exchange-002"},{"speaker":"西本委員","kind":"質問","question":"所管が違うかもしれません。築何年になるんですか。地域センター、まだどういう形になるかわかりませんけれども、あそこの一帯で大々的な改築等々がある中で、ここは耐震にしたということで、もし老朽化が激しいということであるならば、建替えということも視野に入れてもいいんじゃないかなと思ったんですが、その原因は何かおわかりでしょうか。改築という方法も１つあると思うんですけれども。","respondent":"小川品川図書館長","answer":"建設年度は昭和４４年度ですので、約４０年近く経っているかと思います。確かにいろいろと老朽等は進んでいるところなんですけれども、住宅等が入っていることと、あわせまして関係課、技術系の部門と相談した結果、耐震補強をするという選択になったものです。","voiceIndex":12,"id":"exchange-003"},{"speaker":"西本委員","kind":"質問","question":"戸数の多さもありますので、早々に改築という形にならないのかもしれないんですが、あそこは一貫校ができる上で、かなりの開発が進むというか、整理がされると思うんですね。その中に私は入れてもいいんじゃないかと思った部分もあって、それと耐震化工事ということは、これはまだ具体的にどういうものでやっていくかはわからないですけれども、補強という形なんですかね。それはどういう形になるんですか。","respondent":"小川品川図書館長","answer":"図書館の部分だけで言わせていただきますと、例えば柱が少し太くなるだとか、あとブレースといいまして、補強するための鉄骨を入れるですとか、そういったことを行いますので、当然図書館全体ではレイアウトの変更が必要になろうかと思います。","voiceIndex":14,"id":"exchange-004"},{"speaker":"西本委員","kind":"質問・要望","question":"図書館というのは今後、非常にいろいろな意味で拡大していく、整備を進めていただきたいという気持ちもあるんですが、そこが使いづらくなったりとか、狭くなってしまったりということが起きるならば、私は図書館だけでも、例えば一貫校の中に入れちゃうとか、ありえないかもしれないけれども、そういう二葉図書館をもうちょっと発展させていただきたいという気持ちがあるんですけれども、そのためには。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":16,"id":"exchange-005"},{"speaker":"浅野委員","kind":"質問","question":"図書館の耐震化工事ということで、まだ確定していない部分が多いと思いますけれども、休館ということになりますと、二葉図書館の蔵書をどうされるのかというのが気になっていて、かなりの量だと思うので、例えばほかの図書館に分散させるのか、それともほとんどが多分、ほかの図書館にもあるから、例えばどこかの倉庫にしまっておくのか、またユニークなものがあれば。","respondent":"小川品川図書館長","answer":"ちなみに２年ほど前ですが、南大井図書館を耐震改修工事をさせていただいたときには、たまたま日野学園の改築の関係がありましたものですから、日野中の体育館をお借りしたような経緯がありますので。","voiceIndex":17,"id":"exchange-006"},{"speaker":"浅野委員","kind":"質問・要望","question":"保管だけですか。そういうところで貸し出しできないということで、保管だけということになりますと、今まで利用されていた方の利便性とか、そういうことに関しては近くの図書館に行くとか、そういうことになるかと思いますけれども、一旦は不利益というんでしょうかね、不都合をかけるような形になると思いますので、そこら辺はしっかりと住民の方に理解を得られるような形をつくっていただきたいと思います。","respondent":"小川品川図書館長","answer":"インターネットの予約をしても、必ずどちらかの図書館に受け取りに来ていただくという、今はそういったことになっておりますが、こちらにつきましても、一度は来ていただく。それから返しに来ていただくという流れは、できますれば今後も続けていきたいと考えております。","voiceIndex":19,"id":"exchange-007"},{"speaker":"井上委員","kind":"質問","question":"先ほどの小中一貫校の開設に向けての地域の変わりもあると思うんですが、また道路が開通する、たこ公園のところが開通するということで、大分そこのまちの状況が変わるのではないかというところで、何か工事のそういうことも含めて進めていかなければいけない状況があると思うんですが、図書館とか、この次の報告の保育園とか、そういう全体の、ここのところでの議論はちょっと難しいかもしれないんですが。","respondent":"小川品川図書館長","answer":"おそらく平成２３年度くらいには公園整理が整うのではないかとは言われておりますが、今のところはまだそちらのほうもわかっていないので、今後とも情報収集に努めて、できればきちっと連携をしていきたいと考えております。","voiceIndex":21,"id":"exchange-008"},{"speaker":"林副委員長","kind":"質問","question":"全体的な話をすると、住宅が主な建物ですよね。出入り口はしまっていて、駐車場は使えなくなっているけれども、建物の中は全部使えているわけですよ。そうすると、ここの二葉一丁目住宅の耐震工事をやったときに、図書館とか保育園を休まなければいけない理由というのがあるんですか。","respondent":"小川品川図書館長、市川教育次長","answer":"図書館に関しましては、基本的には本を読むところということで、騒音に関してはかなり激しい騒音が出るということは伺っております。したがって中の業務は継続できるということですが、一方でこの間、小学校、中学校の補強工事を夏休みを中心に行ってきていますけれども、強度を補強するために、主として壁に強度を持たせるために、今までの壁をはがして。","voiceIndex":23,"id":"exchange-009"},{"speaker":"林副委員長","kind":"質問","question":"とすると、住宅も明け渡してもらうんですか、一時。さあ、工事をやります、実施設計が平成２２年度に始まります、ああそうですか、じゃ、よろしくお願いしますよというんじゃなくて、私たちは区民サービスをしているのを閉鎖するというのは断じてならないというふうに教育長は言わないのでしょうか。","respondent":"市川教育次長","answer":"ただ今のご質問の趣旨は、私どももこの間、小・中学校の耐震補強工事を実施してくる中で、工事の目的、これは耐震性能を強度なものにする、一定の数字をクリアするように強度を持たせなくてはいけない。","voiceIndex":26,"id":"exchange-010"},{"speaker":"林副委員長","kind":"質問","question":"２６号線の工事がずっと続いていて、今はちょっと中断しているんだけれども、あの近辺で工事から工事が中断に至るまでの間、空き巣が２件入っているんですよ、あの近隣で。ですから、これから区営住宅の耐震化をする所管と教育委員会と、周りの人たちのこともよく考えるように伝えて、事故なく、そういう区民に害が及ぶようなことも極力ないように進めていただくようにお願いをしておきます。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":28,"id":"exchange-011"},{"speaker":"中塚委員","kind":"質問・要望","question":"この清水台保育園と二葉保育園、それぞれ平成２３年度に工事をやるということ、ちょっと前に本年度設計をすると、スケジュールが決まったというお話があったんですけれども、さっきの二葉図書館とこれと、要するに実施設計、基本設計、工事の、そもそもスケジュールの流れがよく見えなかったのでご説明いただきたいのと、あと二葉一丁目住宅と二葉保育園と二葉図書館と一体的に進めるのか。","respondent":"吉岡保育課長","answer":"スケジュールですけれども、６月にお話ししましたように、今年度から設計に着手しますということが６月の時点では決まっていたんですが、今、委員のお話があったように、基本設計、実施設計、それから工事という流れになりまして。","voiceIndex":34,"id":"exchange-012"},{"speaker":"中塚委員","kind":"質問・要望","question":"基本設計、実施設計、工事、そのスケジュールがまた固まり次第、適宜報告をしていただきたいなと思うのと、あと清水台保育園は仮設園舎に設置する予定と資料に書いてあるとおり、仮設をつくるわけですよね。それはいつからなのか、何年間なのか、教えていただけますか。","respondent":"吉岡保育課長","answer":"それから保育課としては、保育園をそこで継続することができれば、利用者の方にとっても一番利便性を確保できますので、そういうふうに思っているんですけれども、先ほど申し上げたように、いろいろな工法等の制約もあろうかと思いますので。","voiceIndex":36,"id":"exchange-013"},{"speaker":"中塚委員","kind":"質問・要望","question":"まだ別の園舎に行くか行かないかも含めて今、検討しているというご説明なんでしょうか。その前後がわからないのでご説明いただきたい。","respondent":"吉岡保育課長、古川子ども未来事業部長","answer":"なぜこの時期かですけれども、当然お住まいの方もいらっしゃいますし、あと園の利用者の方も、あるいは図書館の利用者の方もいらっしゃいますので、なるべく早くお知らせをするということと、今、在園されているお子さんについては。数カ月間なり、若干もう少しかかるかもしれませんが、そういうことが当然予測がされておりますので、事前にそれぞれ関係者、住宅におきましてはお住まいの方、併設する施設においては施設の利用者等々に。","voiceIndex":38,"id":"exchange-014"},{"speaker":"中塚委員","kind":"質問","question":"保育園の耐震化状況で、先ほどの説明ですと、公立の認可保育園はあと都営住宅と併設している八ツ山保育園のみで、あとは終わったという説明でよろしかったでしょうか。私立の認可保育園のほうはどういう状況なのか。品川区の耐震改修促進計画ですか。いわゆる公の保育園の耐震改修を進めていくという計画が出ていると思うんですけれども、私立のほうの現状はどうなっているのか。","respondent":"吉岡保育課長","answer":"私立園につきましては、それぞれ一定の工事費等が必要になるということで、それぞれ検討されて、努力はされているところだと聞いておりますけれども、今、手元に各園ごとの資料を持っておりませんので、それ以上の説明は控えします。","voiceIndex":41,"id":"exchange-015"},{"speaker":"中塚委員","kind":"質問・要望","question":"公立、私立問わず、認可保育園の耐震化を１日も早く進めていただきたい、要望して終わります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":43,"id":"exchange-016"},{"speaker":"西本委員","kind":"質問","question":"未確定なところが多々あると思うんですが、この後、報告があると思いますけれども、平塚小学校跡の土地、清水台保育園というのは、ここの敷地内に仮園舎を、ということなんですか。","respondent":"吉岡保育課長","answer":"後ほど、平塚幼保のご報告の中で図面が出てきますので、その際にはその図面をごらんいただきたいんですけれども、とりあえず新しくつくっている施設の敷地の中に仮設の園舎を置かせていただきたいということで、今お願いをしております。","voiceIndex":44,"id":"exchange-017"},{"speaker":"西本委員","kind":"質問","question":"後で報告があるというのを重々知りながら、こっちも関係していますので、ここで質問しますけれども、平成２３年度に工事が始まるので、清水台保育園が仮園舎になる場合は、平成２２年度、平成２３年度、移動しなきゃいけないわけですよね、仮設の園舎に。ここの中で安全面とか、どういう格好にしていくのかというのが見えないんですけれども。","respondent":"吉岡保育課長","answer":"工事は平成２３年度中に実施をするということは今、ご報告させていただいたとおりなんですけれども、それが平成２３年度の４月から年度末の翌年３月までぎっしり詰めて１２カ月かかるのか、あるいは半年ちょっと、あるいは８カ月で終わるのか。","voiceIndex":46,"id":"exchange-018"},{"speaker":"西本委員","kind":"質問・要望","question":"交流をもたせるというのはすごくいいことだと思うので、そこは保育の内容として、幼稚園と保育園とぜひいろいろ交流をやっていただいて、工事の期間ですけれども、やっていただきたいなという部分もあるんですが、その反面、そういう危惧をする保護者の方もいらっしゃるということもあると思いますので、それをきっちり初めからそういうことではないですよということで入れていただかないと。","respondent":"吉岡保育課長","answer":"清水台保育園につきましては、何で動くかというと、耐震工事のために動くわけですから、それが終わって安全、耐震性が担保されれば、またもとへ戻るという予定でおります。","voiceIndex":48,"id":"exchange-019"}]},{"id":"topic-02","title":"御殿山幼稚園の移転","agenda":"御殿山幼稚園の移転","exchanges":[{"speaker":"中塚委員","kind":"質問・要望","question":"ちょっとこの御殿山幼稚園の移転計画というんですかね。よくわからなかった部分があるのでご説明いただきたいんですけれども、初めにこの北品川五丁目第１地区再開発を進めるべきではないと私は思っています。移転計画がどういう流れなのかよくわからなかったのでお聞きしたいんですけれども、まず御殿山幼稚園がこの品川地区小中一貫校に来るのは平成２３年４月ですけれども、戻ってくるというんですかね。","respondent":"吉岡保育課長","answer":"それから御殿山幼稚園と品川地区小中一貫校の距離ですけれども、直線距離にして７００ｍから８００ｍかなと思いますが、通っていらっしゃる地区が御殿山小学校の西であれば、若干遠くなられる方も出てくるかなと思うんですけれども、その辺は事前にご説明する予定でおります。","voiceIndex":56,"id":"exchange-020"},{"speaker":"中塚委員","kind":"質問・要望","question":"御殿山幼稚園が戻るのは平成２６年度ということですけれども、それは御殿山小学校の開設時なのか、そことの関係がよくわからなかったのでそこをご説明いただきたいのと、あと品川地区小中一貫校の開校に合わせて御殿山幼稚園が移転をするということでよろしいんですよね。そうなると、品川地区の小中一貫校の幼保一体施設というんですか。","respondent":"吉岡保育課長、田村庶務課長、古川子ども未来事業部長","answer":"図面のところにも書いてありますように、幼稚園の４歳児、５歳児だけではなくて、０歳児からの部屋も予定していますので、この場所において。ですから、御殿山小学校の改築については、単独で今のところ考えております。そのときの私ども、ご説明させていただいた中では、基本的には、品川区に幼稚園が９園ありますけれども、９園を増やすという考えはないわけでありますので。","voiceIndex":58,"id":"exchange-021"},{"speaker":"中塚委員","kind":"質問・要望","question":"御殿山幼稚園が品川地区小中一貫校に来て、戻るまでの３年の間は、ここの幼保一体施設というんですか、４歳児、５歳児はいわゆる御殿山幼稚園、０歳、１歳、２歳、３歳が新しくできる認可保育園、その２つが同居している、そういう考えでよろしかったんでしょうか。となると、その３年の間の品川地区小中一貫校の幼保一体施設というのは、３歳までの認可保育園ということになるんでしょうか。","respondent":"吉岡保育課長","answer":"それから戻った後の保育園はというお話でございましたけれども、戻った後の保育園につきましては、先ほど部長がご説明しましたように、幼稚園の新設ということは考えてございませんので、保育園として乳幼児教育の部分も充実させた形のものということで。","voiceIndex":62,"id":"exchange-022"},{"speaker":"中塚委員","kind":"質問","question":"品川地区小中一貫校の幼保一体化施設で、０歳から５歳までの年齢ごとの定員は何人になるのかというのを伺いたいんですけれども、もちろん御殿山幼稚園が３年間来るわけですから、今通っている方、また御殿山幼稚園の定員は満たすというふうに考えているのか、それを満たしながらも将来的な定員なのかよくわからないんですけれども。","respondent":"吉岡保育課長","answer":"定員につきましては、施設の開設時までに結論を出していく形になろうかと思いますけれども、幼稚園部門について言えば、現行の御殿山幼稚園がありますので、その御殿山幼稚園の枠というのは当然確保されているということでございまして。","voiceIndex":64,"id":"exchange-023"},{"speaker":"中塚委員","kind":"質問","question":"４歳、５歳の御殿山幼稚園の今の人数と定員の数がわからなかったんですけれども、たしか２クラス分じゃかなかったかなと。同じ規模の４歳、５歳の定員になるというのは明らかなんでしょうか。結果として３年後できる幼保一体化施設の定員というのも今後決めていくということなのか。","respondent":"吉岡保育課長","answer":"御殿山幼稚園につきましては、現行は定員が４歳児が３０名、５歳児が３２名の６２名でございまして、今後、定員につきましても、幼稚園については１クラス３５人というのが上限になってありますので、その範囲内で、これからまだちょっと時間がありますので。","voiceIndex":66,"id":"exchange-024"},{"speaker":"西本委員","kind":"質問・要望","question":"重複するかもしれませんが、整理させていただきたいと思うんですが、御殿山幼稚園というのは、いずれは０歳、１歳、２歳、３歳を含めた幼保一体の施設になるわけですね。その形をもって、平成２５年、平成２６年に再開発に戻っていきますよということですか。そこがよくわからない。","respondent":"吉岡保育課長","answer":"それから戻るときなんですけれども、これはまだいろいろ再開発組合と交渉等を今やっている過程ですので、どういう形で戻れるのか、それを見極めながら最終的な判断はする形になろうかなと考えています。","voiceIndex":68,"id":"exchange-025"},{"speaker":"西本委員","kind":"質問","question":"ということは、先ほどの説明で平成１９年のときとそこが変わっているということ、まだ不確定だということでいいんですか。そのときは幼保一体化の中でやっていきますよという形だったので、その再開発の中でも幼保一体化施設として入ってきますよという説明だったと思うんですよ、平成１９年度。だけど今は、どういう状況になるのか、ならないのか不確定ですよという段階なのかということです。","respondent":"古川子ども未来事業部長","answer":"それは御殿山幼稚園がベースになるということですから、そこに新設の保育園が当然また加わる。したがって、新設の保育園はいずれにしても２カ所に将来はできるということです。","voiceIndex":70,"id":"exchange-026"},{"speaker":"西本委員","kind":"確認","question":"幼稚園は既存のものがベースになるので、幼稚園という形じゃなくて、保育園が認可保育園なのかどうかよくわからないけれども、そういう新たな保育園になるのかもしれませんが、そういう形で持っていくよということですね。それの確認と、それから、そうなると、かなりそこを説明していかないと、０歳、１歳、２歳、３歳ですよね。既に平成２３年から平成２５年度の間に入るわけですよね。","respondent":"吉岡保育課長","answer":"年明けぐらいに保育園の募集をかけるときに、新しい新設された御殿山幼稚園と一体の幼保一体施設の保育園は、３年後には御殿山幼稚園は戻りますというご説明は、当然あわせてするということになると思います。","voiceIndex":72,"id":"exchange-027"},{"speaker":"西本委員","kind":"質問・要望","question":"それでもやっぱり保育園は保育園、幼稚園は幼稚園という感覚は当然あるわけで、それによって選択をしていく可能性がありますから、そこをきちんと、完璧に誘導してしまえば、どの施設、名前だけ違っていて、幼保一体化施設だ、認定こども園だといっても、名前だけ違っていて中身は一緒ですよというならどこでも構わないんですけれども、多分まだまだそう整理はできない部分があると思うので。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":74,"id":"exchange-028"},{"speaker":"井上委員","kind":"意見","question":"戻ったときに、開発の関係でわからないけれども、幼稚園型の幼保一体型になったとすると、０歳から３歳までも一緒に移転をするのかどうかということが、幼稚園の規模しかない地域貢献施設に戻るということであれば、０歳から３歳はここに残るんでしょうけれども、そこのところがまずどうなのかというのが１点。","respondent":"吉岡保育課長","answer":"品川地区に御殿山幼稚園が一旦来て３年間で戻った後は、この時点では幼稚園ではありませんので、保育園ということで、乳幼児教育の充実はほかの園と同様実施していきますけれども、残るのは保育園です。","voiceIndex":75,"id":"exchange-029"},{"speaker":"井上委員","kind":"質問・要望","question":"そうすると、地域でずっとこのこと、私はこの地元におりますので、この中で話し合われていたときに、ここの名称があると思うんですけれども、地域の方への今の決定の、行政内でそういう決定した時期と、小中一貫校の準備会が今行われている中で、幼保一体の施設の説明も並行して行われているはずですので、そのときに名称も含めて、御殿山幼稚園が来たのであれば、御殿山幼稚園という３年間の名称。","respondent":"田村庶務課長","answer":"品川地区の小中一貫校の準備会、地域の町会だとかＰＴＡなどを含めた中では、幼保の施設についても区として必要なので、飛び地のほうに設置をしますという形で説明はしています。","voiceIndex":77,"id":"exchange-030"},{"speaker":"井上委員","kind":"質問","question":"今、地域への説明ということで、ここにそういう幼稚園施設、保育園施設ができるということは期待を持って地域の方は、足りなくなるということも含めて期待をしているところであるので、その辺については、今ここでこういう話を聞いた中でもなかなかわかりにくい、戻るときにどういう状況で戻れるかということもはっきりしない中ですけれども。","respondent":"吉岡保育課長","answer":"本日、委員会への報告が終わりますので、早急にしていきたいと考えております。","voiceIndex":79,"id":"exchange-031"},{"speaker":"井上委員","kind":"質問・要望","question":"早急って、大体いつごろというところをはっきりと、いついつですというのはないにしても、１０月初旬なのか、中旬なのか、そういうことぐらいはお伝えいただきたいと思います。","respondent":"吉岡保育課長","answer":"幼稚園の今年度の入園の説明会が１０月２７日に予定されておりますので、地域についてはそれまでにはお話しします。","voiceIndex":81,"id":"exchange-032"},{"speaker":"浅野委員","kind":"質問","question":"１点だけなんですけれども、飛び地のほうなんですけれども、将来的には０歳から５歳までが入る施設になるわけですけれども、例えば地震ですとか災害が起きたときに、隣の学校に避難することが想定されるのか、どういう形でかちょっとお伺いします。","respondent":"吉岡保育課長","answer":"保育園児、幼稚園児の避難場所ということでしょうか。","voiceIndex":83,"id":"exchange-033"},{"speaker":"浅野委員","kind":"質問・要望","question":"要望です。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":87,"id":"exchange-034"},{"speaker":"林副委員長","kind":"確認","question":"確認をしたいんだけれども、今、保育課長のほうから答弁があって、教育委員会からはときどき庶務課長が答弁する。いわゆる品川地区の一貫校にできる保育園、それから御殿山幼稚園が３カ年移設するというか、借りる。この品川地区の一体型の小中一貫校にできるいわゆる就学前の子どもたちの施設というのは、幼保一体型じゃないんですか。どっちが答えなんでしょうか。","respondent":"古川子ども未来事業部長","answer":"具体的にどこがどう入るかにということについては、今後さまざまな地域の事情を踏まえた上で検討させてくださいと、こういう答弁をした記憶があります。したがいまして、今、副委員長からのご質問のとおり、幼保一体施設ということも当然考えの中にはございました。","voiceIndex":88,"id":"exchange-035"},{"speaker":"林副委員長","kind":"質問","question":"いろいろなこういう段階を踏んで変わってきたという説明は受けております。ただ幼保という呼び方、品川区が、第一義的にはプリスクールで始めたという部分があって、教育委員会に聞きます、一体型の一貫校をつくるときには、幼保一元化された就学前の施設をつくるというのは、もう放棄したんですか。これは教育委員会に聞きます。","respondent":"市川教育次長","answer":"その後、荏原西については、私どもがちょっと見込めないアクシデントと申しましょうか、事情がございまして断念いたしましたけれども、品川地区、それから、これから設計に取りかかってまいりますけれども、荏原東については。","voiceIndex":90,"id":"exchange-036"},{"speaker":"林副委員長","kind":"確認","question":"確認しておきますけれども、一体型小中一貫校と就学前の子どもたちの施設、幼稚園とか保育園とかいうとまたややこしくなってくるから、就学前の子どもたちの施設については、教育委員会はできる範囲、それから子ども未来事業部については、教育委員会の指図は受けない、うちで独自に考えた形をつくっていく、そういうふうに理解しておいてよろしいですか。","respondent":"市川教育次長、古川子ども未来事業部長","answer":"つまりハードの枠が超えられる限りは、そういったことを区長部局のほうに常に投げかけていきたいと考えていますし、逆にそういう投げかけは区長部局のほうから私どもが受ければ、そのことについては検討をしていきたい。この流れは基本に置いておりますので、教育委員会と子ども未来事業部は常に一体となって、子どもが大人になっていく、その貴重な時間を共有しながら子どもの教育にあたる、このように考えております。","voiceIndex":92,"id":"exchange-037"},{"speaker":"林副委員長","kind":"質問","question":"もう１つ、これだけ御殿山幼稚園の移転、それから戻るという話をもう１時間近くやっているんだけれども、教育委員会は御殿山小学校の改築については何も出てこないんだけれども、知らんぷりしていてていいわけですか、現段階では。","respondent":"田村庶務課長","answer":"その辺を踏まえて、通常ですと、基本設計１年、実施設計１年、工期２年というので改築等をやっているんですが、その連動と合わせて、全体で４年で賄えるのか、さらに１年追加するのか、あるいは再開発の完了竣工月日とずれ込むのか。","voiceIndex":95,"id":"exchange-038"},{"speaker":"林副委員長","kind":"質問","question":"その改築するところの御殿山小学校と御殿山幼稚園というのは、一体型にできるという自信はお持ちなんですか。幼稚園のところは向こうが供与してくれる、委譲してくれるスペースに幼稚園をはめ込む。教育委員会の考え方をちょっと聞かせてくれますか。","respondent":"市川教育次長","answer":"ただそのソフトを考えるときにも、御殿山小学校の設計の段階でレイアウトをどうしたらそのソフトが実現しやすいのかということも、１つ検討のポイントにはなるだろうと考えています。","voiceIndex":97,"id":"exchange-039"},{"speaker":"井上委員","kind":"質問・要望","question":"御殿山小学校の改築で以前文教委員会にいなかったので確認なんですが、地域の方もＰＴＡの方も、仮設は建てないで建設がされるということでずっと説明をされていると、校長先生から、以前です、今ではありませんで、保護者の方が伺っていますが、その辺をちょっとだけ確認させてください。","respondent":"市川教育次長","answer":"本日、資料で提供いたしました中で、平成１７年１１月に文教委員会にて報告となって以後、今、委員のご質問にございました仮設はつくりませんというような説明は一切行ってきてございません。","voiceIndex":99,"id":"exchange-040"}]},{"id":"topic-03","title":"（仮称）平塚幼保一体施設整備計画","agenda":"（仮称）平塚幼保一体施設整備計画","exchanges":[{"speaker":"中塚委員","kind":"質問","question":"平塚幼保一体施設整備計画についてなんですけれども、改めて伺いたいのは、この幼保一体施設は、平塚幼稚園と保育園と、その関係がよくまだわかっていないので、要は、認可保育園の新たな設置にもなるということですよね。それと定員が１２０名から１５０名程度ということですけれども、年齢別にどう想定しているのか、ご説明いただけますか。","respondent":"吉岡保育課長","answer":"０歳から３歳の保育園児につきましては、現在のところ、入園のご希望等を踏まえ、どのような形が一番適切なのか、充分検討しまして設定を行っていきたいと考えております。","voiceIndex":107,"id":"exchange-041"},{"speaker":"中塚委員","kind":"質問・要望","question":"開設して入園するときには既に決められているんですよね。その辺のこの定員の設定の仕組みというか、考え方がちょっとわからないのでご説明いただきたいのと、あとこの図面の工程計画のイメージのところに、仮設１のところではまず幼稚園の仮設があって、仮設２のところの保育園が先ほどの保育園の仮設園舎、仮設のときの園庭というのはどこになるのか、教えていただけますか。","respondent":"吉岡保育課長","answer":"保育園の定員の設定の考え方ですけれども、こちらの開設の予定が、幼保一体施設の使用開始になる部分だけ見ましても、平成２４年１１月ということで、若干まだ期間がありますので、その間に検討し、決定することになるかと思ってありますけれども、定員につきましては。","voiceIndex":109,"id":"exchange-042"},{"speaker":"中塚委員","kind":"質問・要望","question":"平塚の周りでもなかなか保育園なんかが大分不足しているという話をよく伺いますので、こういうときにこの保育園の定員の考え方、単なるキャパシティからおのずと決まっているのか、じゃなくて、これだけの保育需要があるからこういうキャパシティが必要なのかと、その辺が先ほどの説明ではよく見えなかったので、地域の子育て支援の拠点という位置付けであれば、地域の保育というか。","respondent":"吉岡保育課長","answer":"ただ施設のキャパシティと、通常、この規模の保育園であればどの程度の定員でいくのかという考え方がありますので、いずれにしても２年後の話ですから、その間の入園希望の状況等々を見ながら、設定をすることになろうかと思います。","voiceIndex":111,"id":"exchange-043"},{"speaker":"西本委員","kind":"質問・要望","question":"確認をさせていただきたいんですが、保育園と幼稚園と、それから区民の方が使われる部分という、これというのは完全に、動線を知りたいんですけれども、完全にシャットアウトしてしまうのか、保育園側から使えるという形もつくり出せるのか、そこはいかがでしょうか。","respondent":"吉岡保育課長","answer":"区民施設等の活用の範囲については、これからの区民施設のほうの運営の問題とも絡んでくるところですので、どのような形での活用ができるのか、今後も検討していきたいなと考えています。","voiceIndex":113,"id":"exchange-044"},{"speaker":"西本委員","kind":"質問・要望","question":"もちろんセキュリティの問題というのは一番大切になりますので、そこはしっかりやっていただきたいというのと同時に、いろいろな施設があるので、多目的ホールとか、スポーツ施設などもありますよね。駐車場というよりは駐輪場のほうが広いほうがいいのかな、という部分があるんですが、それはどういうお考えなんでしょうか。","respondent":"吉岡保育課長","answer":"先ほどちょっとご説明を漏らしてしまったんですけれども、本日、この全体の文化スポーツ施設については区民委員会のほうでご報告させていただいているんですが、こちらは幼保施設の所管なので、区民施設のほうは存じていない部分もあります。","voiceIndex":115,"id":"exchange-045"},{"speaker":"西本委員","kind":"質問","question":"駐輪場なんですが、幼稚園側のほうにも必要だと思うんですけれども、それはどこら辺に設置する形なんでしょうか。","respondent":"吉岡保育課長","answer":"詳細は実施設計を進める中で最終的には詰めていきたいと思います。いずれにしても施設の隣接したところです。","voiceIndex":117,"id":"exchange-046"},{"speaker":"浅野委員","kind":"質問","question":"概略はご説明いただいたんですけれども、保育園と幼稚園の仮の園舎というんでしょうか、建てられるのは右のほうに出ているんですけれども、この三角形のところ、たしか都の土地か何かだったのかなと思いますけれども、ここに駐車場もまた今回の仮の校舎というんでしょうかね、つくらないのは、やはり何か制限があってのことかなとうがった見方をしてしまったんですけれども、仮の建物にしても。","respondent":"吉岡保育課長","answer":"それから細長い通路状のところは、いずれにいたしましても、先ほどお話しいたしましたように、保育園・幼稚園部分の区画は、外部から簡単に入れないような、直接外部の人が入れないような形の管理を行うというふうに考えてありますので、安全上の支障がないように。","voiceIndex":119,"id":"exchange-047"},{"speaker":"林副委員長","kind":"質問・要望","question":"この図のちょっと説明をしていただきたい。１枚目の右側のイラストというか、絵があって、真ん中に階段状の段々がありますよね。２枚目の左端の図に、真ん中あたり、正面入り口の左側に、これも階段状のものが乗っているんだけれども、全然違う絵なんですね。１面と２面。そういうものを出してくるという、こんな違う絵が出てきちゃっていいのか。ちょっと説明してください。","respondent":"吉岡保育課長","answer":"これを上っていくと２階へ出るという構造です。","voiceIndex":121,"id":"exchange-048"},{"speaker":"林副委員長","kind":"質問","question":"自信を持って説明しているみたいだけれども、１枚目の階段が真ん中にあるでしょう。階段状のものがあるよね、あるでしょう。その左側が何もないんだよ。２枚目のこの左側は喫茶室とか絵がかいてあるのね。１枚目と２枚目と全然違う絵なんですか。","respondent":"吉岡保育課長","answer":"ここが先ほど申しましたように１階の地盤面になるんですけれども、こちらについては、階段を上がったこの面は２階の床面になります。こちらは１階の建物部分になりますので、２枚目の１階平面図の喫茶室や便所なんかがかいてあるところがここに入るということです。","voiceIndex":123,"id":"exchange-049"},{"speaker":"林副委員長","kind":"確認","question":"もう１回確認する。２枚目の左側が１階の平面図なのね。２枚目の左側が。１枚目のこのカラーの絵は、２階部分を鳥瞰図みたいにあらわしてあるんですか。そういう判断をしなさいというのを無言のうちに我々に言っているわけなんですね。","respondent":"吉岡保育課長","answer":"これはいわゆるパース図というものでして、一応立体的に見えるように透視図法的にかかれている絵ということでございまして、これは位置関係から言うと、斜め上方から見たような感じのイメージの絵ということになります。","voiceIndex":125,"id":"exchange-050"},{"speaker":"林副委員長","kind":"質問","question":"そうすると、２枚目のこの絵を見て、配置図とかそういうものはつかみなさいと。１枚目の絵は大ざっぱに鳥がのぞいているような鳥瞰図というのか、そういう絵だから、参考程度に見ておいてくださいよと。そういうふうに理解しておけばいいわけですか。","respondent":"吉岡保育課長","answer":"１枚目については、イメージ図といいますか、全体像がわかるようにするために模型をつくったりしますけれども、その模型の絵画版のようなイメージで、イメージはこういう外観になるということでお考えいただければいいと思います。","voiceIndex":127,"id":"exchange-051"}]},{"id":"topic-04","title":"その他","agenda":"その他","exchanges":[{"speaker":"中塚委員","kind":"質問・要望","question":"改めてまず一般質問のほうからなんですけれども、小中一貫教育、小中一貫校の法的位置づけという質問に対して併設校という答弁がありましたけれども、日野学園が開校して、次いで伊藤学園、八潮学園と続いていますけれども、当初、日野学園は文部科学省の研究開発校としてスタートして、その後、いろいろ特区だったり位置づけが変わっていると思うんですけれども、その経過について。","respondent":"和氣小中一貫教育担当課長","answer":"さらに私どもは品川区全域で小中一貫教育に取り組むということで、さらに平成１７年１１月７日に、この区域を原小学校・伊藤中学校だけではなくて、品川区全域を指定してほしいという形で、構造改革特別区域変更申請を出しまして、平成１７年１２月１日付でこれが認可されました。","voiceIndex":133,"id":"exchange-052"},{"speaker":"中塚委員","kind":"質問・要望","question":"ずっとこの経過の位置づけがときどきに変わっていて、何がどんなふうに変わっていたのかずっとわからないままだったので、もうちょっと伺いたいと思うんですけれども、一番初めの平成１４年の文部科学省研究開発学校というのは、たしか３年間の指定でしたか。これは日野学園をつくるにあたっての研究開発学校ということで始まったということなんでしょうかね。","respondent":"和氣小中一貫教育担当課長","answer":"ですから特別の扱いでやれるという、そういう研究開発学校でやったわけですけれども、もちろん日野学園をつくるというだけじゃなくて、小中一貫教育がどういうふうにやっていけるのか、実際にどういうカリキュラムを組んでいくのかという実践研究になりますので。","voiceIndex":135,"id":"exchange-053"},{"speaker":"中塚委員","kind":"質問・要望","question":"その辺がよくわからないんですけれども、一方で３年間研究、つまり１年後にもう一方が動き出すという、何でこの間が１年なのかというのがよくわからなかったのでご説明いただきたいのと、それと一緒に伺いますけれども、平成２０年度の文部科学省教育課程特例校認定ということなんですけれども、認定の取り消しで自動的に取り組んでいいよというふうになったということですけれども、その間。","respondent":"冠木指導課長","answer":"それから平成１９年と平成２０年の間ですけれども、これは平成１９年までと平成２０年からですけれども、構造改革特別区域ということで内閣府が進めてまいりましたけれども、それをぜひ広く一般化していくということで。","voiceIndex":137,"id":"exchange-054"},{"speaker":"中塚委員","kind":"質問","question":"全国展開の経過がつながってきた気がするんですけれども、どうも聞いていますと、節目、節目で報告があったのかもしれませんけれども、こういう流れというのが見えなかったなと思ったんですね。受理があったんでしょう。この６年間でここまでの節目、節目、方向としてはどういう方向を向いているのかがあるんですけれども、この先どこへ向かっていくのか、ちょっとそこを教えてください。","respondent":"和氣小中一貫教育担当課長","answer":"今、先日の答弁でもありましたように、義務教育学校の法制化ということで、法律に中等教育学校と同じように明記をしていただくということでずっと要請をしておりますけれども、文科省の中でも法制化に向けたプロジェクトチームも設置されておりまして、この先。","voiceIndex":139,"id":"exchange-055"},{"speaker":"中塚委員","kind":"意見","question":"政府の議論はあまり読み尽くしていないので、経過がよくわからない部分もあるんですけれども、教育長のお話ですと、教育の地方分権化という流れはよくわかりますけれどもね、一方で公教育がどうあるべきかとか、日本の中で、東京の中でも、どこで生まれても、どんな環境で育っても、しっかりした人格と、あと学習と、そういうのを養っていく。","respondent":"若月教育長","answer":"今、中塚委員がおっしゃったことはもっとものことです。したがって、日本には学習指導要領というものがあって、どの学校へ行っても、どの地域へ行っても、またどんな形態の義務教育でも、学習指導要領によってすべての学習の内容は担保されているということであります。","voiceIndex":143,"id":"exchange-056"},{"speaker":"中塚委員","kind":"意見","question":"もちろん学習指導要領が担保だという話はありましたけれども、いろいろ改革はありますけれども、直接そういう子どもたちに接するのは教師であり、学校であり、そこを支えるのが地域だったり、保護者だったり、ＯＢだったり、町会だったりとあるわけで、子どもたちに接するそういう環境、これはやっぱり要というか、大切だなと思います。","respondent":"若月教育長","answer":"おっしゃるとおりです。したがって、一貫教育であろうと、６・３の普通のあれであろうと、教師が子どもに直接触れ、地域と一緒にやっていく。それは少しも変わらないんだということ、それをよくお考えいただきたいと思います。","voiceIndex":145,"id":"exchange-057"},{"speaker":"中塚委員","kind":"質問・要望","question":"じゃ、次を。昨日配付された資料なんですけれども、昨日もちょっとお伺いしましたけれども、要するにこの位置づけはと。これは何だということをご説明いただきたい。","respondent":"和氣小中一貫教育担当課長","answer":"一番最初は、平成１８年度から始めたのは、文部科学省の新教育システム開発プログラムという委託事業によりまして、私どもが取り組んでいる小中一貫教育の成果についてきっちりと検証していこうということで、国からの委託金が出ますので、それを使いまして、学者であるとか。","voiceIndex":147,"id":"exchange-058"},{"speaker":"中塚委員","kind":"質問","question":"今のご説明ですと、平成１８年、平成１９年が新教育開発プログラムの予算を使ってということだったんでしょうかね。平成２０年は、要するに別の予算を使ったけれども、３年間の検証をしたということで、来年もというお話でよかったんでしょうかね。要するに位置づけがよくわからなかったんですね。それを踏まえた上で、教育委員会としてどう総括をするのか。その指摘をどう受けとめ課題を抽出するのかという。","respondent":"和氣小中一貫教育担当課長","answer":"これを踏まえて私どもは次の政策を考え、打ち出しているですし、継続するものはしっかり継続をしていくというふうに、１つの検証材料にさせていただいているです。","voiceIndex":149,"id":"exchange-059"},{"speaker":"中塚委員","kind":"質問・要望","question":"それはそれで必要でしょう。私が聞きたいのは、教育委員会としての総括を、プラン２１が始まって１０年余りでしょうかね。総括なるものを、検証という形でいいんですよ。それをしっかりと示していくときではないのかなと思うので、そこをご説明いただきたいんですけれども。","respondent":"若月教育長","answer":"今後もこういうことでありまして、もう１度申し上げますが、今やっている教育改革そのものをやめるとか何とかという意味での総括では全くありませんので、その点は十分にご理解をいただきたいと思います。","voiceIndex":151,"id":"exchange-060"},{"speaker":"中塚委員","kind":"意見","question":"その根幹部分のことを否定するための検証はしないというお話だと思うんですけれども、ただ品川区の教育改革そのものの姿が、区民にとってどういうふうに思われているのか、理解されているのか、またまだわからないのか、批判があるのか、姿そのものをしっかり区民に問うて、保護者に問うて、まあ、子どもたちに問うてというのは。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":153,"id":"exchange-061"},{"speaker":"井上委員","kind":"質問・要望","question":"この資料でちょっとお伺いしたいんですが、初めの文部科学省の研究開発というのは、先ほど９年間を通した研究であるということがわかったので、これはこういう資料を出していただいてよかったんですが、その後、構造改革特区の認定のところで原小学校と伊藤中学校となっているんですけれども、このときに第二日野小学校と日野中学校の何かで特区をしたという経過があったのかなと思ったので。","respondent":"和氣小中一貫教育担当課長","answer":"ちょっとわかりづらかったかもしれません。文部科学省の研究開発学校、第二日野小学校・日野中学校は、３年間という最初の形でありますので、平成１４年・平成１５年・平成１６年はその継続でやれるんですね。ですから、特に特区で出す必要がない。","voiceIndex":154,"id":"exchange-062"},{"speaker":"井上委員","kind":"質問・要望","question":"今、振り返ってみると、平成１４年度のときの研究開発校のときに、一貫校の建設ということがここの時点ではなかったと思っているんですけれども、スケジュールのところで、第２校目のところも、どことどこの学校をやるかという議論の中で、鈴ケ森中学校・鈴ケ森小学校だとか、３校ぐらい案が出ていて、その中でここに決まったと思うんですけれども、そういう経過を見ると。","respondent":"和氣小中一貫教育担当課長","answer":"委員は誤解されていらっしゃると思うんですけれども、平成１４年３月に小中一貫校をつくるということについては既に発表しています。それ以降、それに合わせてやりましたし、平成１５年には教育委員会で小中一貫校も決定しております。","voiceIndex":156,"id":"exchange-063"},{"speaker":"井上委員","kind":"質問・要望","question":"発表の仕方が、手順を踏んでいるとおっしゃいましたけれども、私たちは新聞によって報道で知るというところがあって、なかなかうまいこといっていないなと思うんですが、あと２点だけお伺いしたいんですが、平成１４年度の文部科学省の研究開発で、９年を通してという、そしてまた一貫校構想がもしあるとすれば、感覚的にどうして第二日野小学校と日野中学校なんだろうというところが当初からすごい疑問で。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":158,"id":"exchange-064"},{"speaker":"井上委員","kind":"意見","question":"義務教育学校のところなんですが、一貫校、一体学校が義務教育学校というふうに、今、小学校と中学校と名前がそのままなのでというのはわかるんですけれども、品川区の場合には分離型で、一貫教育はしていますけれども、そこも義務教育学校ということに、そういう法制化なのか、それは国がやることだと思うんですけれども、イメージがちょっと。","respondent":"和氣小中一貫教育担当課長","answer":"実際、私どもは私どもの中で、今、分離型の連携校、それから施設一体型と両方展開をしておりまして、各グループごとにやっておりまして、これについて特に大きく変更する考えは今のところございませんけれども、さまざまな形の義務教育が９年間の展開ができるようなことを。","voiceIndex":161,"id":"exchange-065"},{"speaker":"林副委員長","kind":"意見","question":"それを今さらどうするという話を持ち上げないようにしてほしいというのは、これは教育委員会に伝えておきます。あくまでも品川の教育というのを打ち出していくんだと。いろいろな議会の議員の所属する会派の思惑によって教育をどうこうしようという考えにはならないでほしい。品川区の教育委員会として子どもたちを指導していくというのが大義であってほしい。それだけは伝えておきます。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":163,"id":"exchange-066"},{"speaker":"中塚委員","kind":"意見","question":"もう１つは、学校から希望を受け付けているというお話でしたけれども、どういう仕組みで学校からの希望を受け付けているのか、ちょっと仕組みがわからなかったので、あわせてご説明いただけますか。","respondent":"富田学務課長","answer":"そのほかに各学校から、それとは別個だけれども、老朽化してどうにかしてほしいという希望調査も行い、この２度の調査を合わせて購入金額を決めたです。","voiceIndex":174,"id":"exchange-067"},{"speaker":"中塚委員","kind":"質問","question":"新しい教材が入る時期が例年どおりこの時期なんだというお話がありましたけれども、本来、学習指導要領の改訂ですから、その教材も大きくなったと思いますけれども、詳しくはわからないんですけれども、実際に教壇に立っている先生たちが授業に必要となった教材を購入するときに、もっと学校に自由度というんですかね、迅速に購入できるというか、授業に必要になったときに。","respondent":"富田学務課長","answer":"購入の時期ですけれども、今回、議案として提出していますので、本件の議決を正式にしていただきました後に正式な契約を行い、購入の手続きを進めさせていただきたいと思います。","voiceIndex":176,"id":"exchange-068"}]},{"id":"topic-05","title":"行政施設","agenda":"行政施設","exchanges":[{"speaker":"中塚委員","kind":"質問","question":"明倫教育ということで、これだけ見ると、小学校にしては随分難しいことを、難しい言葉でというのかな、表現しているなと思うんですけれども、何が伺いたいかというと、これをどのように授業に生かしているのか、また学校生活の中で具体化しているのか、朝礼だったり、授業だったり、昼休みだったり、部活動だったり、いろいろなところで反映しているのかなとは思いますので、できるだけ時間を確保して。","respondent":"市川教育次長","answer":"まさに地域と、あるいは地元の産業とともに栄えてきたということを、これはわりと日常的に、特に地元の明電舎とのいろいろな交流活動、あるいは明電舎のスポンサーシップの中で提供される事業などを通じて行っているということを認識しておりまして。","voiceIndex":190,"id":"exchange-069"},{"speaker":"中塚委員","kind":"意見","question":"品川の学校もそれぞれ歴史があって、ぜひこういう、とかく基礎学力の向上だ、いろいろテストだとなると、どうしても自分の子どものテストの点数が気になるというのは、ある意味では当然といえば当然なんですけれども、そこの学校の成り立ちや地域との関係を通じて、もっと深いところで子どもたちが学び育っていけると、一回りも二回りも大きくなれる、そういう教育も可能になってくるのかなと感じますので。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":192,"id":"exchange-070"},{"speaker":"中塚委員","kind":"質問","question":"この報告について一言いいですか。何日にここ、次の日、午前と午後、大ざっぱと思いますけれども、行程表をご検討いただけたらと思います。","respondent":"堺委員長","answer":"それはまた正副で検討していきたいと思います。ほかによろしいですか。行政視察についてを終了いたします。以上で本日の予定はすべて終了いたしました。ご協力ありがとうございました。","voiceIndex":195,"id":"exchange-071"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?Template=document&Id=4682#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=9&TermStart=2009-01-01&TermEnd=2009-12-31"}],"sourceMeta":{"pages":0,"characters":61922,"voices":196}},{"id":"h21-20090925-5","meetingId":"h21-cm09","date":"2009年9月25日","dateIso":"2009-09-25","committee":"総務委員会","time":"午前１０時０２分～午前１１時５７分","status":"正式会議録","sourceType":"formal","overview":"総務委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を28件抜き出しています。","hasFullText":true,"topics":[{"id":"topic-01","title":"委員会での質疑","agenda":"委員会での質疑","exchanges":[{"speaker":"本多委員","kind":"質問・要望","question":"３点質問します。当然、進めていて、いろいろと補わなきゃいけないという部分だと思うんですけれども、その計画性についてはどうだったのかという、その３点、教えていただきたいと思います。","respondent":"金子企画財政課長","answer":"これが検証の結果、非常に効果が実証されて、遜色のないものだということがわかってくれば、コストとの見合いもありますけれども、他の区の施設、さまざまな施設がありますけれども、それは区が直営している施設あるいは指定管理者が管理しているところにも。","voiceIndex":5,"id":"exchange-001"},{"speaker":"宮崎委員","kind":"質問・要望","question":"は調査方法も含めてお伺いしたいと思います。それと５１ページのところの一番下の大井町西地区のところですけれども、開発補助金が補正で出てきているんですけれども、当初予算ではなくて、補正で出てきているというのはどういう意味なのか、進捗に合わせて大体補助というのは出るんじゃないかと思うんですけれども、どういうふうなところに来ているのか、そこをお伺いしたいと思います。","respondent":"金子企画財政課長","answer":"この部分につきましては、ご案内のとおりですけれども、密集住宅の市街地ということで、今後の全体計画の進展に伴って、最終的な整備をする予定ですけれども、当面は近所の方々が使えるように広場としてやっていこうということで、例えばトイレの設置であるとか。","voiceIndex":8,"id":"exchange-002"},{"speaker":"宮崎委員","kind":"質問","question":"住民の意見を聞いて、それで計画したんじゃないかなと思うんですけどね。具体的にまだ何件ぐらいというのがわからないというのは、この金額自体どうなのということになるので、大体このぐらい回るので、このぐらいの予算になりましたということじゃないのかなと思うんですけれども、ちょっとお伺いしたいと思います。それで、この地域にということなんですね。あるいは停滞しているということなんでしょうか。","respondent":"金子企画財政課長","answer":"広場の件ですけれども、先ほど３つの広場をまとめてお答えしてしまったんですけれども、トイレを設置するのは今のところ１カ所で、それはその中でも一番広いところですね。","voiceIndex":10,"id":"exchange-003"},{"speaker":"宮崎委員","kind":"質問・要望","question":"その暫定整備のところ、密集事業の種地ということなんですけれども、例えば豊町六丁目のところの公園の予定地のところは、２９号線の計画線内にあるということなんですけれども、あと二葉四丁目のところの２カ所については、密集事業の種地となると、例えばこれから密集事業をやっている公園で、それが今は公園なんだけれども、別な目的になる可能性があるということでいいんでしょうか。","respondent":"金子企画財政課長","answer":"１点目の広場整備の件ですけれども、先ほど申し上げましたところの２カ所目なんですけれども、これは当初、そんなに広くないところなので、あくまでも先ほど申し上げましたとおり、密集市街地住宅事業の種地として開放する予定はなかったんですけれども。","voiceIndex":12,"id":"exchange-004"},{"speaker":"宮崎委員","kind":"質問","question":"先ほどの暫定整備というと、二葉四丁目のところの小さいほうの公園についても、そういった小さいところについても今の説明でいいんでしょうか。それをお聞きしたいと思います。先ほど大崎駅西口のことを紹介しましたけれども、こちらのほうもまだうわさの段階というか、そういう状況なんですけれども、半分ぐらいしか売れていない。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":14,"id":"exchange-005"},{"speaker":"土井委員","kind":"質問・要望","question":"ちょっとお伺いしたいんですけれども、補正というものは、いろいろな性格が含まれているわけですね。それらは特に前者の、最初に言った、具体化してきたから予算化したとか、国が負担を当然しなければならないものだから、国が出してきたというのを予算化するというのはまた当然のことですから、今の地域活性化等々も含めて、緊急経済対策等で決まったからやるというものがあると。","respondent":"金子企画財政課長","answer":"今回、冒頭にご説明しましたとおり、国の補正予算絡みが非常に多いということで、そういう意味では一般会計においては全体１６億円のところを約１２億円ほど、そういったものが対応している部分があります。","voiceIndex":16,"id":"exchange-006"},{"speaker":"土井委員","kind":"意見","question":"それをなぜこれだけにしたのかというのは、それなりの理由があるんだろうなと。何十分の１なり何なりの、何億という金額なのかどうか知らないけれども、それはどういうことなんでしょう。そして、それに品川区としてはこれに箇所づけしたということだろうと思うので、その辺の考え方をちょっと、これからもこういうのがあったらどうするのという参考にもなる気がします。","respondent":"金子企画財政課長","answer":"残る２分の１はこれも当てられますよということで、言ってみれば推奨がありましたので、これについては使う方向で考えていると。","voiceIndex":18,"id":"exchange-007"},{"speaker":"土井委員","kind":"質問","question":"ということは、もともと品川区の割り当て分としては７,０００万円ほどの割り当て分があったんですよという今のお話ですね。そして、今、そこで先ほどあったように、なかったらどうしたのというのは、やっぱりある種の問題だと思う。デジタル化しなければいけない。そのときには国の負担が普通なら２分の１ですよと。それは区民のため、子どもたちのために使うのは別に何の問題もないわけですからね。","respondent":"金子企画財政課長","answer":"もう１つは、授業で使うということで、これは通常の大きさのテレビというよりは大型のテレビを想定していまして、国のほうでも５０インチぐらいという話がありましたけれども、品川区としては４２インチで、例えば視聴覚室、あるいは教室等でも使えるように。","voiceIndex":20,"id":"exchange-008"},{"speaker":"土井委員","kind":"意見","question":"今の例えば、ちょっとデジタルテレビを出しちゃったのがいけないのかもしれないけれども、デジタルテレビで言えば、黙っていても、極端な言い方をしたら、品川区で買いますよということでなったら、今までの経緯から言って、学校教育の関係で２分の１は出してくれるんだろうなと。そうですよね。そのようなものと、箇所づけ等についてはどういうふうな考え方をしていくのか。ここをちょっと聞きたい。","respondent":"金子企画財政課長","answer":"後先の問題、にわとりが先か、卵が先かみたいなところもあるかと思うんですけれども、ただ私どもとしましては、ここに載っているものは、例えば今、デジタルテレビの話がありましたけれども、プレミアム共通商品券にしても、また修学旅行のキャンセル代にしても。","voiceIndex":22,"id":"exchange-009"},{"speaker":"土井委員","kind":"意見","question":"最後に、本予算の場合でも、補正予算の場合でも、具体的箇所づけなどをやって、それで国にこういう形で我々仕事をするので、補助してください。この項目の補助金を出してくださいということで申請をして、よしということになって、最終的に決算のときにいただきますと。執行することによって初めて、そして認定されることによってのみ、出てくるんだと思うんですけれども、それでいいんですよね。","respondent":"日下部企画部長","answer":"それを自治体としてどうか有効に活用して、地域のためにも活用してほしいという提案もあったわけですから、そういう意味では、国と地方のお互いの１つの地域の活性化なり何なり、そういった点で一致したところで、財源の有効な活用が図られるということでありますので、今後とも。","voiceIndex":24,"id":"exchange-010"},{"speaker":"土井委員","kind":"質問","question":"まあ、いいからここにモニュメントをつくろうよみたいな格好で、変にやるようでは困るねということなので、したがってそういう意味も含めて、ちょっとお伺いさせていただいたので、これからもやっぱり一般会計の本予算のときであれ、補正予算のときであれ、同じ発想でやっぱり品川区がやっているんだということで、あってほしいと思いながら、終わらせていただきます。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":26,"id":"exchange-011"},{"speaker":"山元委員","kind":"質問・要望","question":"１つは５３ページのプラン２１推進事業追加分の中に、特色のある教育活動経費ということで、スポーツ教育推進事業、自然体験活動開発支援事業、小学校、中学校があるんですけれども、具体的にどの学校かということと、何校かある学校の中に、あえてこの１校、２校を選んだ基準というか、何かそういうものがあれば教えていただきたいということと、それからもう１つ。","respondent":"金子企画財政課長、中川原広報広聴課長","answer":"ただ、手を挙げる学校が多い場合には、より研究の成果が発揮できるようなところを、そういう観点から選んで指定するというふうに聞いているところで、そして先ほど申し上げた４校になったです。私のほうから、４１ページのまちのサインの現況調査についてお答えいたします。今年度当初予算で、まちのサイン計画というものの見直し経費を算定しております。","voiceIndex":28,"id":"exchange-012"},{"speaker":"山元委員","kind":"質問","question":"１つ、先ほど公募によってプラン２１の特色ある教育ということで、特色という、例えばスポーツ教育に関して、御殿山とかいろいろ名前が挙げられたんですが、この学校は例えばサッカーが強いとか何かそういうことがあるんですか。そこに力を入れようとか、それであえてこの公募もあったでしょうけれども、それに決定的な何かがないと、ただ手を挙げたから、そこにしようというものですか。","respondent":"金子企画財政課長","answer":"学校の名前と募集の仕方は確認したんですけれども、申しわけないんですけれども、そこのそれぞれの学校の特色ということまでまだちょっと確認していないので、それは後でご説明させていただければと思います。","voiceIndex":31,"id":"exchange-013"},{"speaker":"須貝委員","kind":"確認","question":"５１ページの東急目黒線連続立体交差事業の中の家屋損失補償費等負担金なんですが、現実、どの程度の被害があったのかということをちょっと確認の意味で、あとどのような被害状況だったのかをお聞かせ願いたいのと、あと５３ページの密集住宅市街地整備促進事業として、５億円使っているわけですが、ここで密集住宅市街地整備ですよね。","respondent":"金子企画財政課長、大沢委員長","answer":"具体的な被害状況については、掌握しているわけではないので、私どものほうで聞いているのは、あくまでも、今まで工事を進めてまいりましたので。総合審査における答弁ですので、総合的、包括的なご答弁のほうで結構ですので、個別的なものに関しては、そこまでお答えしなくて結構です。密集住宅市街地は二葉三丁目、四丁目、豊町六丁目のかなり広範囲に設定しています。","voiceIndex":34,"id":"exchange-014"},{"speaker":"須貝委員","kind":"確認","question":"実際、ちょっと我々も見た範囲では、ちょっとＪＴの跡地は密集市街地に網がかかっているのかもしれないですけれども、項目の内容とすると、名前がちょっとふさわしくないのかなという、確認のために聞いた次第です。後で、もしわかれば教えてください。ここの繰越金というのが、これは区からの繰入金という解釈で、区から３億６,４００万円ですか、それを出してという考え方でよろしいんですよね。","respondent":"金子企画財政課長","answer":"そういう意味では、年度の当初予算は見込みでつくっておりますので、相差の部分があります。その相差の部分のところから、こちらのほうに繰越金を多少積み増しするという格好で計上しています。","voiceIndex":38,"id":"exchange-015"},{"speaker":"須貝委員","kind":"質問","question":"ということは、なかなかわかりにくいですが、今回区から繰り入れで、実際一般財源から入れて使っている、今回補正に対して使う額というのは、どこかに載っているんですか。何か報告ではいろいろ細かく載っておりますが、総額で今回補正に対しては、一般財源から幾らということで載っていますが、それを区からは今回は一切繰入金というか、予算の持ち出しはないというふうな見方をすればいいんですか。","respondent":"金子企画財政課長","answer":"ちょっと質問趣旨を諮りかねるところがあるんですけれども、あくまでも平成２０年度予算の中で決算をした結果繰り越しをした額があります。","voiceIndex":40,"id":"exchange-016"},{"speaker":"須貝委員","kind":"質問","question":"わかりました。ということは、私は思うんですけれども、せっかく区としてこういう国庫の補助金等が入ってきて、これからこういうふうに品川区がいろいろな所管で考えられて、幅広く予算をそういうふうに使っていくというご努力は本当にすばらしいと思うし、いろいろな分野にわたって雇用確保、緊急雇用ですか、あと経済対策ということその他教育関係も本当に評価できるものだと思います。","respondent":"金子企画財政課長","answer":"補正予算ですので、先ほど冒頭でも申しましたとおり、年度当初に予定していなかったもの、あるいは今回メインを占めております、国等の補助金等の中から判断しているわけですけれども、当然のことながら、補正という前提がありますので、現在の経済状況を見ながら。","voiceIndex":42,"id":"exchange-017"},{"speaker":"宮崎委員","kind":"質問・要望","question":"中身を見れば、いろいろ新型インフルエンザ、これは当然やらなければいけない。プレミアム商品券の助成等は商連の要望ということもあって、それは当然だと思うんですけれども、ちょっと今回のこういう点はおかしいなというのは、やっぱり大井町西地区の開発への補助金、これは出すほうもそうですけれども、使うほうも、私はこれはおかしいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":49,"id":"exchange-018"},{"speaker":"宮崎委員","kind":"質問","question":"この後期高齢者医療保険料の徴収ということなんですけれども、それが緊急雇用で雇うということなんですけれども、いわゆる滞納を整理しなきゃいけないことだと思うんですけれども、この状況を具体的に、どういうふうな状況なのか、具体的にどういうふうに回収をやっていくのか。何人ぐらい雇っていくのか、その辺がわからないので、教えていただければと思います。","respondent":"金子企画財政課長","answer":"後期高齢者医療関係のまず雇用の人数なんですけれども、具体的に対応するのは２人なんですけれども、今現在、始まったばかりですけれども、保険料の収納率が９７.１％という収納率だったわけで、そういう意味では滞納者の数で申し上げると。","voiceIndex":54,"id":"exchange-019"},{"speaker":"宮崎委員","kind":"質問・要望","question":"１０月から天引きが始まっているんですけれども、この収納率９７.１％、全体のところなのかということですけれども、以前も決算特別委員会だったかと思うんですけれども、全体の普通徴収だったときは、高齢者のところで勘違いしている人が非常に多かったというのが実際あって、ここのところの７月、８月、９月の対策というのは、全体の普通徴収だったとき。","respondent":"金子企画財政課長","answer":"その細かい数字は持っておりませんので、わかりません。","voiceIndex":56,"id":"exchange-020"},{"speaker":"宮崎委員","kind":"質問","question":"例えばこれから、この２人がいろいろ対応していくんですけれども、滞納している理由とか、そこのところは何か傾向というのは、区のほうとしてはつかんでいるでしょうか。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":58,"id":"exchange-021"},{"speaker":"宮崎委員","kind":"質問","question":"いや、私は区としてどういう滞納の理由なのかと。これをわざわざ２人配置するわけですよね。大体人をつけるにしても、そういう理由というのが、何か問題意識というか、そういうのがあったんじゃないかなと思うんですけれども、そこら辺のところはどういうふうに考えているのですか。","respondent":"榎本人事課長","answer":"この補正の中では、上の段は正規職員の分が載っていますけれども、やはり制度の変わり目の部分で、かなり繁忙期を極めているということもありまして、正規職員を３人分追加した職員というのも一緒に合わせて。","voiceIndex":61,"id":"exchange-022"},{"speaker":"宮崎委員","kind":"意見","question":"私はやっぱり後期高齢者の７５歳以上のところは、私がアンケートをとると、非常に生活が厳しくなってきているというのが出てきています。そういうところで、天引きをやると。今度は徴収できないところは徴収に回るというのは、私は住民感情から言っても、非常に理解できない部分だと思います。反対です。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":67,"id":"exchange-023"},{"speaker":"宮崎委員","kind":"質問","question":"ちょっと細かいことですけれども、精算で返すものだと思うんですけれども、国庫支出金等となっているんですけれども、国庫支出金と支払基金それぞれ大体どのくらいの金額になっているか、もうちょっと詳しい中身がわかるでしょうか。","respondent":"金子企画財政課長","answer":"国庫支出金等の中身でありますけれども、三者ありまして、国、東京都、支払基金であります。国についてが１億４,０００万円ほどです。それから東京都につきましては１,０００万円ほど。支払基金が１,４００万円弱というような金額になっております。","voiceIndex":72,"id":"exchange-024"},{"speaker":"宮崎委員","kind":"確認","question":"保険料の負担割合のほうから行くと、ちょっと国の大体半分ぐらいが東京都になるのかなと思ったんですけれども、この違いが出てくるというのは何かわかるでしょうか。所管じゃないのでわからないと思いますが、ちょっと私の記憶だと、国の半分が東京都だったかなと思うんですけれども、大分金額に差があるので確認しておきたいんですけれども。","respondent":"金子企画財政課長","answer":"今、国と都と支払基金を３つに分けましたけれども、その中でまたそれぞれ細かい部分が幾つかありまして、それをトータルして、こういうふうになっているので、お尋ねのところちょっと直接お答えできないんですけれども。","voiceIndex":74,"id":"exchange-025"}]},{"id":"topic-02","title":"では２の行政視察についてですが、先に３のその他","agenda":"では２の行政視察についてですが、先に３のその他","exchanges":[{"speaker":"宮崎委員","kind":"意見","question":"全戸配布のことなんですけれども、今の説明に対して、考え方、どういうときに全戸配布をやるのかというのをもう１回聞いておきたいんですけれども。","respondent":"中川原広報広聴課長","answer":"今回は、長期基本計画ができまして、今後１０年、また基本構想が定まりましたので、それをグラビア部分に特集しまして、それと品川ガイドの本体の部分をあわせまして、保存版としてお使いいただく形で配布をするものです。","voiceIndex":92,"id":"exchange-026"},{"speaker":"宮崎委員","kind":"質問・要望","question":"これは議会などでも質問が出てきていますけれども、そういう意味では必要な情報というのは広報で出ているわけですから、やっぱりこれが必要、これが必要じゃないとか、みんなに知ってほしいとか、そういうふうに区別するんじゃなくて、やっぱり全部全戸配布するというふうにしてほしいと。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":94,"id":"exchange-027"},{"speaker":"須貝委員","kind":"質問・要望","question":"今、庁舎の駐車場なんですが、やはりまだちょっと混んでいるところが見受けられるんですね。今、民間の駐車場をもちろん借りているわけですが、現に庁舎の駐車場に区の関係、また区の職員も一般の車とか、それからパトロール車も一律とまっている。せっかく区が区民サービスで配慮しているところが、ちょっと無になっているのかなという気もしますので、そこはちょっと要望だけさせていただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":96,"id":"exchange-028"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?Template=document&Id=1834#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=5&TermStart=2009-01-01&TermEnd=2009-12-31"}],"sourceMeta":{"pages":0,"characters":34343,"voices":105}},{"id":"h21-20090928-14","meetingId":"h21-cm09","date":"2009年9月28日","dateIso":"2009-09-28","committee":"行財政改革特別委員会","time":"午前１０時０３分～午前１１時４６分","status":"正式会議録","sourceType":"formal","overview":"行財政改革特別委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を32件抜き出しています。","hasFullText":true,"topics":[{"id":"topic-01","title":"特定事件調査","agenda":"特定事件調査","exchanges":[{"speaker":"渡部委員","kind":"質問","question":"幾つかお伺いしますが、最初に数字を追いかけてしまっていたんですが、そもそもこの利用率の出し方はどういうふうに出していますでしょうか。平日、休日とか、分子と分母を明確に教えください。ティーンズ館は８時までですか。例えば子どもたちがいる時間帯とそういう目的外使用で訪れる人たちと合わせていられるようにしているのかというところを教えてください。","respondent":"久保田行財政改革担当課長","answer":"利用率の分母・分子の考え方ですけれども、こちらにつきましては、それぞれの施設の利用可能な日数を分母としています。","voiceIndex":5,"id":"exchange-001"},{"speaker":"渡部委員","kind":"確認","question":"最後、確認だけなんですけれども、それは例えば中小企業センターであれば、同じ中小企業センターでも、この部屋は工事をやっていたから使えませんでしたという日は分母から引いてある。必ずしも分母は一緒じゃないという認識でいいんですね。","respondent":"久保田行財政改革担当課長","answer":"委員がおっしゃるとおりで、工事等で使っていないところは分母から除いてありますので、同じ集会所の施設の中でも、分母の回数は異なるです。","voiceIndex":7,"id":"exchange-002"},{"speaker":"川西委員","kind":"質問","question":"基本的なところで、おさらいみたいになりますが、教えてください。荏原区民センター、１０時まで開館というこの経緯があったと思いますけれども、もう１回聞かせてください。それから区民集会所の使用料の決定基準、これは面積比なのかどうかということも含めて、もう１回伺います。これの決定の経緯も教えてください。","respondent":"久保田行財政改革担当課長","answer":"ご質問にお答えいたします。１点目の荏原区民センターの開館時間が１０時までといったところの経緯ですけれども、大変申しわけございません。私のほうで１０時までになった経緯を把握してございませんので、確認いたしまして、後ほどご回答させていただきたいと思います。","voiceIndex":9,"id":"exchange-003"},{"speaker":"川西委員","kind":"質問","question":"そうしますと、２番目の区民集会所の使用料については、主に平米数で決定するということで承知しておいていいですか。","respondent":"久保田行財政改革担当課長","answer":"委員おっしゃるとおり、基本的には平米数のほうから算出しまして、それぞれの施設の使用料を定めているといったところです。","voiceIndex":11,"id":"exchange-004"},{"speaker":"川西委員","kind":"確認","question":"それから先ほどの減免団体の申請は、２年に１回といいますと、今度何年が対象になりましょうかが１つですね。それから中小企業センターを利用している人から伺っていることなんですが、減免はないけれども、品川区に住んでいて、品川区で働いている人たちの名簿を出すと、予約が早くできると聞いているんですけれども、この辺を確認したいと思います。","respondent":"久保田行財政改革担当課長","answer":"次に中小企業センターの利用ですけれども、委員からお話がございましたように、勤労者が使用する場合には、１ページの概要のところにも書いてありますけれども、使用日の属する月の４カ月前の２１日から末日までに予約ができるということで。","voiceIndex":13,"id":"exchange-005"},{"speaker":"川西委員","kind":"質問","question":"ちょっとだけもう１つ。五反田文化センターは今、改築中で、そうでしたね。そこを使用していた団体の方から、かなり使用料が上がるのだろうかという心配を時々話題にしておられます。その辺については、まさかきゅりあんより高くならないと思いますよと想像で言っていますが、見通してとして検討はどこかでされているんでしょうか。","respondent":"久保田行財政改革担当課長","answer":"検討は所管課のほうでやっていると思いますけれども、使用料の算定にあたりましては、施設がきれいになったからということで料金が上がるという考え方では今のところはないと、それは基本的に考えているです。","voiceIndex":15,"id":"exchange-006"},{"speaker":"安藤委員","kind":"質問・要望","question":"りんし２１のところなんですけれども、あまりこの施設について私自身、認識していなかったもので、改めてお伺いしたいんですけれども、著しく利用率が低くなっているんですけれども、その原因があれば教えていただきたいのと、あとこの施設については、普通の集会所という感じの施設なんでしょうか。教えてください。","respondent":"久保田行財政改革担当課長","answer":"１点目です。","voiceIndex":17,"id":"exchange-007"},{"speaker":"安藤委員","kind":"質問・要望","question":"企業による使用の実態と考え方について伺いたいんですが、区民集会所の話なんですけれども、地域住民の集会の利便に供することにより、福祉の増進に寄与することを目的とするとあるんですけれども、企業が例えば研修ですとか説明会とかで使う場合もあると思うんですが、こういった企業の利用に対する区の考え方をお伺いしたいのと、あと各企業とか、認定団体とか。","respondent":"久保田行財政改革担当課長","answer":"例えば営利目的ということであれば、物品の販売を行うとか、不特定多数の方を集めて製品の説明会をやるとか、そういったものについては営利目的に該当するということでお断りをしておりますが、委員からお話がございましたように。","voiceIndex":19,"id":"exchange-008"},{"speaker":"安藤委員","kind":"質問","question":"考え方はわかりましたけれども、実際に企業の皆さんがどれくらい使用されているか。特に大崎第１地域センターとかですと、すごく駅から近いとか、周りに会社も多いとか、立地条件によると思うんですけれども、そういったことはつかんでいらっしゃるかという後段の質問はいかがでしょうか。","respondent":"久保田行財政改革担当課長","answer":"ただ数字としてそういうものが抽出できるかということは、所管のほうに確認しないとなかなかお答えできないなです。企業といいましても区民料金で貸し出しをしておりますので、そういったものが抽出できるのかどうかというのは、所管課のほうと相談させていただきたいと思います。","voiceIndex":21,"id":"exchange-009"},{"speaker":"安藤委員","kind":"質問・要望","question":"次の質問なんですが、地域にいろいろ集会所が配置されていますけれども、例えば上大崎ですとか豊町、あるいは二葉の地域とか、地域によって若干集会施設の配置に偏りが現在出ているんじゃないかなと感じているんですけれども、そもそも現在こういった配置になっているわけですけれども、どのような考え方で、どういう経緯で現在のようになったのか教えていただきたいのと、あとこれからの話なんですけれども。","respondent":"久保田行財政改革担当課長","answer":"私どもとしましては、限られた地域の中に、できるだけ多くの集会所を設けられればいいんですけれども、場所等につきましてもいろいろと限られてありますので、そうした中で、本日ご説明しましたように、集会所だけではなくて、文化センターとか、児童センターとか。","voiceIndex":23,"id":"exchange-010"},{"speaker":"安藤委員","kind":"質問・要望","question":"考え方という形でいいので、そういった集会所施設の配置の考え方をもう１度お伺いしたいのと、これまでの経緯というところではあまりご答弁がなかったので、現在のような区民集会所の配置になったという、これまでこういった経緯でこういうふうになりましたよというところを、もう少し教えていただきたいと思います。","respondent":"久保田行財政改革担当課長","answer":"ただ地域によりましても、縦に長いとか、東西に長いとかいろいろありますので、そうした中で多少ご不便をおかけしている地域というものもあるかもわかりませんけれども、全体的に地域バランスを考えながら、１３の地域に集会所を配置してきたという経過です。","voiceIndex":25,"id":"exchange-011"},{"speaker":"阿部委員","kind":"質問","question":"それから先ほども話題に出ましたりんし２１、確かに駅から遠くて使いにくいというのもあると思いますけれども、それにしても大変利用率が低いということで、今、私が聞いた話の中では、企画を中心に今後どのような活用策をとっていくかということで、既に検討もされているということもちらと聞いたような気がするんですけれども、その辺のことをお伺いしたいと思います。","respondent":"金子企画財政課長、久保田行財政改革担当課長","answer":"そういう意味では、現在の利用料金の体系というのは、中小企業の振興という意味からも、こういう位置づけでやってきたところでありますし、今後、特に大企業等の利用が増えてくるとか、そういったことがあれば別ですけれども。ただ、利用率が低いといいましても、現に約５％の利用率でもお使いになっていただいている方がいますので、そういった中でどういった活用ができるのかなというところは、今後引き続き検討をしていきたいと考えているところです。","voiceIndex":27,"id":"exchange-012"},{"speaker":"阿部委員","kind":"質問","question":"駅から遠いから低いんじゃないかというだけのご答弁では、あまりどうなんでしょうね。きちんと質問のあったことについては、現在の状況、それに対してどういう対応をしているかということについては、別に隠すような話ではないわけで、ご検討していることはいいことなわけですから、きちんとおっしゃっていただければと思います。","respondent":"日下部企画部長","answer":"ただその後、阿部委員のほうから今のような形で具体的な検討についてどう進めているのかというご質問がありましたので、それについてはしっかりとまたご答弁申し上げたですので、その辺は十分にご理解をいただきたいと思います。","voiceIndex":30,"id":"exchange-013"},{"speaker":"阿部委員","kind":"質問","question":"その２つの間を埋める発想がどうもわかりにくかったと思いますけれども、要はご検討されているということは、先ほどのご質問の中で、なぜ低いのかということが、駅から遠いからというだけではないということを前提にご検討がされているわけですよね。だから駅から遠いというだけのご答弁では十分ではなかったのではないかと言わせていただきました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":32,"id":"exchange-014"},{"speaker":"渡辺委員","kind":"質問・要望","question":"利用率のこと、これは各施設共通という考え方で伺えればと思います。これもやはり自民党内でも大分議論になって要望してという経緯もあった中で、個々のケースでもわりと大きな施設にはそういうのがありがちかなと。余談ですが、グラウンド等でも、そういった施設では多数お声を自分なんかも把握しているつもりなので、その辺の利用率と予約に対する考え方を伺えればと思います。","respondent":"久保田行財政改革担当課長","answer":"利用率ですけれども、私ども例えば集会所であれば、地域の方にご利用いただくというところが目的ですので、例えば地域の方がお使いになるときに、一般的な方がお使いのときには２カ月前からの予約ということですけれども。","voiceIndex":33,"id":"exchange-015"},{"speaker":"山内委員","kind":"質問","question":"１枚目、施設の概要の中で、料金が各施設ごとに細かくというか、記載されております。２ページ目から年間利用率等々利用者の数、いろいろ書かれておりますが、ここで質問なんですが、この一覧を見ますと、年間大体幾らぐらいの利用料金があがったのかということが記載されていないんですね。金額的なことが記載されない何か理由があるのか、その辺をお尋ねしたいんですが。","respondent":"金子企画財政課長","answer":"こういうのが平成１９年度実績の数字としています。","voiceIndex":35,"id":"exchange-016"},{"speaker":"山内委員","kind":"意見","question":"それは全体のあれですよね。そうじゃなくて、せっかくここまで細かくやっているんだったら、だったら各施設で年間幾らぐらいの利用料があがったんですよということを記載してもいいはずなんですね。それが何でできないのかということを私は今聞いているんですけれども。","respondent":"久保田行財政改革担当課長","answer":"本日は施設の概要ということで、こういった形で資料をお示しさせていただいているところですので、今後またそういうご要望がございましたら、正副委員長のほうと調整させていただいて、資料としてご提供していきたいと考えているところです。","voiceIndex":37,"id":"exchange-017"},{"speaker":"山内委員","kind":"質問・要望","question":"現にそれは我々も知っておくべきではないかと思うんですね。そういう意味で、そういう金額的な部分でもやっぱり１つ把握しておくことが大事だと思いますので、これは要望になりますけれども、一つ一つの施設で大体幾らあがっているのかということを、ちゃんと明確にしていただきたいなという要望で終わります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":39,"id":"exchange-018"},{"speaker":"中塚委員","kind":"意見","question":"先ほど料金の話が出ていましたけれども、一方で予約をして料金を支払って取り消す場合というのがあるんですね。いわゆる取り消しだったり、払い戻しであったり、この仕組みがどうなっているのか、ご説明いただけますか。","respondent":"久保田行財政改革担当課長","answer":"シルバーセンターにつきましても、申し込みのときに使用料をお支払いいただいて、こちらにつきましては、使用日の２日前までに取りやめた場合には、５割返還という規定をさせていただいているところです。","voiceIndex":40,"id":"exchange-019"},{"speaker":"中塚委員","kind":"質問・要望","question":"それと先ほどから利用率についていろいろご議論がありましたけれども、先ほどからのご説明ですと、７割、８割は適正じゃないかというお話がありましたけれども、利用している方にお話を聞くと、特に８割を超えてくるとなかなか取れないなというのが実感で、取りにくい施設だなというのがみんなわかってくると、１カ月前だったり、２カ月前だったり、どんどん早くなってしまって。","respondent":"久保田行財政改革担当課長","answer":"８０％を超えるとなかなか利用できないという実感があるというご質問で、その辺の工夫をですが、例えば集会所でありますれば、使用料の申請の翌日から７日以内にお金をお支払いいただくという規定になってありますので、例えば電話予約等をされますと。","voiceIndex":42,"id":"exchange-020"},{"speaker":"中塚委員","kind":"質問・要望","question":"畳の改修にしてもそう思います。例えば日本舞踊だったり、畳を使っての利用が多いところは、当然畳のすり減りも多くなってしまうわけで、それに見合った改修というのも当然必要になってくるとは思うんですけれども、その利用実態や利用目的、また区民要望、こうしたものの把握というのはどのように行っていらっしゃるのかを教えていただきたい。荏原区民センターのレクホールは年間だと９５％ですか。","respondent":"久保田行財政改革担当課長","answer":"レクホールについてですけれども、委員ご指摘のように、ご利用の率が高いといった状況がありますが、私どものほうで具体的にこのレクホールがどういった形で使われてこういう率になっているかというのは把握してございませんので、こちらにつきましても、推測するに。","voiceIndex":44,"id":"exchange-021"},{"speaker":"中塚委員","kind":"質問・要望","question":"利用実態、利用目的、施設の窓口で把握している。いろいろな団体が練習場所がないという話をよく伺うんですね。足をドンドンとやると下に響いてしまってなかなか練習ができないとか、そういうのもよく伺うんですけれども、これだけレクホールが利用者にとっては利便性が今は悪いなと思うんですけれども、そこはどうお考えなのか、最後に教えてください。","respondent":"久保田行財政改革担当課長","answer":"レクホールのほうですけれども、今、数がというお話でございましたけれども、例えば五反田文化センターは今、改築しておりますので、そちらのほうでもそういったレクホール的な活動のできる場所というのを整備してまいりますし。","voiceIndex":46,"id":"exchange-022"},{"speaker":"市川委員","kind":"質問","question":"２点ほど伺いたいんですが、先ほど区境のエリアでは非常に集会所が少ないので、大崎、上大崎のほうはシルバーセンターの目的外使用もあるというお話だったんですけれども、こう見ていると、中心部分とか、駅に近いところに集会所が集まっていたり、いろいろな施設が集まっているなということが改めてわかるんですけれども、区境のところは。","respondent":"久保田行財政改革担当課長","answer":"一方、港区のほうにつきましては、港区のいろいろな考え方があるようで、集会所系の利用については、区民以外の方には貸し出しはしていないという、これは政策的な区の考え方ということで聞いておりますので、港区の施設というものについては。","voiceIndex":48,"id":"exchange-023"},{"speaker":"市川委員","kind":"質問","question":"もう１つ、利用のないときの目的外使用のところの管理についてはわかりました。かなり使わないで人を配置したりしなかったりというのは、それもなかなか大変な作業の１つになってくるのかなと思うんですけれども、その辺のところで行き違いとかで使えなかったりということはないんでしょうか。なかなか難しい管理の仕方だなと思いますので、ちょっとそこだけ教えてください。","respondent":"久保田行財政改革担当課長","answer":"施設のほうに直接申し込みいただいているですので、そういった例えば申し込んだのにシルバー人材センターの人が来なくて使えなかったといったことがないようには努力していると聞いておりますが、万が一そういうことが起きても。","voiceIndex":50,"id":"exchange-024"},{"speaker":"川西委員","kind":"質問","question":"もう１つ、長年にわたって区民集会所の区民センター、地域センターですね。そういう点で、私どもなんかはいすの部屋が空いていない場合にも、この日しか会議ができない、集まりができないというときに、やむを得ず借りるということがあったものですから、長年訴えてきました。しかしこの実績を見ると結構な数字ですから、やはり和室というのはこの日本社会の中で必要なんだなと。","respondent":"久保田行財政改革担当課長","answer":"それと私の経験等からもあるんですけれども、例えばお子さん連れのお母さん方がサークル活動とかで使うときには、和室のほうが使いやすいといった声も聞いておりますので、そういう中では一定程度和室というものが必要なのかなと考えているところです。","voiceIndex":52,"id":"exchange-025"},{"speaker":"須藤委員","kind":"質問","question":"私が聞き漏らしたのかもしれないんだけれども、平成２０年１０月の利用実績、平日利用率という数字が出ているのと、年間利用率というふうに出ているんだけれども、ここは何で１０月だけを取り上げてこうしたのかね。そうすると、我々が見ているのは、実際に利用があるのかないかは年間利用率しか見られないわけなんだけれども、その辺は何か説明があって１０月だけというふうにとられたのか、教えてください。","respondent":"久保田行財政改革担当課長","answer":"今後、集計のあり方につきましては、委員からご指摘いただきましたように、各所管のほうとも調整をして、できるだけ精緻な集計ができるように努力していきたいと考えております。","voiceIndex":54,"id":"exchange-026"},{"speaker":"須藤委員","kind":"質問","question":"多分そんなことだろうと思ったんだけれども、きちんと行政がしっかりやっていくならば、やっぱり年間で云々といったら１月から、年度でやるなら４月から３月まで、それが平日はどうなんだ、土・日はどうなんだというのがきちんととらえられるような、今、こういうＩＴの時代なので、インプットすればどんどんできちゃう形なので、そういうプログラムを各施設に渡して、そうしていかないと。","respondent":"久保田行財政改革担当課長","answer":"平成２０年度につきましては、そういう微妙な集計をとっているかどうか、よく所管のほうに確認をしないとならないので、この場でちょっとできるというところではお答えできないところなんですけれども、１０月というところで利用実績をとっているところを見ますと。","voiceIndex":56,"id":"exchange-027"},{"speaker":"須藤委員","kind":"質問・要望","question":"全館利用率はびしっと出ました。質問されて、土・日・平日はどうなっているんですかと。年間が５７.９％ですよと。９月はこういう状況ですよというのはこれで１つの例として、土・日はこういうふうになっていますよという例の１つとしては、全体的な中の一部としては１２分の１としてわかるけれども、やはり全体を比較するなら全体を比較した数字で出していただきたいと、正副委員長にお願いをしておきます。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":58,"id":"exchange-028"},{"speaker":"若林委員","kind":"確認","question":"ただ１回取り消して、例えば品川第一の第１集会室はキャンセルしたけれども、日にちを違えて同じ第１集会室とか、同じ日にちで第２集会室とかというふうに取り直した場合に、相殺ができると思ったんですが、それを確認させていただいて、そうすると、品川第一の中も含めて、それが大崎第二であろうと、荏原第三であろうと、要するにお金の入るところは全部会計に入ってくるわけですよね。返還された口なので。","respondent":"日下部企画部長、久保田行財政改革担当課長","answer":"私のほうから１点目についてお答え申し上げたいと思います。区有施設につきましては、確かにご指摘にありましたように、数年前に１度、行革委員会でご検討いただいた経緯があります。こちらにつきましても、そういったご要望を受けて、今後、調査研究をしていかなければならないのかなですので、またどういった手法ができるのかとかというのも、私どものほうでも検討をしていきたいなとは考えております。","voiceIndex":59,"id":"exchange-029"},{"speaker":"阿部委員","kind":"意見","question":"今のキャンセルポリシーの話なんですけれども、今、世の中を見てみても、例えばＪＲの切符とか、キャンプ場の予約とか、キャンセルはキャンセル、だけど変更という枠組みがあるというものも結構世の中にはあると思います。先ほどご答弁の中で、今後ご検討という言葉も出ましたので、キャンセル以外に変更という考え方も取り入れながら規則を見直すということもあってもいいのかなと、これは意見です。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":63,"id":"exchange-030"},{"speaker":"中塚委員","kind":"質問・要望","question":"つまりどの施設でも借りられる。１回登録すると、また消すときは消すときの仕組みがあって、利用者にすればこっちからこっちという思いなんだけれども、例えば１０日じゃなくて１１日だったとか、１０日の第１講習室じゃなくて第２だったということなんだけれども、オンライン上はそこがうまくいかないみたいな実感をよく聞くし、私もすごく感じるんですね。よろしくお願いします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":64,"id":"exchange-031"},{"speaker":"山元委員","kind":"質問・要望","question":"１つだけ関連するんですが、申し込みするときには、カードでメンバーズカードじゃないんですが、使いますよね。例えば東大井区民集会所だけは使えないと言われたんですが、何か理由があるのか。もしあるのであれば教えていただきたいんですが。電話とまた窓口に来てくださいということで。","respondent":"久保田行財政改革担当課長","answer":"東大井についてですけれども、規則上では、東大井区民集会所については、使用申請書ということになっておりますので、予約システムでは申し込みができないという規定になっておりますので、多分カードというものが使えないのかなと思っているんですけれども。","voiceIndex":65,"id":"exchange-032"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?Template=document&Id=5870#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=14&TermStart=2009-01-01&TermEnd=2009-12-31"}],"sourceMeta":{"pages":0,"characters":34486,"voices":71}},{"id":"h21-20090929-15","meetingId":"h21-cm09","date":"2009年9月29日","dateIso":"2009-09-29","committee":"環境対策特別委員会","time":"午前１０時０３分～午前１１時３６分","status":"正式会議録","sourceType":"formal","overview":"環境対策特別委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を0件抜き出しています。","hasFullText":true,"topics":[],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?Template=document&Id=6174#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=15&TermStart=2009-01-01&TermEnd=2009-12-31"}],"sourceMeta":{"pages":0,"characters":1215,"voices":8}}]);
